INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c687abe8-7c65-467c-9e4b-32164d9bada4', '0192cbff-b339-5c2b-bd65-0d0b74a9ed56', 'රජුට අයත් ඉඩම්වල වගා කිරීම', 'රජුට අයත් ඉඩම්වල වගා කිරීම', NULL, 'sanitized', 'v1', 2, 0);
