INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bcfe3483-acf9-4373-8d59-330839b70609', '1773771f-0e5f-5db7-b663-2d3db256d52a', 'වේවැල්කැටිය සෙල්ලිපියයි.', 'වේවැල්කැටිය සෙල්ලිපියයි.', NULL, 'sanitized', 'v1', 2, 0);
