INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f8ca666-e09a-42b7-b041-1decc9e4d6bd', 'bdc69db7-8138-51c6-80e2-ae670c4c6cd9', 'වන සතුන්ගේ වාසස්ථාන ආරක්ෂා කර ගැනීමය.', 'වන සතුන්ගේ වාසස්ථාන ආරක්ෂා කර ගැනීමය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ee36c266-a842-49f3-917d-7dab4b713574', 'bdc69db7-8138-51c6-80e2-ae670c4c6cd9', 'වගාබිම්වල පස නිසරු වීම වළක්වා ගැනීමය.', 'වගාබිම්වල පස නිසරු වීම වළක්වා ගැනීමය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('881fc8ba-57b3-5d34-b1d8-01a57036e930', '02e01737-d257-5d5a-ae8e-59c814d0dac7', 16, '<p>ජෝතිය සිටුවරයාගේ කැරැල්ල ඇති වූයේ මින් කිනම් රාජ්‍ය සමයකදීද?</p>', '<p>ජෝතිය සිටුවරයාගේ කැරැල්ල ඇති වූයේ මින් කිනම් රාජ්‍ය සමයකදීද?</p>', NULL, 'කෝට්ටේ යුගයේ හයවන පරාක්‍රමබාහු රජ සමයේදී උඩරට ප්‍රදේශයේ පාලකයා වූ ජෝතිය සිටු විසින් රජුට එරෙහිව කැරැල්ලක් ඇති කරන ලදී.', 'කෝට්ටේ යුගයේ හයවන පරාක්‍රමබාහු රජ සමයේදී උඩරට ප්‍රදේශයේ පාලකයා වූ ජෝතිය සිටු විසින් රජුට එරෙහිව කැරැල්ලක් ඇති කරන ලදී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
