INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b476e7e6-161d-5b0c-84cb-77b3fd529021', '02e01737-d257-5d5a-ae8e-59c814d0dac7', 24, '<p>සූරියමල් ව්‍යාපාරය සම්බන්ධ නිවැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>සූරියමල් ව්‍යාපාරය සම්බන්ධ නිවැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'පොපිමල් ව්‍යාපාරයට විකල්පයක් ලෙස ඇරඹි සූරියමල් ව්‍යාපාරය, බ්‍රිතාන්‍ය අධිරාජ්‍ය විරෝධී සහ ශ්‍රී ලංකාවේ නිදහස උදෙසා වූ ප්‍රචාරක ව්‍යාපාරයක් ලෙස ක්‍රියාත්මක විය.', 'පොපිමල් ව්‍යාපාරයට විකල්පයක් ලෙස ඇරඹි සූරියමල් ව්‍යාපාරය, බ්‍රිතාන්‍ය අධිරාජ්‍ය විරෝධී සහ ශ්‍රී ලංකාවේ නිදහස උදෙසා වූ ප්‍රචාරක ව්‍යාපාරයක් ලෙස ක්‍රියාත්මක විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1a0bf52b-5819-495b-8330-e0045f8111ca', 'b476e7e6-161d-5b0c-84cb-77b3fd529021', 'පළමුවන ලෝක මහා සංග්‍රාමයේදී ආබාධිත බ්‍රිතාන්‍ය සොල්දාදුවන්ට ආධාර එකතු කිරීමේ ව්‍යාපාරයක් වීම', 'පළමුවන ලෝක මහා සංග්‍රාමයේදී ආබාධිත බ්‍රිතාන්‍ය සොල්දාදුවන්ට ආධාර එකතු කිරීමේ ව්‍යාපාරයක් වීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4ee12f78-ce73-4c95-884d-39bbadaf7f38', 'b476e7e6-161d-5b0c-84cb-77b3fd529021', 'ශ්‍රී ලංකාවේ නිදහස සඳහා ගෙන ගිය උද්ඝෝෂණ වල ප්‍රචාරක ව්‍යාපාරයක් වීම', 'ශ්‍රී ලංකාවේ නිදහස සඳහා ගෙන ගිය උද්ඝෝෂණ වල ප්‍රචාරක ව්‍යාපාරයක් වීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a7a15c29-bf69-409d-b550-d2b7a3da18dc', 'b476e7e6-161d-5b0c-84cb-77b3fd529021', 'යුධ සාමදාන දිනය සැමරීම සඳහා සූරියමල් විකිණීමේ ව්‍යාපාරය ආරම්භ කිරීම', 'යුධ සාමදාන දිනය සැමරීම සඳහා සූරියමල් විකිණීමේ ව්‍යාපාරය ආරම්භ කිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bac4a953-dc66-43d3-8c16-38d93aec4e7f', 'b476e7e6-161d-5b0c-84cb-77b3fd529021', 'සූරියමල් විකිණීමෙන් ලැබෙන මුදල් බ්‍රිතාන්‍ය මහා භාණ්ඩාගාරයට යැවීමට කටයුතු කිරීම', 'සූරියමල් විකිණීමෙන් ලැබෙන මුදල් බ්‍රිතාන්‍ය මහා භාණ්ඩාගාරයට යැවීමට කටයුතු කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d40a6fe5-0b79-54ae-bed1-b063d6bea0ca', '02e01737-d257-5d5a-ae8e-59c814d0dac7', 25, '<p>ඩොනමෝර් ආණ්ඩුක්‍රමයෙන් හඳුන්වා දෙනු ලැබූ ලක්ෂණයක් වන්නේ,</p>', '<p>ඩොනමෝර් ආණ්ඩුක්‍රමයෙන් හඳුන්වා දෙනු ලැබූ ලක්ෂණයක් වන්නේ,</p>', NULL, '1931 ඩොනමෝර් ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් ලාංකිකයන්ට සර්වජන ඡන්ද බලය (Universal Franchise) ප්‍රථම වරට හඳුන්වා දෙන ලදී.', '1931 ඩොනමෝර් ආණ්ඩුක්‍රම ව්‍යවස්ථාව මගින් ලාංකිකයන්ට සර්වජන ඡන්ද බලය (Universal Franchise) ප්‍රථම වරට හඳුන්වා දෙන ලදී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
