INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4bafb238-4614-5ca0-bf75-2eac07016fca', '02e01737-d257-5d5a-ae8e-59c814d0dac7', 30, '<p>පුනරුද සමයේ කලා ශිල්ප ක්ෂේත්‍රයේ ඇති වූ වෙනස්කමක් වන්නේ,</p>', '<p>පුනරුද සමයේ කලා ශිල්ප ක්ෂේත්‍රයේ ඇති වූ වෙනස්කමක් වන්නේ,</p>', NULL, 'ආගමික රාමුවෙන් මිදී මානවවාදය සහ ලෞකික රසවින්දනය පදනම් කරගත් කලා කෘති බිහිවීම පුනරුද සමයේ ප්‍රධාන ලක්ෂණයකි.', 'ආගමික රාමුවෙන් මිදී මානවවාදය සහ ලෞකික රසවින්දනය පදනම් කරගත් කලා කෘති බිහිවීම පුනරුද සමයේ ප්‍රධාන ලක්ෂණයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3f488ed2-b55e-4ed2-9e9c-1ca56fd37a1b', '4bafb238-4614-5ca0-bf75-2eac07016fca', 'ලෞකික රස වින්දනයට මුල් තැන දෙන කලා කෘති බිහිවීම ය.', 'ලෞකික රස වින්දනයට මුල් තැන දෙන කලා කෘති බිහිවීම ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6a0e71fa-fd6b-4786-9ba5-904e4734a2f0', '4bafb238-4614-5ca0-bf75-2eac07016fca', 'ශිල්පීන් අයත් වූ ශ්‍රේණිවල නමින් කලා නිර්මාණ එළි දැක්වීම ය.', 'ශිල්පීන් අයත් වූ ශ්‍රේණිවල නමින් කලා නිර්මාණ එළි දැක්වීම ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ba86dc0c-3dac-410c-8744-4151ef9f7a2b', '4bafb238-4614-5ca0-bf75-2eac07016fca', 'කලා කෘතිවලට අනුග්‍රහ දැක්වීමේ ශක්තිය පල්ලියට පමණක් තිබීම ය.', 'කලා කෘතිවලට අනුග්‍රහ දැක්වීමේ ශක්තිය පල්ලියට පමණක් තිබීම ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1e317f91-1727-4b5f-899d-36c819a287cf', '4bafb238-4614-5ca0-bf75-2eac07016fca', 'කලා කෘති හා කලා ශිල්ප ආගමටම පමණක් නැඹුරු වීමය.', 'කලා කෘති හා කලා ශිල්ප ආගමටම පමණක් නැඹුරු වීමය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a8cbc2a3-87a4-508b-b3db-22b41db11e97', '02e01737-d257-5d5a-ae8e-59c814d0dac7', 31, '<p>කාර්මික විප්ලව සමයේ බ්‍රිතාන්‍යයේ ඉඩම් කොටු කිරීමේ ව්‍යාපාරය මගින් සිදු වූයේ,</p>', '<p>කාර්මික විප්ලව සමයේ බ්‍රිතාන්‍යයේ ඉඩම් කොටු කිරීමේ ව්‍යාපාරය මගින් සිදු වූයේ,</p>', NULL, 'විසිරී තිබූ කුඩා ඉඩම් කැබලි එකතු කර, වැටවල් ගසා විශාල ගොවිපළවල් (Enclosures) බවට පත්කිරීම ඉඩම් කොටු කිරීමේ ව්‍යාපාරය මගින් සිදුවිය.', 'විසිරී තිබූ කුඩා ඉඩම් කැබලි එකතු කර, වැටවල් ගසා විශාල ගොවිපළවල් (Enclosures) බවට පත්කිරීම ඉඩම් කොටු කිරීමේ ව්‍යාපාරය මගින් සිදුවිය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('521ae496-31f5-4a8e-91df-8b9f7e54cb8e', 'a8cbc2a3-87a4-508b-b3db-22b41db11e97', 'විශාල ඉඩම් කුඩා කොටස් වලට බෙදා වෙන් කිරීම ය.', 'විශාල ඉඩම් කුඩා කොටස් වලට බෙදා වෙන් කිරීම ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a9d7a31e-12aa-463d-8a06-36b8b5dbad29', 'a8cbc2a3-87a4-508b-b3db-22b41db11e97', 'දිළින්දන් සතු ඉඩම් රදළයන් විසින් අත්පත් කරගැනීම ය.', 'දිළින්දන් සතු ඉඩම් රදළයන් විසින් අත්පත් කරගැනීම ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b321b68f-c8a1-4ce5-90a5-55f1f3796b53', 'a8cbc2a3-87a4-508b-b3db-22b41db11e97', 'කාර්මික අවශ්‍යතා සඳහා ග්‍රාමීය ඉඩම් යොදා ගැනීම ය.', 'කාර්මික අවශ්‍යතා සඳහා ග්‍රාමීය ඉඩම් යොදා ගැනීම ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7f00173b-24d3-4b05-b128-cb5bb9699562', 'a8cbc2a3-87a4-508b-b3db-22b41db11e97', 'සුළු ගොවියන් සතු කුඩා ඉඩම් එකතු කර විශාල ගොවිපළවල් සකස් කිරීම ය.', 'සුළු ගොවියන් සතු කුඩා ඉඩම් එකතු කර විශාල ගොවිපළවල් සකස් කිරීම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('61320d56-92a1-5be8-88ef-89fc1f4f8980', '02e01737-d257-5d5a-ae8e-59c814d0dac7', 32, '<p>පහත අදහස් ඇතුළත් දේශපාලන දර්ශනය ලොවපුරා ව්‍යාප්ත වූයේ කිනම් විප්ලවයෙන් පසුද?<br><br>• සමාජය සතු ධන සම්පත් පිළිබඳ පොදු අයිතිය පිළිගැනීම<br>• සෑම පුරවැසියකුටම තම කුසලතා ඉහළ නංවා ගැනීමට සමාන ඉඩක් ලබාදීම<br>• නිෂ්පාදන ඵල සියලු දෙනාටම බෙදී යාම</p>', '<p>පහත අදහස් ඇතුළත් දේශපාලන දර්ශනය ලොවපුරා ව්‍යාප්ත වූයේ කිනම් විප්ලවයෙන් පසුද?<br><br>• සමාජය සතු ධන සම්පත් පිළිබඳ පොදු අයිතිය පිළිගැනීම<br>• සෑම පුරවැසියකුටම තම කුසලතා ඉහළ නංවා ගැනීමට සමාන ඉඩක් ලබාදීම<br>• නිෂ්පාදන ඵල සියලු දෙනාටම බෙදී යාම</p>', NULL, '1917 රුසියානු විප්ලවයෙන් පසුව සමාජවාදී අදහස් සහ පොදු දේපළ අයිතිය පිළිබඳ දේශපාලන දර්ශනය ලොව පුරා ව්‍යාප්ත විය.', '1917 රුසියානු විප්ලවයෙන් පසුව සමාජවාදී අදහස් සහ පොදු දේපළ අයිතිය පිළිබඳ දේශපාලන දර්ශනය ලොව පුරා ව්‍යාප්ත විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
