INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('af6303a4-bfb2-413c-b437-4ab81420fcdd', 'e79f32d9-de4d-535c-8875-bf08967f7ed8', 'පාඨමාලාව, පිළියෙළ, සන්තුෂ්ටිය, තොටු පොළ', 'පාඨමාලාව, පිළියෙළ, සන්තුෂ්ටිය, තොටු පොළ', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ef15446e-d921-52de-8b20-c58f01c85428', '02f097bf-b909-5f6f-b953-3348e94db9ad', 8, '<p>මුදුන, ගෞරව, දීකිරි, මේඝ යන වචන වල පළමු අකුරෙහි අන්තර්ගත පිල්ලම අනුපිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', '<p>මුදුන, ගෞරව, දීකිරි, මේඝ යන වචන වල පළමු අකුරෙහි අන්තර්ගත පිල්ලම අනුපිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', NULL, '''මු'' - කෙටි පාපිල්ල, ''ගෞ'' - කොම්බුව හා ගයනුකිත්ත, ''දී'' - දීර්ඝ ඉස්පිල්ල, ''මේ'' - කොම්බුව හා දීර්ඝත්ව ලක්ෂණය (හල්කිරිම).', '''මු'' - කෙටි පාපිල්ල, ''ගෞ'' - කොම්බුව හා ගයනුකිත්ත, ''දී'' - දීර්ඝ ඉස්පිල්ල, ''මේ'' - කොම්බුව හා දීර්ඝත්ව ලක්ෂණය (හල්කිරිම).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('67038f08-f3d7-4df1-b219-2a6048e5a050', 'ef15446e-d921-52de-8b20-c58f01c85428', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, දීර්ඝ ඉස්පිල්ල, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, දීර්ඝ ඉස්පිල්ල, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('96c5be22-ed3f-4bdb-b9f1-98439b515b4d', 'ef15446e-d921-52de-8b20-c58f01c85428', 'කෙටි පාපිල්ල, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය, දීර්ඝ ඉස්පිල්ල, කොම්බුව හා ගයනුකිත්ත', 'කෙටි පාපිල්ල, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය, දීර්ඝ ඉස්පිල්ල, කොම්බුව හා ගයනුකිත්ත', NULL, 'sanitized', 'v1', 1, 0);
