INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ce408859-930c-4615-a3d4-610a616151fb', 'ef15446e-d921-52de-8b20-c58f01c85428', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය, දීර්ඝ ඉස්පිල්ල', 'කෙටි පාපිල්ල, කොම්බුව හා ගයනුකිත්ත, කොම්බුව හා දීර්ඝත්ව ලක්ෂණය, දීර්ඝ ඉස්පිල්ල', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2063a132-45fb-59e7-b1b7-df9c7d01e411', '02f097bf-b909-5f6f-b953-3348e94db9ad', 9, '<p>''අධිකාරි'' යන පදයෙහි අන්තර්ගත ව්‍යඤ්ජන අක්ෂර වර්ග වනුයේ,</p>', '<p>''අධිකාරි'' යන පදයෙහි අන්තර්ගත ව්‍යඤ්ජන අක්ෂර වර්ග වනුයේ,</p>', NULL, 'මෙහි අන්තර්ගත ව්‍යංජන වන්නේ ධ් (දන්තජ), ක් (කණ්ඨජ) සහ ර (මුර්ධජ) ය.', 'මෙහි අන්තර්ගත ව්‍යංජන වන්නේ ධ් (දන්තජ), ක් (කණ්ඨජ) සහ ර (මුර්ධජ) ය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
