INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f5b99446-4182-4475-ad07-6e64b3c3eec3', 'dd83ee4c-a839-5a77-ae54-50786ce92eba', 'ජීවන අද්දැකීම් වනාහි නිර්මාණකරණයේ දී ඉතා වැදගත්ය.', 'ජීවන අද්දැකීම් වනාහි නිර්මාණකරණයේ දී ඉතා වැදගත්ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dee4700d-209c-4406-a96a-dffc3b344c70', 'dd83ee4c-a839-5a77-ae54-50786ce92eba', 'සාමූහික ක්‍රියාකාරකම් සියල්ල හුදකලාවම සිදු කිරීම පහසුය.', 'සාමූහික ක්‍රියාකාරකම් සියල්ල හුදකලාවම සිදු කිරීම පහසුය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1c9f4fda-a382-5020-b044-3cb7ac4d278b', '02f097bf-b909-5f6f-b953-3348e94db9ad', 26, '<p>පහත අදහසට වඩාත්ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>පිහිටක් බලාපොරොත්තුවෙන් ගිය විට විපත්තියකට මුහුණ පෑම</p>', '<p>පහත අදහසට වඩාත්ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>පිහිටක් බලාපොරොත්තුවෙන් ගිය විට විපත්තියකට මුහුණ පෑම</p>', NULL, 'යහපතක් අපේක්ෂාවෙන් ගිය තැනකදී ඊට හාත්පසින්ම වෙනස් වූ විනාශයක් සිදුවීම මෙම ප්‍රස්තාව පිරුළෙන් අදහස් කෙරේ.', 'යහපතක් අපේක්ෂාවෙන් ගිය තැනකදී ඊට හාත්පසින්ම වෙනස් වූ විනාශයක් සිදුවීම මෙම ප්‍රස්තාව පිරුළෙන් අදහස් කෙරේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('44f24ede-4f8b-4251-bd43-7f75f0d7cac9', '1c9f4fda-a382-5020-b044-3cb7ac4d278b', 'නැග්ග ඉණි මඟට පයින් ගහනවා වාගේ.', 'නැග්ග ඉණි මඟට පයින් ගහනවා වාගේ.', NULL, 'sanitized', 'v1', 0, 1);
