INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('33fd2b84-8c66-5731-a269-9822f02f54f5', '02f097bf-b909-5f6f-b953-3348e94db9ad', 29, '<p>ව්‍යාකරණානුකූලව නිවැරදි වාක්‍යය තෝරන්න.</p>', '<p>ව්‍යාකරණානුකූලව නිවැරදි වාක්‍යය තෝරන්න.</p>', NULL, '''වැසියෝ'' යන උක්ත බහුවචන පදයට අනුකූලව ''යුත්තාහ'' යන බහුවචන ආඛ්‍යාතය නිවැරදිව යෙදී ඇත.', '''වැසියෝ'' යන උක්ත බහුවචන පදයට අනුකූලව ''යුත්තාහ'' යන බහුවචන ආඛ්‍යාතය නිවැරදිව යෙදී ඇත.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d2d5e18e-da56-4cf1-9c4b-9ec62e6279af', '33fd2b84-8c66-5731-a269-9822f02f54f5', 'රටක වැසියෝ සමගියෙන් ජීවත් විය යුත්තාහ.', 'රටක වැසියෝ සමගියෙන් ජීවත් විය යුත්තාහ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f4a0e7eb-3b00-4774-a1f4-507c5256009c', '33fd2b84-8c66-5731-a269-9822f02f54f5', 'විකුමැත්තන් සැමවිටම නුවණැත්තන් නො වෙති.', 'විකුමැත්තන් සැමවිටම නුවණැත්තන් නො වෙති.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('80719ce5-b60c-41c1-826f-a9d9bd61e7dc', '33fd2b84-8c66-5731-a269-9822f02f54f5', 'ගොවියෝ කුඹුරු සාද්දී ගෙවිලියෝ ආහාර රැගෙන යති.', 'ගොවියෝ කුඹුරු සාද්දී ගෙවිලියෝ ආහාර රැගෙන යති.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1200fb6c-d10b-44e7-a2d8-482a93ff33ca', '33fd2b84-8c66-5731-a269-9822f02f54f5', 'ප්‍රකට ගායකයෙක් වූ සනත් නන්දසිරි දක්ෂ සංගීතඥයෙක් ද විය.', 'ප්‍රකට ගායකයෙක් වූ සනත් නන්දසිරි දක්ෂ සංගීතඥයෙක් ද විය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3b8d559b-82f9-5da6-b475-7f1e249434cb', '02f097bf-b909-5f6f-b953-3348e94db9ad', 30, '<p>ව්‍යාකරණානුකූලව නිවැරදි වාක්‍යය තෝරන්න.</p>', '<p>ව්‍යාකරණානුකූලව නිවැරදි වාක්‍යය තෝරන්න.</p>', NULL, 'රාජ්‍ය නායකයා වැනි ගෞරවාන්විත තනතුරු හැඳින්වීමේදී උක්තය ඒකවචන වුවද ඊට ගෞරවයක් වශයෙන් ආඛ්‍යාතය බහුවචනයෙන් (වෙති) තැබීම නිවැරදිය.', 'රාජ්‍ය නායකයා වැනි ගෞරවාන්විත තනතුරු හැඳින්වීමේදී උක්තය ඒකවචන වුවද ඊට ගෞරවයක් වශයෙන් ආඛ්‍යාතය බහුවචනයෙන් (වෙති) තැබීම නිවැරදිය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
