INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e566c45f-87bc-42b3-ace1-e0ae2a058560', '3b8d559b-82f9-5da6-b475-7f1e249434cb', '''රාජ්‍ය නායකයා විදේශ ගත වෙති'' යි වාර්තාකරුවෝ කීහ.', '''රාජ්‍ය නායකයා විදේශ ගත වෙති'' යි වාර්තාකරුවෝ කීහ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f146f4be-9292-434f-b596-4dd30f547be2', '3b8d559b-82f9-5da6-b475-7f1e249434cb', 'නිවේදකයා ද නිවේදිකාව ද වේදිකාව මතට නැග්ගා ය.', 'නිවේදකයා ද නිවේදිකාව ද වේදිකාව මතට නැග්ගා ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('bda3c34e-22c6-529c-aa7f-a142e15216d9', '02f097bf-b909-5f6f-b953-3348e94db9ad', 31, '<p>ගුණපාල නිවටයකු .................. හිස නැමුවේ ය.<br>අසරණ දරුවන් .................. පිළිසරණක් වන්න.<br>වැද්දා සිය බල්ලා .................. වනයට ගියේය.<br>ආරක්ෂක අමාත්‍යාංශය රටෙහි ආරක්ෂාව .................. පිහිටුවා ඇත.<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද?</p>', '<p>ගුණපාල නිවටයකු .................. හිස නැමුවේ ය.<br>අසරණ දරුවන් .................. පිළිසරණක් වන්න.<br>වැද්දා සිය බල්ලා .................. වනයට ගියේය.<br>ආරක්ෂක අමාත්‍යාංශය රටෙහි ආරක්ෂාව .................. පිහිටුවා ඇත.<br><br>ඉහත වාක්‍ය වල හිස් තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද?</p>', NULL, 'අනුපිළිවෙලින්: නිවටයකු ''මෙන්'', දරුවන් ''උදෙසා/වෙනුවෙන්'', බල්ලා ''කැටුව'', ආරක්ෂාව ''උදෙසා/වෙනුවෙන්'' යෙදීම අර්ථවත් වේ.', 'අනුපිළිවෙලින්: නිවටයකු ''මෙන්'', දරුවන් ''උදෙසා/වෙනුවෙන්'', බල්ලා ''කැටුව'', ආරක්ෂාව ''උදෙසා/වෙනුවෙන්'' යෙදීම අර්ථවත් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
