INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('be39fa7d-d286-4fe9-8f15-43fa4119101c', '24e7d0cb-5f6b-5eb6-af67-77806b59287b', 'සෙමින් සෙමින් ඇවිදිමින් වතුර බාල්දිය ගෙනෙන්න.', 'සෙමින් සෙමින් ඇවිදිමින් වතුර බාල්දිය ගෙනෙන්න.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9c0a9ff9-6c06-5a2a-92e1-f24f0d38db1b', '02f097bf-b909-5f6f-b953-3348e94db9ad', 33, '<p>ස්ථිරවාසීතාව යනුවෙන් හඳුන්වන්නේ,</p>', '<p>ස්ථිරවාසීතාව යනුවෙන් හඳුන්වන්නේ,</p>', NULL, 'ස්ථිරවාසීතාව යනු තැනින් තැනට යන සංචාරක දිවිය අතහැර එක් නිශ්චිත ස්ථානයක ස්ථිරවම දිගු කාලයක් පදිංචි වී සිටීමයි.', 'ස්ථිරවාසීතාව යනු තැනින් තැනට යන සංචාරක දිවිය අතහැර එක් නිශ්චිත ස්ථානයක ස්ථිරවම දිගු කාලයක් පදිංචි වී සිටීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7484b54a-ae02-4f26-8430-581367dd108f', '9c0a9ff9-6c06-5a2a-92e1-f24f0d38db1b', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජීවිතයෙන් මිදී නිවාස තනා ගැනීම යි.', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජීවිතයෙන් මිදී නිවාස තනා ගැනීම යි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8705a240-ff4a-440a-bcf3-07cf04c884b3', '9c0a9ff9-6c06-5a2a-92e1-f24f0d38db1b', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජිවිතයේ දී තාවකාලික නිවාස තනා ගැනීම යි.', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජිවිතයේ දී තාවකාලික නිවාස තනා ගැනීම යි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ff636219-4bb9-4ab3-8063-eeb85403a86b', '9c0a9ff9-6c06-5a2a-92e1-f24f0d38db1b', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජීවිතයෙන් මිදී එක් තැනක දිගුකලක් වාසය කිරීම යි.', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් සංචාරක ජීවිතයෙන් මිදී එක් තැනක දිගුකලක් වාසය කිරීම යි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('615e255b-7292-4e8a-a8b8-39dcd5b1350e', '9c0a9ff9-6c06-5a2a-92e1-f24f0d38db1b', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් තැනින් තැන සංචාරය කරමින් ජීවත් වීම යි.', 'ප්‍රාග් ඓතිහාසික යුගයේ මිනිසුන් තැනින් තැන සංචාරය කරමින් ජීවත් වීම යි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5e89bb69-8778-5fea-9801-b1266d73154b', '02f097bf-b909-5f6f-b953-3348e94db9ad', 34, '<p>පහත සඳහන් කවියේ හතරවන පදය නිවැරදිව දැක්වෙන වරණය තෝරන්න.<br><br>ලීල් නැතිව නිසරුව තෙපලන්නේ<br>මහල්ල නුඹගේ හිමි ද අසන්නේ<br>වාල් තමාවත් ඇද්ද ඉතින්නේ<br>....................................</p>', '<p>පහත සඳහන් කවියේ හතරවන පදය නිවැරදිව දැක්වෙන වරණය තෝරන්න.<br><br>ලීල් නැතිව නිසරුව තෙපලන්නේ<br>මහල්ල නුඹගේ හිමි ද අසන්නේ<br>වාල් තමාවත් ඇද්ද ඉතින්නේ<br>....................................</p>', NULL, 'සඳකිඳුරු දා කවෙහි එන මෙම පද්‍යයේ නිවැරදි අවසන් පාදය ''වාල් විඳින දුක මෙනුඹ විඳින්නේ'' යන්නයි.', 'සඳකිඳුරු දා කවෙහි එන මෙම පද්‍යයේ නිවැරදි අවසන් පාදය ''වාල් විඳින දුක මෙනුඹ විඳින්නේ'' යන්නයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('153449a3-514b-4b82-b418-ddea5e91fe3c', '5e89bb69-8778-5fea-9801-b1266d73154b', 'හැම කල් මළ දා දෝ සැප වන්නේ', 'හැම කල් මළ දා දෝ සැප වන්නේ', NULL, 'sanitized', 'v1', 0, 1);
