INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5a89e977-5fdb-5857-b2b3-906e7dfdd45f', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 2, '<p>LP ගෑස්වල ප්‍රධාන සංඝටක ලෙස අඩංගු හයිඩ්‍රොකාබන වනුයේ,</p>', '<p>LP ගෑස්වල ප්‍රධාන සංඝටක ලෙස අඩංගු හයිඩ්‍රොකාබන වනුයේ,</p>', NULL, 'ද්‍රව කරන ලද ඛනිජ තෙල් වායුව (LP Gas - Liquefied Petroleum Gas) ප්‍රධාන වශයෙන් ප්‍රොපේන් ($C_3H_8$) සහ බියුටේන් ($C_4H_{10}$) යන වායුමය හයිඩ්‍රොකාබන වල මිශ්‍රණයකින් සමන්විත වේ.[cite: 11]', 'ද්‍රව කරන ලද ඛනිජ තෙල් වායුව (LP Gas - Liquefied Petroleum Gas) ප්‍රධාන වශයෙන් ප්‍රොපේන් ($C_3H_8$) සහ බියුටේන් ($C_4H_{10}$) යන වායුමය හයිඩ්‍රොකාබන වල මිශ්‍රණයකින් සමන්විත වේ.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('283fe77c-c542-4047-98bd-cdd9007db148', '5a89e977-5fdb-5857-b2b3-906e7dfdd45f', 'මෙතේන් හා එතේන් ය.', 'මෙතේන් හා එතේන් ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('38b2cb77-2050-4384-bdad-7efc5adefe24', '5a89e977-5fdb-5857-b2b3-906e7dfdd45f', 'ප්‍රොපේන් හා බියුටේන් ය.', 'ප්‍රොපේන් හා බියුටේන් ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('788374cf-7d29-4116-b630-b64d70b29f4d', '5a89e977-5fdb-5857-b2b3-906e7dfdd45f', 'බියුටේන් හා පෙන්ටේන් ය.', 'බියුටේන් හා පෙන්ටේන් ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1f0b46ee-f21d-4827-84cd-67b3119807f5', '5a89e977-5fdb-5857-b2b3-906e7dfdd45f', 'ප්‍රොපේන් හා පෙන්ටේන් ය.', 'ප්‍රොපේන් හා පෙන්ටේන් ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('92608b96-2e4e-5766-840d-8eb672ac5af7', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 3, '<p>කාර්ය ප්‍රමාණයේ ඒකකය කුමක්ද?</p>', '<p>කාර්ය ප්‍රමාණයේ ඒකකය කුමක්ද?</p>', NULL, 'කාර්යය = බලය $\times$ විස්ථාපනය. බලයේ මූලික ඒකකය $kg~m~s^{-2}$ (නිව්ටන්) වේ. විස්ථාපනයේ ඒකකය $m$ වේ. එබැවින් කාර්යයේ ඒකකය (ජූල්) මූලික ඒකක වලින් දැක්වූ විට $(kg~m~s^{-2}) \times m = kg~m^2s^{-2}$ වේ.[cite: 11]', 'කාර්යය = බලය $\times$ විස්ථාපනය. බලයේ මූලික ඒකකය $kg~m~s^{-2}$ (නිව්ටන්) වේ. විස්ථාපනයේ ඒකකය $m$ වේ. එබැවින් කාර්යයේ ඒකකය (ජූල්) මූලික ඒකක වලින් දැක්වූ විට $(kg~m~s^{-2}) \times m = kg~m^2s^{-2}$ වේ.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
