INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('49a6be54-930f-415c-bdb5-93d226d7b1af', '3921ec8b-17c2-5cc9-97b7-c98c21ecee56', 'ඉලෙක්ට්‍රෝන හා ප්‍රෝටෝන සංඛ්‍යාවේ එකතුව', 'ඉලෙක්ට්‍රෝන හා ප්‍රෝටෝන සංඛ්‍යාවේ එකතුව', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('471d9f48-2479-4116-94f0-d64f33fdc687', '3921ec8b-17c2-5cc9-97b7-c98c21ecee56', 'ප්‍රෝටෝන හා නියුට්‍රෝන සංඛ්‍යාවේ එකතුව', 'ප්‍රෝටෝන හා නියුට්‍රෝන සංඛ්‍යාවේ එකතුව', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9ce8ec1e-7be1-5478-aec7-1bfb0a4d7475', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 8, '<p>මෝටර් රථ එන්ජිමක නිපදවන අධික තාපය ඉවත් කිරීම සඳහා සිසිලන කාරකයක් ලෙස ජලය භාවිත කිරීමට හේතු වන්නේ ජලය සතු කුමන ගුණාංගයද?</p>', '<p>මෝටර් රථ එන්ජිමක නිපදවන අධික තාපය ඉවත් කිරීම සඳහා සිසිලන කාරකයක් ලෙස ජලය භාවිත කිරීමට හේතු වන්නේ ජලය සතු කුමන ගුණාංගයද?</p>', NULL, 'ජලයට ඉතා ඉහළ විශිෂ්ට තාප ධාරිතාවක් (High specific heat capacity) ඇත. එනම්, ජලයේ උෂ්ණත්වය සුළු ප්‍රමාණයකින් ඉහළ යාමට විශාල තාප ප්‍රමාණයක් අවශෝෂණය කරගත හැක. මේ නිසා එය හොඳ සිසිලනකාරකයක් (Coolant) ලෙස යොදා ගනී.[cite: 11]', 'ජලයට ඉතා ඉහළ විශිෂ්ට තාප ධාරිතාවක් (High specific heat capacity) ඇත. එනම්, ජලයේ උෂ්ණත්වය සුළු ප්‍රමාණයකින් ඉහළ යාමට විශාල තාප ප්‍රමාණයක් අවශෝෂණය කරගත හැක. මේ නිසා එය හොඳ සිසිලනකාරකයක් (Coolant) ලෙස යොදා ගනී.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5c7c6389-ead9-4eec-8a49-e25d9c51c7cb', '9ce8ec1e-7be1-5478-aec7-1bfb0a4d7475', 'ඉහළ විශිෂ්ට තාප ධාරිතාවක් තිබීම', 'ඉහළ විශිෂ්ට තාප ධාරිතාවක් තිබීම', NULL, 'sanitized', 'v1', 0, 1);
