INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('30115d0b-11b2-45e0-ab8d-76b0f6afeed8', '9ce8ec1e-7be1-5478-aec7-1bfb0a4d7475', 'අවර්ණ ද්‍රවයක් වීම', 'අවර්ණ ද්‍රවයක් වීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0f815b6f-4d50-4be5-8f1e-9c93bde35315', '9ce8ec1e-7be1-5478-aec7-1bfb0a4d7475', 'ඉහළ ඝනත්වයක් පැවතීම', 'ඉහළ ඝනත්වයක් පැවතීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('be4e32e0-c7a2-5722-81c1-75e71571769d', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 9, '<p>ආහාර ජීරණ ක්‍රියාවලියේදී ලිපි තෛලෝද කරණයට අවශ්‍ය වන පිත නිපද වෙන්නේ,</p>', '<p>ආහාර ජීරණ ක්‍රියාවලියේදී ලිපි තෛලෝද කරණයට අවශ්‍ය වන පිත නිපද වෙන්නේ,</p>', NULL, 'මිනිස් සිරුරේ පිත (Bile) නිපදවනු ලබන්නේ අක්මාව (Liver) මගිනි. නිපදවන පිත තාවකාලිකව ගබඩා කර තබා ගන්නේ පිත්තාශයේ (Gallbladder) ය.[cite: 11]', 'මිනිස් සිරුරේ පිත (Bile) නිපදවනු ලබන්නේ අක්මාව (Liver) මගිනි. නිපදවන පිත තාවකාලිකව ගබඩා කර තබා ගන්නේ පිත්තාශයේ (Gallbladder) ය.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
