INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4d0c0bd2-0088-5d32-8366-a1c9e3524d3e', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 11, '<p>සාන්ද්‍රණය $1.0~mol~dm^{-3}$ වන සෝඩියම් ක්ලෝරයිඩ් ද්‍රාවණ $100~cm^{3}$ ක අඩංගු NaCl ස්කන්ධය කොපමණද?<br>$(Na=23, Cl=35.5)$</p>', '<p>සාන්ද්‍රණය $1.0~mol~dm^{-3}$ වන සෝඩියම් ක්ලෝරයිඩ් ද්‍රාවණ $100~cm^{3}$ ක අඩංගු NaCl ස්කන්ධය කොපමණද?<br>$(Na=23, Cl=35.5)$</p>', NULL, 'මවුලික ස්කන්ධය $NaCl = 23 + 35.5 = 58.5~gmol^{-1}$.<br>මවුල ගණන ($n$) = සාන්ද්‍රණය ($C$) $\times$ පරිමාව ($V$)<br>$n = 1.0~mol~dm^{-3} \times (100 / 1000)~dm^3 = 0.1~mol$.<br>ස්කන්ධය ($m$) = $n \times M = 0.1~mol \times 58.5~gmol^{-1} = 5.85~g$.[cite: 11]', 'මවුලික ස්කන්ධය $NaCl = 23 + 35.5 = 58.5~gmol^{-1}$.<br>මවුල ගණන ($n$) = සාන්ද්‍රණය ($C$) $\times$ පරිමාව ($V$)<br>$n = 1.0~mol~dm^{-3} \times (100 / 1000)~dm^3 = 0.1~mol$.<br>ස්කන්ධය ($m$) = $n \times M = 0.1~mol \times 58.5~gmol^{-1} = 5.85~g$.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
