INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b703ab81-06c3-5b9d-aa54-36b9aef07eb5', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 16, '<p>කාබන් ඩයොක්සයිඩ් 22 g ක අඩංගු $CO_{2}$ අණු සංඛ්‍යාව කොපමණද?<br>($C=12$, $O=16$, ඇවගාඩ්‍රෝ නියතය $=6.022\times10^{23}mol^{-1}$)</p>', '<p>කාබන් ඩයොක්සයිඩ් 22 g ක අඩංගු $CO_{2}$ අණු සංඛ්‍යාව කොපමණද?<br>($C=12$, $O=16$, ඇවගාඩ්‍රෝ නියතය $=6.022\times10^{23}mol^{-1}$)</p>', NULL, '$CO_2$ හි මවුලික ස්කන්ධය $= 12 + (16 \times 2) = 44~gmol^{-1}$.<br>අඩංගු මවුල ගණන $= \frac{22~g}{44~gmol^{-1}}$.<br>අණු සංඛ්‍යාව සෙවීමට මවුල ගණන ඇවගාඩ්‍රෝ නියතයෙන් ගුණ කළ යුතුය. එනම් අණු සංඛ්‍යාව $= \frac{22}{44} \times 6.022 \times 10^{23}$ වේ.[cite: 11]', '$CO_2$ හි මවුලික ස්කන්ධය $= 12 + (16 \times 2) = 44~gmol^{-1}$.<br>අඩංගු මවුල ගණන $= \frac{22~g}{44~gmol^{-1}}$.<br>අණු සංඛ්‍යාව සෙවීමට මවුල ගණන ඇවගාඩ්‍රෝ නියතයෙන් ගුණ කළ යුතුය. එනම් අණු සංඛ්‍යාව $= \frac{22}{44} \times 6.022 \times 10^{23}$ වේ.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('08f534d8-6498-485b-ac27-85f8d2d8cc87', 'b703ab81-06c3-5b9d-aa54-36b9aef07eb5', '$\frac{22}{44}\times6.022\times10^{23}$', '$\frac{22}{44}\times6.022\times10^{23}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ae17f50b-366b-4f7e-b0d6-500bdc7ee869', 'b703ab81-06c3-5b9d-aa54-36b9aef07eb5', '$\frac{44}{22}\times6.022\times10^{23}$', '$\frac{44}{22}\times6.022\times10^{23}$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('01e79b03-9f17-4b9c-9252-f3cfe8e1b671', 'b703ab81-06c3-5b9d-aa54-36b9aef07eb5', '$\frac{6.022\times10^{23}}{44\times22}$', '$\frac{6.022\times10^{23}}{44\times22}$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('28c2ee60-aa34-456d-9733-6f16ab1dc0f9', 'b703ab81-06c3-5b9d-aa54-36b9aef07eb5', '$44\times22\times6.022\times10^{23}$', '$44\times22\times6.022\times10^{23}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('55cc8eea-6865-5d03-8297-7ef54b56a6a9', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 17, '<p>රසායනික පොහොර වර්ගයක් වන යුරියාවල රසායනික සූත්‍රය $CO(NH_{2})_{2}$ වේ. යුරියා සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>රසායනික පොහොර වර්ගයක් වන යුරියාවල රසායනික සූත්‍රය $CO(NH_{2})_{2}$ වේ. යුරියා සම්බන්ධයෙන් නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'සූත්‍රයට අනුව $(NH_2)_2$ කොටසේ $H$ පරමාණු $2 \times 2 = 4$ ක් ඇත (3 වන ප්‍රකාශය නිවැරදිය). යුරියාවල $C$ පරමාණු 1 ක් පමණක් ඇත. සංයෝගයක් සාදන විට මූලද්‍රව්‍යවල ගුණ වෙනස් වේ. මුළු පරමාණු ගණන $= 1(C) + 1(O) + 2(N) + 4(H) = 8$ වේ.[cite: 11]', 'සූත්‍රයට අනුව $(NH_2)_2$ කොටසේ $H$ පරමාණු $2 \times 2 = 4$ ක් ඇත (3 වන ප්‍රකාශය නිවැරදිය). යුරියාවල $C$ පරමාණු 1 ක් පමණක් ඇත. සංයෝගයක් සාදන විට මූලද්‍රව්‍යවල ගුණ වෙනස් වේ. මුළු පරමාණු ගණන $= 1(C) + 1(O) + 2(N) + 4(H) = 8$ වේ.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
