INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7bfb2a11-c557-491a-a9c1-d32477b6ef9e', '55cc8eea-6865-5d03-8297-7ef54b56a6a9', 'යුරියා අණුවක හයිඩ්‍රජන් පරමාණු හතරක් ඇත.', 'යුරියා අණුවක හයිඩ්‍රජන් පරමාණු හතරක් ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e6f848ea-3399-43a3-8b82-a47a33c14db2', '55cc8eea-6865-5d03-8297-7ef54b56a6a9', 'යුරියා අණුවක ඇති මුළු පරමාණු ගණන හතකි.', 'යුරියා අණුවක ඇති මුළු පරමාණු ගණන හතකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b471adbd-ca77-570a-8713-e4e6a8ec591c', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 18, '<p>නිරෝගී පුද්ගලයෙකුගේ ගුච්ඡිකා පෙරනයෙහි අඩංගු වන, එහෙත් මුත්‍ර වල අඩංගු නොවන සංඝටක පමණක් ඇතුළත් වරණය කුමක්ද?</p>', '<p>නිරෝගී පුද්ගලයෙකුගේ ගුච්ඡිකා පෙරනයෙහි අඩංගු වන, එහෙත් මුත්‍ර වල අඩංගු නොවන සංඝටක පමණක් ඇතුළත් වරණය කුමක්ද?</p>', NULL, 'වකුගඩුවල ගුච්ඡිකාවෙන් (Glomerulus) පෙරෙන ග්ලූකෝස් සහ ඇමයිනෝ අම්ල, පසුව වෘක්කාණු නාලය ඔස්සේ ගමන් කිරීමේදී සම්පූර්ණයෙන්ම නැවත රුධිරයට අවශෝෂණය වේ. එබැවින් නිරෝගී අයෙකුගේ මුත්‍රාවල මේවා අඩංගු නොවේ.[cite: 11]', 'වකුගඩුවල ගුච්ඡිකාවෙන් (Glomerulus) පෙරෙන ග්ලූකෝස් සහ ඇමයිනෝ අම්ල, පසුව වෘක්කාණු නාලය ඔස්සේ ගමන් කිරීමේදී සම්පූර්ණයෙන්ම නැවත රුධිරයට අවශෝෂණය වේ. එබැවින් නිරෝගී අයෙකුගේ මුත්‍රාවල මේවා අඩංගු නොවේ.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
