INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a6a5b5f6-ca18-4201-a97f-6140ce71d58b', 'f949d0ee-a307-5a69-a1bd-c8ecdbc2fcf5', 'A ප්‍රකාශය අසත්‍ය වන අතර B ප්‍රකාශය සත්‍ය වේ.', 'A ප්‍රකාශය අසත්‍ය වන අතර B ප්‍රකාශය සත්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6378aa4d-9aef-5a13-93fc-9480725916f8', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 28, '<p>ආකිමිඩිස් මූල ධර්මය මගින් පැහැදිලි කළ නොහැක්කේ පහත කුමන සංසිද්ධියද?</p>', '<p>ආකිමිඩිස් මූල ධර්මය මගින් පැහැදිලි කළ නොහැක්කේ පහත කුමන සංසිද්ධියද?</p>', NULL, 'ද්‍රව ජැක්කුවක් ක්‍රියාත්මක වන්නේ පීඩනය සමානව සම්ප්‍රේෂණය වීමේ ''පැස්කල් මූලධර්මය'' (Pascal''s principle) මතය. අනෙකුත් සංසිද්ධි තුනම පාවීම සහ උඩුකුරු තෙරපුම හා සම්බන්ධ ආකිමිඩීස් මූලධර්මය මත පදනම් වේ.[cite: 11]', 'ද්‍රව ජැක්කුවක් ක්‍රියාත්මක වන්නේ පීඩනය සමානව සම්ප්‍රේෂණය වීමේ ''පැස්කල් මූලධර්මය'' (Pascal''s principle) මතය. අනෙකුත් සංසිද්ධි තුනම පාවීම සහ උඩුකුරු තෙරපුම හා සම්බන්ධ ආකිමිඩීස් මූලධර්මය මත පදනම් වේ.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3f0eef08-cc2b-41ea-9685-831e34f24814', '6378aa4d-9aef-5a13-93fc-9480725916f8', 'මුහුදේ ගමන් ගන්නා නැවක් ගංගාවකට ඇතුළු වීමේදී වැඩිපුර ගිලීම', 'මුහුදේ ගමන් ගන්නා නැවක් ගංගාවකට ඇතුළු වීමේදී වැඩිපුර ගිලීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6009c67c-726d-4aa7-b732-2d84899e66bf', '6378aa4d-9aef-5a13-93fc-9480725916f8', 'හීලියම් වායුව පුරවන ලද බැලූනයක් වාතය තුළින් ඉහළට ගමන් කිරීම', 'හීලියම් වායුව පුරවන ලද බැලූනයක් වාතය තුළින් ඉහළට ගමන් කිරීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('352686cd-04a1-4e6c-a39d-7ada59c7b722', '6378aa4d-9aef-5a13-93fc-9480725916f8', 'සීනි දිය කිරීමේදී දොඩම් යුෂ වීදුරුවක ගිලී තිබූ දොඩම් ඇට ඉපිලීම', 'සීනි දිය කිරීමේදී දොඩම් යුෂ වීදුරුවක ගිලී තිබූ දොඩම් ඇට ඉපිලීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('879d5375-8bdc-4a86-9bfd-67e85ff7f007', '6378aa4d-9aef-5a13-93fc-9480725916f8', 'කුඩා බලයක් යොදා ද්‍රාව ජැක්කුවකින් විශාල ස්කන්ධයක් එසවීම', 'කුඩා බලයක් යොදා ද්‍රාව ජැක්කුවකින් විශාල ස්කන්ධයක් එසවීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a79da878-3bd0-5f2c-aafd-ec80f754ebdd', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 29, '<p>රූපයේ දැක් වෙන්නේ පඩිපෙළක තබා ඇති සිලින්ඩරාකාර කොන්ක්‍රීට් වළල්ලක හරස්කඩකි. මිනිසා විසින් එය ඉහළ මට්ටම දක්වා පෙරළීමට බලය යෙදිය හැකි ස්ථාන හතරක් A, B, C සහ D ලෙස දක්වා ඇත. සුදුසු දිශාවක් ඔස්සේ අඩුම බලයක් යොදා ඉහළට පෙරළීම සඳහා සිලින්ඩරය මත බලය යෙදිය යුතු ස්ථානය කුමක්ද?</p>
