INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b107fdc6-be36-491f-9e8c-b1c79650b5f4', '061c0e97-6a74-59e1-b70c-3530b06fb9ef', 'යකඩ කෙඳිවල හා යකඩ ඇණයේ සංයුතිය එකිනෙකට වෙනස්ය.', 'යකඩ කෙඳිවල හා යකඩ ඇණයේ සංයුතිය එකිනෙකට වෙනස්ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('82523397-3dd9-4f1f-80de-65339c4659f1', '061c0e97-6a74-59e1-b70c-3530b06fb9ef', 'ප්‍රතික්‍රියාවක ශීඝ්‍රතාව ප්‍රතික්‍රියකවල භෞතික ස්වභාවය මත රඳා පවතී.', 'ප්‍රතික්‍රියාවක ශීඝ්‍රතාව ප්‍රතික්‍රියකවල භෞතික ස්වභාවය මත රඳා පවතී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('daba6594-8cd6-5845-a1ac-c6cf9f6dca91', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 31, '<p>2011 වර්ෂයේ ශ්‍රී ලංකාවේ විසු අලි සංඛ්‍යාව 5879 කි. එම අලි සංඛ්‍යාව හැඳින්වීමට වඩාත් සුදුසු ජෛව ගෝලීය සංවිධාන මට්ටම කුමක්ද?</p>', '<p>2011 වර්ෂයේ ශ්‍රී ලංකාවේ විසු අලි සංඛ්‍යාව 5879 කි. එම අලි සංඛ්‍යාව හැඳින්වීමට වඩාත් සුදුසු ජෛව ගෝලීය සංවිධාන මට්ටම කුමක්ද?</p>', NULL, 'නිශ්චිත කාලයකදී, නිශ්චිත ප්‍රදේශයක ජීවත් වන එකම ජීවී විශේෂයකට අයත් ජීවීන් සමූහයක් ගහනයක් (Population) ලෙස හැඳින්වේ. (මෙම අවස්ථාවේ 2011 දී ශ්‍රී ලංකාවේ සිටි අලින්).[cite: 11]', 'නිශ්චිත කාලයකදී, නිශ්චිත ප්‍රදේශයක ජීවත් වන එකම ජීවී විශේෂයකට අයත් ජීවීන් සමූහයක් ගහනයක් (Population) ලෙස හැඳින්වේ. (මෙම අවස්ථාවේ 2011 දී ශ්‍රී ලංකාවේ සිටි අලින්).[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
