INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('300a740b-6c6b-5ba8-b050-8bcfb133aabd', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 34, '<p>යකඩ මත විද්‍යුත්-ලෝහාලේපනය සිදු කිරීම සම්බන්ධ වැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>යකඩ මත විද්‍යුත්-ලෝහාලේපනය සිදු කිරීම සම්බන්ධ වැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'සාර්ථක හා ගුණාත්මක විද්‍යුත් ලෝහාලේපනයක් (Electroplating) ලබා ගැනීම සඳහා විද්‍යුත් විච්ඡේද්‍ය ද්‍රාවණයේ සාන්ද්‍රණය අඩුවෙන් (තනුකව) පවත්වා ගත යුතුය. අධික සාන්ද්‍රණයකදී ලෝහය වේගයෙන් නිධිගත වී එය බුරුල් සහ අක්‍රමවත් විය හැක.[cite: 11]', 'සාර්ථක හා ගුණාත්මක විද්‍යුත් ලෝහාලේපනයක් (Electroplating) ලබා ගැනීම සඳහා විද්‍යුත් විච්ඡේද්‍ය ද්‍රාවණයේ සාන්ද්‍රණය අඩුවෙන් (තනුකව) පවත්වා ගත යුතුය. අධික සාන්ද්‍රණයකදී ලෝහය වේගයෙන් නිධිගත වී එය බුරුල් සහ අක්‍රමවත් විය හැක.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('11da20fd-b4c6-48a4-8622-abf517af6bc9', '300a740b-6c6b-5ba8-b050-8bcfb133aabd', 'ආලේප කරන ලෝහයේ සංයෝගයක ජලීය ද්‍රාවණයක් විද්‍යුත් විච්ඡේද්‍යය විය යුතුය.', 'ආලේප කරන ලෝහයේ සංයෝගයක ජලීය ද්‍රාවණයක් විද්‍යුත් විච්ඡේද්‍යය විය යුතුය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e085e2d6-009f-4e6c-88d0-0babcf0f85e8', '300a740b-6c6b-5ba8-b050-8bcfb133aabd', 'ගුණාත්මක ලෝහාලේපනයක් සඳහා විද්‍යුත් විච්ඡේද්‍යය ඉහළ සාන්ද්‍රණයක් සහිත විය යුතු ය.', 'ගුණාත්මක ලෝහාලේපනයක් සඳහා විද්‍යුත් විච්ඡේද්‍යය ඉහළ සාන්ද්‍රණයක් සහිත විය යුතු ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c1f45c9c-54c3-4e41-a7c7-1840955edb5f', '300a740b-6c6b-5ba8-b050-8bcfb133aabd', 'විද්‍යුත් විච්ඡේද්‍ය කෝෂයේ කැතෝඩය ලෙස යකඩ යෙදිය යුතු ය.', 'විද්‍යුත් විච්ඡේද්‍ය කෝෂයේ කැතෝඩය ලෙස යකඩ යෙදිය යුතු ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e6653b69-bf58-4d6a-a3f3-57c3f92c7973', '300a740b-6c6b-5ba8-b050-8bcfb133aabd', 'භාවිත කරන විද්‍යුත් ධාරාව සරල ධාරාවක් විය යුතු ය.', 'භාවිත කරන විද්‍යුත් ධාරාව සරල ධාරාවක් විය යුතු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ec7c02c4-2b24-5636-a5e1-79e43c5fdef7', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 35, '<p>ජලීය හයිඩ්‍රොක්ලෝරික් අම්ලය සහිත කේතු ප්ලාස්කුවක් සංවේදී තුලාවක් මත තබා ඇත. එයට වැඩිපුර හුනුගල් කැබලි එකතු කරන ලදි. හුනුගල් කැබලි එකතු කිරීමෙන් පසු තුලාවේ පාඨාංකය කාලයට එදිරිව විචලනය වන ආකාරය දැක්වෙනුයේ කුමන ප්‍රස්තාරයෙන්ද?</p>', '<p>ජලීය හයිඩ්‍රොක්ලෝරික් අම්ලය සහිත කේතු ප්ලාස්කුවක් සංවේදී තුලාවක් මත තබා ඇත. එයට වැඩිපුර හුනුගල් කැබලි එකතු කරන ලදි. හුනුගල් කැබලි එකතු කිරීමෙන් පසු තුලාවේ පාඨාංකය කාලයට එදිරිව විචලනය වන ආකාරය දැක්වෙනුයේ කුමන ප්‍රස්තාරයෙන්ද?</p>', NULL, 'හුනුගල් ($CaCO_3$) අම්ලය සමග ප්‍රතික්‍රියා කරන විට කාබන් ඩයොක්සයිඩ් ($CO_2$) වායුව පිටවේ. ප්ලාස්කුව විවෘත බැවින් වායුව ඉවත් වී මුළු ස්කන්ධය (පාඨාංකය) ක්‍රමයෙන් අඩු වේ. ප්‍රතික්‍රියාව අවසන් වූ පසු ස්කන්ධය නියතව පවතී.[cite: 11]', 'හුනුගල් ($CaCO_3$) අම්ලය සමග ප්‍රතික්‍රියා කරන විට කාබන් ඩයොක්සයිඩ් ($CO_2$) වායුව පිටවේ. ප්ලාස්කුව විවෘත බැවින් වායුව ඉවත් වී මුළු ස්කන්ධය (පාඨාංකය) ක්‍රමයෙන් අඩු වේ. ප්‍රතික්‍රියාව අවසන් වූ පසු ස්කන්ධය නියතව පවතී.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2700a97a-4630-4a45-bf8b-962f09dc932a', 'ec7c02c4-2b24-5636-a5e1-79e43c5fdef7', 'තුලාවේ පාඨාංකය නියතව පවතින ප්‍රස්තාරය (1)
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1a6b84e0-6c64-4adb-a1c2-74cbf3b60c19', 'ec7c02c4-2b24-5636-a5e1-79e43c5fdef7', 'තුලාවේ පාඨාංකය අඩුවී නියත වන ප්‍රස්තාරය (2)
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('88aa81a6-3bd9-4469-b55a-33f67997f74a', 'ec7c02c4-2b24-5636-a5e1-79e43c5fdef7', 'තුලාවේ පාඨාංකය වැඩි වී නියත වන ප්‍රස්තාරය (3)
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('50ecb943-553b-44e5-a27f-14cfb539e884', 'ec7c02c4-2b24-5636-a5e1-79e43c5fdef7', 'තුලාවේ පාඨාංකය ශුන්‍ය දක්වා අඩුවන ප්‍රස්තාරය (4)
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c59f4c50-5275-5dbb-a7a3-5fe72f4ed31e', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 36, '<p>පරිණාමකයක ප්‍රාථමික දඟරයේ සහ ද්විතීයික දඟරයේ පොට සංඛ්‍යා පිළිවෙළින් $N_{P}$ සහ $N_{S}$ වේ. ප්‍රාථමික දඟරයේ විභව අන්තරය $V_{P}$ ද ද්විතීයික දඟරයේ විභව අන්තරය $V_{S}$ ද වේ. පොට සංඛ්‍යා සහ විභව අන්තර අතර නිවැරදි සම්බන්ධතාව කුමක්ද?</p>', '<p>පරිණාමකයක ප්‍රාථමික දඟරයේ සහ ද්විතීයික දඟරයේ පොට සංඛ්‍යා පිළිවෙළින් $N_{P}$ සහ $N_{S}$ වේ. ප්‍රාථමික දඟරයේ විභව අන්තරය $V_{P}$ ද ද්විතීයික දඟරයේ විභව අන්තරය $V_{S}$ ද වේ. පොට සංඛ්‍යා සහ විභව අන්තර අතර නිවැරදි සම්බන්ධතාව කුමක්ද?</p>', NULL, 'පරිණාමකයක් (Transformer) සඳහා, දඟර වල විභව අන්තර අනුපාතය එහි පොට සංඛ්‍යා අනුපාතයට සමාන වේ. එනම් $\frac{V_p}{V_s} = \frac{N_p}{N_s}$ වේ.[cite: 11]', 'පරිණාමකයක් (Transformer) සඳහා, දඟර වල විභව අන්තර අනුපාතය එහි පොට සංඛ්‍යා අනුපාතයට සමාන වේ. එනම් $\frac{V_p}{V_s} = \frac{N_p}{N_s}$ වේ.[cite: 11]', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aff6bcad-8110-448f-bd99-7363f2a00918', 'c59f4c50-5275-5dbb-a7a3-5fe72f4ed31e', '$\frac{V_{p}}{V_{s}}=\frac{N_{p}}{N_{s}}$', '$\frac{V_{p}}{V_{s}}=\frac{N_{p}}{N_{s}}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('deb087ce-326a-4f01-a317-02219f5ff4f8', 'c59f4c50-5275-5dbb-a7a3-5fe72f4ed31e', '$\frac{V_{S}}{V_{P}}=\frac{N_{P}}{N_{S}}$', '$\frac{V_{S}}{V_{P}}=\frac{N_{P}}{N_{S}}$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d52f882b-0ab6-4f32-8a91-da3bf35dcdcd', 'c59f4c50-5275-5dbb-a7a3-5fe72f4ed31e', '$V_{S}V_{P}=N_{S}N_{P}$', '$V_{S}V_{P}=N_{S}N_{P}$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e4bf83aa-1273-4b9b-8934-5bb4abc2ddf5', 'c59f4c50-5275-5dbb-a7a3-5fe72f4ed31e', '$V_{S}N_{S}=\frac{1}{V_{p}N_{p}}$', '$V_{S}N_{S}=\frac{1}{V_{p}N_{p}}$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8fa4d830-9c24-54b3-8fdf-06b96cc3c71b', '0be5970f-09e6-504b-9bac-dfdc8afbaa07', 37, '<p>A, B, C හා D නිවාස හතරක තොරතුරු සලකන්න.<br>A - සූර්ය කෝෂ, CFL, LP ගෑස් ලිප<br>B - ජාතික විදුලිය, සූත්‍රිකා බල්බ, විදුලි තාපකය<br>C - විදුලි ජනකය, ප්‍රතිදීපන පහන්, භූමිතෙල් ලිප<br>D - ජීව වායු ඒකකය, ජීව වායු ලාම්පු, දර ලිප<br><br>පුනර්ජනනීය නොවන ශක්ති ප්‍රභවයක් පමණක් වැය වන්නේ කුමන නිවසේ ද?</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4b6d10f9-69b0-42a3-b838-77dde76284fd', '8fa4d830-9c24-54b3-8fdf-06b96cc3c71b', 'A', 'A', NULL, 'sanitized', 'v1', 0, 1);
