INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e8976570-48ef-4a73-8494-cc3d645d39c3', 'cc030e24-af5c-5323-a629-61cad44f655e', 'බීජය තුළ එක් බීජ පත්‍රයක් තිබීමයි.', 'බීජය තුළ එක් බීජ පත්‍රයක් තිබීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('514ed66b-7af3-4b3c-b5e8-259cb37eb145', 'cc030e24-af5c-5323-a629-61cad44f655e', 'චතුර් අංක හෝ පංචාංක පුෂ්ප දැරීමයි.', 'චතුර් අංක හෝ පංචාංක පුෂ්ප දැරීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6eee739b-1816-512d-9d2c-4e34b4af876a', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 9, '<p>විද්‍යුත් - චුම්බක තරංග හා සම්බන්ධ පහත ප්‍රකාශ වලින් අසත්‍ය ප්‍රකාශය කුමක්ද?</p>', '<p>විද්‍යුත් - චුම්බක තරංග හා සම්බන්ධ පහත ප්‍රකාශ වලින් අසත්‍ය ප්‍රකාශය කුමක්ද?</p>', NULL, 'තරංගයක් එක් මාධ්‍යයකින් තවත් මාධ්‍යයකට ගමන් කිරීමේදී එහි වේගය සහ තරංග ආයාමය වෙනස් වුවද, තරංගයේ සංඛ්‍යාතය (Frequency) කිසිවිටෙකත් වෙනස් නොවේ. එය රඳා පවතින්නේ තරංගය නිපදවන ප්‍රභවය මත පමණි. එබැවින් සංඛ්‍යාතය අඩු වේ යන්න අසත්‍යයකි.', 'තරංගයක් එක් මාධ්‍යයකින් තවත් මාධ්‍යයකට ගමන් කිරීමේදී එහි වේගය සහ තරංග ආයාමය වෙනස් වුවද, තරංගයේ සංඛ්‍යාතය (Frequency) කිසිවිටෙකත් වෙනස් නොවේ. එය රඳා පවතින්නේ තරංගය නිපදවන ප්‍රභවය මත පමණි. එබැවින් සංඛ්‍යාතය අඩු වේ යන්න අසත්‍යයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9852291f-e975-4d47-b692-7dd162c1c19c', '6eee739b-1816-512d-9d2c-4e34b4af876a', 'ශක්තිය සම්ප්‍රේෂණය කරයි.', 'ශක්තිය සම්ප්‍රේෂණය කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5406199e-83d7-4bf4-8cc3-25735377c93d', '6eee739b-1816-512d-9d2c-4e34b4af876a', 'රික්තයේ දී $3\times10^{8}m~s^{-1}$ වේගයකින් ගමන් කරයි.', 'රික්තයේ දී $3\times10^{8}m~s^{-1}$ වේගයකින් ගමන් කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bcf11f51-7b5f-43bc-9683-c13a7574f7cf', '6eee739b-1816-512d-9d2c-4e34b4af876a', 'පදාර්ථමය මාධ්‍යයක දී සංඛ්‍යාතය රික්තයේ දීට වඩා අඩු වේ.', 'පදාර්ථමය මාධ්‍යයක දී සංඛ්‍යාතය රික්තයේ දීට වඩා අඩු වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f90c0cfb-7d19-4163-884d-510949bd1840', '6eee739b-1816-512d-9d2c-4e34b4af876a', 'පදාර්ථමය මාධ්‍යයක දී වේගය රික්තයේ දීට වඩා අඩු වේ.', 'පදාර්ථමය මාධ්‍යයක දී වේගය රික්තයේ දීට වඩා අඩු වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('91eb4cf3-e845-5c29-ab73-af8c3be29139', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 10, '<p>අයනික සංයෝග පිළිබඳ ව සත්‍ය වනුයේ පහත කුමන ප්‍රකාශයද?</p>', '<p>අයනික සංයෝග පිළිබඳ ව සත්‍ය වනුයේ පහත කුමන ප්‍රකාශයද?</p>', NULL, 'අයනික සංයෝග වල කැටායන සහ ඇනායන අතර ප්‍රබල ස්ථිති විද්‍යුත් ආකර්ෂණ බල පවතින බැවින් ඒවා බිඳ හෙලීමට විශාල තාප ශක්තියක් අවශ්‍ය වේ. එබැවින් ඒවායේ ද්‍රවාංක හා තාපාංක ඉතා ඉහළ අගයන් ගනී. ඝන අවස්ථාවේ අයන චලනය විය නොහැකි බැවින් විදුලිය සන්නයනය නොකරන අතර, විලීන හෝ ජලීය අවස්ථාවේදී විදුලිය සන්නයනය කරයි.', 'අයනික සංයෝග වල කැටායන සහ ඇනායන අතර ප්‍රබල ස්ථිති විද්‍යුත් ආකර්ෂණ බල පවතින බැවින් ඒවා බිඳ හෙලීමට විශාල තාප ශක්තියක් අවශ්‍ය වේ. එබැවින් ඒවායේ ද්‍රවාංක හා තාපාංක ඉතා ඉහළ අගයන් ගනී. ඝන අවස්ථාවේ අයන චලනය විය නොහැකි බැවින් විදුලිය සන්නයනය නොකරන අතර, විලීන හෝ ජලීය අවස්ථාවේදී විදුලිය සන්නයනය කරයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
