INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('364c49ee-1b36-4bd8-8492-7c7365c1bf5d', '91eb4cf3-e845-5c29-ab73-af8c3be29139', 'විලීන අවස්ථාවේ දී විදුලිය සන්නයනය නො කරයි.', 'විලීන අවස්ථාවේ දී විදුලිය සන්නයනය නො කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('eb92b013-461b-520c-a11e-a0c57142a720', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 11, '<p>ශ්වසන පද්ධතිය ආශ්‍රිත රෝගයකින් පෙළෙන පුද්ගලයෙකු තුළ පහත රෝග ලක්ෂණ දක්නට ලැබේ.<br>• කැස්ස සමඟ රුධිරය පිටවීම<br>• ශරීරයේ බර අඩු වීම<br>• අධික වෙහෙස<br>මෙම පුද්ගලයාට වැළඳී තිබීමට හැක්කේ</p>', '<p>ශ්වසන පද්ධතිය ආශ්‍රිත රෝගයකින් පෙළෙන පුද්ගලයෙකු තුළ පහත රෝග ලක්ෂණ දක්නට ලැබේ.<br>• කැස්ස සමඟ රුධිරය පිටවීම<br>• ශරීරයේ බර අඩු වීම<br>• අධික වෙහෙස<br>මෙම පුද්ගලයාට වැළඳී තිබීමට හැක්කේ</p>', NULL, 'කැස්ස සමඟ රුධිරය පිටවීම, ශරීරයේ බර ක්‍රමයෙන් අඩු වීම, අධික වෙහෙස සහ රාත්‍රී කාලයට දහඩිය දැමීම ක්ෂය රෝගයේ (Tuberculosis - TB) ප්‍රධාන රෝග ලක්ෂණ වේ.', 'කැස්ස සමඟ රුධිරය පිටවීම, ශරීරයේ බර ක්‍රමයෙන් අඩු වීම, අධික වෙහෙස සහ රාත්‍රී කාලයට දහඩිය දැමීම ක්ෂය රෝගයේ (Tuberculosis - TB) ප්‍රධාන රෝග ලක්ෂණ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
