INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('da0773fa-be72-4f53-b7ac-2899961e6c0b', '7c24df5f-f0bb-5986-87eb-adb431134829', 'ලෝහ පරමාණු ඉලෙක්ට්‍රෝන පිට කරමින් ධන අයන නිපදවයි.', 'ලෝහ පරමාණු ඉලෙක්ට්‍රෝන පිට කරමින් ධන අයන නිපදවයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b645d1d8-6f4a-47ec-b7ae-94f4772b1a0e', '7c24df5f-f0bb-5986-87eb-adb431134829', 'සියලු ම ලෝහ අම්ල සමග ප්‍රතික්‍රියා කර හයිඩ්රජන් පිට කරයි.', 'සියලු ම ලෝහ අම්ල සමග ප්‍රතික්‍රියා කර හයිඩ්රජන් පිට කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fde0295a-bcd8-5d89-a29d-326db04c48c9', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 18, '<p>එක්තරා ද්‍රාවණයකට මෙතිල් ඔරේන්ජ් බිංදු කිහිපයක් එක් කළ විට එම ද්‍රාවණය රතු පැහැයට හැරිණි. එම ද්‍රාවණයේ pH අගය වීමට වඩාත් ඉඩ ඇත්තේ මින් කුමක්ද?</p>', '<p>එක්තරා ද්‍රාවණයකට මෙතිල් ඔරේන්ජ් බිංදු කිහිපයක් එක් කළ විට එම ද්‍රාවණය රතු පැහැයට හැරිණි. එම ද්‍රාවණයේ pH අගය වීමට වඩාත් ඉඩ ඇත්තේ මින් කුමක්ද?</p>', NULL, 'මෙතිල් ඔරේන්ජ් (Methyl orange) දර්ශකය ආම්ලික මාධ්‍යයකදී (pH < 3.1 පමණ) රතු වර්ණයක් ගන්නා අතර, භාෂ්මික සහ උදාසීන මාධ්‍යවලදී කහ/තැඹිලි වර්ණයක් ගනී. එබැවින් රතු පැහැය ලබා දෙන්නේ ප්‍රබල ආම්ලික ද්‍රාවණයක් වන pH = 2 අවස්ථාවේදීය.', 'මෙතිල් ඔරේන්ජ් (Methyl orange) දර්ශකය ආම්ලික මාධ්‍යයකදී (pH < 3.1 පමණ) රතු වර්ණයක් ගන්නා අතර, භාෂ්මික සහ උදාසීන මාධ්‍යවලදී කහ/තැඹිලි වර්ණයක් ගනී. එබැවින් රතු පැහැය ලබා දෙන්නේ ප්‍රබල ආම්ලික ද්‍රාවණයක් වන pH = 2 අවස්ථාවේදීය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
