INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f06f88a9-0e8a-5954-8023-588c0ab288f7', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 23, '<p>කැල්සියම් කාබනේට් 10 g ක ඇති කැල්සියම් කාබනේට් මවුල ප්‍රමාණය කොපමණ ද? $(CaCO_{3}=100)$</p>', '<p>කැල්සියම් කාබනේට් 10 g ක ඇති කැල්සියම් කාබනේට් මවුල ප්‍රමාණය කොපමණ ද? $(CaCO_{3}=100)$</p>', NULL, 'මවුල ගණන ($n$) = ස්කන්ධය ($m$) / මවුලික ස්කන්ධය ($M$).<br>$n = 10 g / 100 gmol^{-1} = 0.1 mol$.', 'මවුල ගණන ($n$) = ස්කන්ධය ($m$) / මවුලික ස්කන්ධය ($M$).<br>$n = 10 g / 100 gmol^{-1} = 0.1 mol$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
