INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4827e509-b471-4780-ad36-18febd2e9987', 'dcc09ec1-7897-5696-b544-3afe419c9b3b', 'ග්ලූකෝස් යනු කාබොහයිඩ්රේටවල තැනුම් ඒකකයයි.', 'ග්ලූකෝස් යනු කාබොහයිඩ්රේටවල තැනුම් ඒකකයයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1a810af0-0905-5583-8496-a0791ee9877e', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 25, '<p>දකුණු පසින් දැක්වෙන්නේ A හා B ලෝහ දෙකකින් සැදුම් ලත් ද්වීලෝහ පටියකි. මෙහි වැඩියෙන් ප්‍රසාරණය වන ලෝහය A වන අතර අඩුවෙන් ප්‍රසාරණය වන ලෝහය B වේ.<br>ද්වි ලෝහ පටියේ උෂ්ණත්වය වැඩි කළ විට එහි හැඩය වෙනස් වන්නේ පහත කුමන ආකාරයටද?</p>
