INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3b762f82-3444-47cd-b5ea-fe07b9fa68d8', '63619431-98b4-5e66-b4d4-95234d4406dd', 'ඝන වස්තුවේ ස්කන්ධය විස්ථාපිත ද්‍රව ස්කන්ධයට සමාන විය යුතුය.', 'ඝන වස්තුවේ ස්කන්ධය විස්ථාපිත ද්‍රව ස්කන්ධයට සමාන විය යුතුය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('430d371d-e9dc-4f94-8922-f4df311ddc79', '63619431-98b4-5e66-b4d4-95234d4406dd', 'ඝන වස්තුවේ බර එමගින් විස්ථාපිත ද්‍රව පරිමාවේ බරට සමාන විය යුතු ය.', 'ඝන වස්තුවේ බර එමගින් විස්ථාපිත ද්‍රව පරිමාවේ බරට සමාන විය යුතු ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('35c912d2-2f07-4886-8327-449198b886af', '63619431-98b4-5e66-b4d4-95234d4406dd', 'ඝන වස්තුවේ බර එය මත ඇති වන උඩුකුරු තෙරපුමට වඩා අඩු විය යුතු ය.', 'ඝන වස්තුවේ බර එය මත ඇති වන උඩුකුරු තෙරපුමට වඩා අඩු විය යුතු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4af82507-cadf-54fe-8346-401d9d6fbeda', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 27, '<p>Tt ප්‍රවේණි දර්ශය සහිත ජීවීන් දෙදෙනෙකු අතර අන්තරාභිජනනයෙන් බිහි වන ජනිතයන්ගේ එකිනෙකට වෙනස් ප්‍රවේණි දර්ශ සංඛ්‍යාව හා රූපානුදර්ශ සංඛ්‍යාව පිළිවෙළින්,</p>', '<p>Tt ප්‍රවේණි දර්ශය සහිත ජීවීන් දෙදෙනෙකු අතර අන්තරාභිජනනයෙන් බිහි වන ජනිතයන්ගේ එකිනෙකට වෙනස් ප්‍රවේණි දර්ශ සංඛ්‍යාව හා රූපානුදර්ශ සංඛ්‍යාව පිළිවෙළින්,</p>', NULL, 'විෂමයුග්මක මුහුම්කරණයකදී (Tt x Tt), පැනනගින ප්‍රවේණි දර්ශ (Genotypes) 3 කි (TT, Tt, tt). මේවාට අනුරූපව ඇතිවන රූපානුදර්ශ (Phenotypes) 2 කි (උස සහ මිටි - මෙහි TT සහ Tt යන දෙකම උස ලක්ෂණය පෙන්වයි).', 'විෂමයුග්මක මුහුම්කරණයකදී (Tt x Tt), පැනනගින ප්‍රවේණි දර්ශ (Genotypes) 3 කි (TT, Tt, tt). මේවාට අනුරූපව ඇතිවන රූපානුදර්ශ (Phenotypes) 2 කි (උස සහ මිටි - මෙහි TT සහ Tt යන දෙකම උස ලක්ෂණය පෙන්වයි).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
