INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3a545310-3176-4f1d-8772-ca58aa833bd3', '5379414a-91ca-572c-8ecb-6c1a1ff93d7a', 'S ස්විච්චය විවෘත කරන මොහොතේ දී සහ වසන මොහොතේ දී පමණක් B හි ධාරාවක් ගලා යයි.', 'S ස්විච්චය විවෘත කරන මොහොතේ දී සහ වසන මොහොතේ දී පමණක් B හි ධාරාවක් ගලා යයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c5d219d9-fa87-58cc-b3e2-e27e31e1120b', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 36, '<p>ප්‍රවේග - කාල ප්‍රස්තාරය පිළිබඳ දක්වා ඇති පහත ප්‍රකාශ වලින් අසත්‍ය ප්‍රකාශය කුමක්ද?</p>', '<p>ප්‍රවේග - කාල ප්‍රස්තාරය පිළිබඳ දක්වා ඇති පහත ප්‍රකාශ වලින් අසත්‍ය ප්‍රකාශය කුමක්ද?</p>', NULL, 'ප්‍රවේග-කාල ප්‍රස්තාරයක අනුක්‍රමණය (Gradient) මගින් ත්වරණය නිරූපණය වේ. කාලයත් සමග ප්‍රවේගය වෙනස් වන විට (ත්වරණය වන විට) අනුක්‍රමණයට අගයක් ඇත, එය ශුන්‍ය නොවේ. අනුක්‍රමණය ශුන්‍ය වන්නේ ප්‍රවේගය නියතව (ඒකාකාර ප්‍රවේගයෙන්) පවතින විටදීය.', 'ප්‍රවේග-කාල ප්‍රස්තාරයක අනුක්‍රමණය (Gradient) මගින් ත්වරණය නිරූපණය වේ. කාලයත් සමග ප්‍රවේගය වෙනස් වන විට (ත්වරණය වන විට) අනුක්‍රමණයට අගයක් ඇත, එය ශුන්‍ය නොවේ. අනුක්‍රමණය ශුන්‍ය වන්නේ ප්‍රවේගය නියතව (ඒකාකාර ප්‍රවේගයෙන්) පවතින විටදීය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
