INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e23b1b27-2a2a-42e9-bf3d-9faff0be965a', 'c5d219d9-fa87-58cc-b3e2-e27e31e1120b', 'කාලයත් සමග ප්‍රවේගය වෙනස් වන චලිතයක දී ප්‍රස්තාරයේ අනුක්‍රමණය ශුන්‍ය වේ.', 'කාලයත් සමග ප්‍රවේගය වෙනස් වන චලිතයක දී ප්‍රස්තාරයේ අනුක්‍රමණය ශුන්‍ය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b981c1c-add2-4166-875f-6a3f4b888ee7', 'c5d219d9-fa87-58cc-b3e2-e27e31e1120b', 'ප්‍රස්තාරයේ අනුක්‍රමණයෙන් ත්වරණය/මන්දනය ලැබේ.', 'ප්‍රස්තාරයේ අනුක්‍රමණයෙන් ත්වරණය/මන්දනය ලැබේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d363fec-c35f-5f93-8fbd-f5ecc9f4abf1', '0bf4e196-a3ae-5a00-b3d9-7a9d140d95a6', 37, '<p>සාගර පරිසර පද්ධතිවල ඇල්ගී ගහනය අසාමාන්‍ය ලෙස වර්ධනය වීමට දායක වන දූෂකය කුමක්ද?</p>', '<p>සාගර පරිසර පද්ධතිවල ඇල්ගී ගහනය අසාමාන්‍ය ලෙස වර්ධනය වීමට දායක වන දූෂකය කුමක්ද?</p>', NULL, 'ජලාශ හා සාගරවල ඇල්ගී ගහනය අසාමාන්‍ය ලෙස වර්ධනය වීම ''සුපෝෂණය'' (Eutrophication) ලෙස හැඳින්වේ. කෘෂිකාර්මික පොහොර සහ සේදුම් කාරක හරහා ජලයට එකතු වන නයිට්‍රේට සහ පොස්පේට් ($PO_4^{3-}$) යන පෝෂක මීට ප්‍රධාන වශයෙන් දායක වේ.', 'ජලාශ හා සාගරවල ඇල්ගී ගහනය අසාමාන්‍ය ලෙස වර්ධනය වීම ''සුපෝෂණය'' (Eutrophication) ලෙස හැඳින්වේ. කෘෂිකාර්මික පොහොර සහ සේදුම් කාරක හරහා ජලයට එකතු වන නයිට්‍රේට සහ පොස්පේට් ($PO_4^{3-}$) යන පෝෂක මීට ප්‍රධාන වශයෙන් දායක වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
