INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('58108085-9f44-49a8-976f-b04ad395def2', 'b8359fab-145b-551f-8a89-0a1d21337750', 'එදිනෙදා මිල දී ගන්නා ආහාර ද්‍රව්‍ය රැගෙන ඒමට එක ම රෙදි මල්ලක් භාවිත කිරීම', 'එදිනෙදා මිල දී ගන්නා ආහාර ද්‍රව්‍ය රැගෙන ඒමට එක ම රෙදි මල්ලක් භාවිත කිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fcd4e075-69a9-48a5-abf6-78735a974fd8', 'b8359fab-145b-551f-8a89-0a1d21337750', 'මැහුම් ගැලවුණු ඇඳුමක් නැවත මසා ඇඳීම', 'මැහුම් ගැලවුණු ඇඳුමක් නැවත මසා ඇඳීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4ea50357-9666-50a2-8bf1-a6c7bd9706b9', '0c3c990e-e81c-5492-9797-f946ca52bc04', 1, '<p>අතීත ශ්‍රී ලංකාවේ වෙළෙඳාම හා ලෝහ කර්මාන්තය පිළිබඳ හැදෑරීමේ දී වැදගත් මූලාශ්‍රය වන්නේ මින් කුමක්ද?</p>', '<p>අතීත ශ්‍රී ලංකාවේ වෙළෙඳාම හා ලෝහ කර්මාන්තය පිළිබඳ හැදෑරීමේ දී වැදගත් මූලාශ්‍රය වන්නේ මින් කුමක්ද?</p>', NULL, 'පැරණි ශ්‍රී ලංකාවේ වෙළෙඳාම සහ ලෝහ භාවිතය පිළිබඳව වඩාත් නිවැරදි තොරතුරු සපයන මූලාශ්‍රය වන්නේ ඒ යුගයේ භාවිතා කළ කාසි ය. විවිධ රටවලින් හමුවූ කාසි සහ දේශීයව නිෂ්පාදිත කාසි මගින් වෙළෙඳ සබඳතා හා ලෝහ තාක්ෂණය මැනවින් අවබෝධ කරගත හැක.', 'පැරණි ශ්‍රී ලංකාවේ වෙළෙඳාම සහ ලෝහ භාවිතය පිළිබඳව වඩාත් නිවැරදි තොරතුරු සපයන මූලාශ්‍රය වන්නේ ඒ යුගයේ භාවිතා කළ කාසි ය. විවිධ රටවලින් හමුවූ කාසි සහ දේශීයව නිෂ්පාදිත කාසි මගින් වෙළෙඳ සබඳතා හා ලෝහ තාක්ෂණය මැනවින් අවබෝධ කරගත හැක.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
