INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4430deae-f543-55fe-a9c9-1df2e5497d2c', '0c3c990e-e81c-5492-9797-f946ca52bc04', 4, '<p>මුල් යුගයේ ජනතාව ගංගා නිම්න වලින් පිටත ප්‍රදේශ පදිංචිය සඳහා තෝරා ගැනීමට හේතුව කුමක්ද?</p>', '<p>මුල් යුගයේ ජනතාව ගංගා නිම්න වලින් පිටත ප්‍රදේශ පදිංචිය සඳහා තෝරා ගැනීමට හේතුව කුමක්ද?</p>', NULL, 'මුල් යුගයේ ජනාවාස ගංගා නිම්න ආශ්‍රිතව බිහි වුවද, අධික වර්ෂා කාලවලදී ඇතිවන ගංවතුර තත්ත්වයන්ගෙන් බේරීම සඳහා ඔවුන් ගංගා නිම්නයෙන් මඳක් ඈතට හෝ උස් බිම් වෙත සංක්‍රමණය වී පදිංචි වීම සිදු කරන ලදී.', 'මුල් යුගයේ ජනාවාස ගංගා නිම්න ආශ්‍රිතව බිහි වුවද, අධික වර්ෂා කාලවලදී ඇතිවන ගංවතුර තත්ත්වයන්ගෙන් බේරීම සඳහා ඔවුන් ගංගා නිම්නයෙන් මඳක් ඈතට හෝ උස් බිම් වෙත සංක්‍රමණය වී පදිංචි වීම සිදු කරන ලදී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c74070a1-7ff4-4f22-9c35-0d1f28dfcce3', '4430deae-f543-55fe-a9c9-1df2e5497d2c', 'ගංවතුර උවදුරෙන් බේරීම', 'ගංවතුර උවදුරෙන් බේරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('35089b36-b321-4595-a58c-f20e60936313', '4430deae-f543-55fe-a9c9-1df2e5497d2c', 'කෘෂිකර්මාන්තයට හිතකර සාධක පැවතීම', 'කෘෂිකර්මාන්තයට හිතකර සාධක පැවතීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('922bc7d5-f8c0-4240-bcdb-c1287d75d8d3', '4430deae-f543-55fe-a9c9-1df2e5497d2c', 'වන සතුන්ගෙන් ආරක්ෂා වීම', 'වන සතුන්ගෙන් ආරක්ෂා වීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dcf877d8-be4c-424e-9415-58043175f8cd', '4430deae-f543-55fe-a9c9-1df2e5497d2c', 'ගමනාගමන පහසුව', 'ගමනාගමන පහසුව', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c41d4137-9bbb-5307-a407-ec66bf507661', '0c3c990e-e81c-5492-9797-f946ca52bc04', 5, '<p>A, B, C හා D යන ප්‍රකාශ ඇසුරෙන් පහත ප්‍රශ්නයට පිළිතුරු සපයන්න.<br><br>A - වැව් කේන්ද්‍ර කරගනිමින් ජනාවාස බිහිවීම<br>B - ක්‍රමවත් සුසාන චාරිත්‍ර අනුගමනය කිරීම<br>C - විවිධ වෘත්තීන්ට අනුව ජනාවාස බිහිවීම<br>D - කෘෂිකාර්මික කටයුතු ආරම්භ වීම<br><br>පූර්ව ඵෙතිහාසික යුගය (Proto-historic period) හා සම්බන්ධ නිවැරදි ප්‍රකාශ වන්නේ,</p>', '<p>A, B, C හා D යන ප්‍රකාශ ඇසුරෙන් පහත ප්‍රශ්නයට පිළිතුරු සපයන්න.<br><br>A - වැව් කේන්ද්‍ර කරගනිමින් ජනාවාස බිහිවීම<br>B - ක්‍රමවත් සුසාන චාරිත්‍ර අනුගමනය කිරීම<br>C - විවිධ වෘත්තීන්ට අනුව ජනාවාස බිහිවීම<br>D - කෘෂිකාර්මික කටයුතු ආරම්භ වීම<br><br>පූර්ව ඵෙතිහාසික යුගය (Proto-historic period) හා සම්බන්ධ නිවැරදි ප්‍රකාශ වන්නේ,</p>', NULL, 'පූර්ව ඓතිහාසික යුගයේ ප්‍රධාන ලක්ෂණ වන්නේ කෘෂිකර්මාන්තය (D) ආරම්භ කිරීම සහ මළවුන් ඇදහීම හෝ ක්‍රමවත් සුසාන චාරිත්‍ර (B) අනුගමනය කිරීමයි. මැටි බඳුන් භාවිතය ද මේ යුගයේ විශේෂ ලක්ෂණයකි.', 'පූර්ව ඓතිහාසික යුගයේ ප්‍රධාන ලක්ෂණ වන්නේ කෘෂිකර්මාන්තය (D) ආරම්භ කිරීම සහ මළවුන් ඇදහීම හෝ ක්‍රමවත් සුසාන චාරිත්‍ර (B) අනුගමනය කිරීමයි. මැටි බඳුන් භාවිතය ද මේ යුගයේ විශේෂ ලක්ෂණයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
