INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6a7ec166-b469-5029-a59b-f0cf534207cc', '0c3c990e-e81c-5492-9797-f946ca52bc04', 9, '<p>වසභ, මහසෙන් හා මහා පරාක්‍රමබාහු යන රජවරුන් පිළිබඳ පොදු කරුණ වන්නේ මින් කුමක්ද ?</p>', '<p>වසභ, මහසෙන් හා මහා පරාක්‍රමබාහු යන රජවරුන් පිළිබඳ පොදු කරුණ වන්නේ මින් කුමක්ද ?</p>', NULL, 'වසභ රජු, මහසෙන් රජු සහ මහා පරාක්‍රමබාහු රජු යන තිදෙනාම ලංකාවේ වාරිමාර්ග ඉතිහාසයේ දැවැන්ත පෙරළියක් කරමින් වැව් සහ ඇළ මාර්ග විශාල සංඛ්‍යාවක් ඉදි කළ ශ්‍රේෂ්ඨ පාලකයින් වේ.', 'වසභ රජු, මහසෙන් රජු සහ මහා පරාක්‍රමබාහු රජු යන තිදෙනාම ලංකාවේ වාරිමාර්ග ඉතිහාසයේ දැවැන්ත පෙරළියක් කරමින් වැව් සහ ඇළ මාර්ග විශාල සංඛ්‍යාවක් ඉදි කළ ශ්‍රේෂ්ඨ පාලකයින් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5514fe2d-ed81-409d-9514-c6eb7f0e7008', '6a7ec166-b469-5029-a59b-f0cf534207cc', 'රට එක්සේසත් කිරීම', 'රට එක්සේසත් කිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e6171cfe-7763-4795-9647-6c58907a70dd', '6a7ec166-b469-5029-a59b-f0cf534207cc', 'විදේශ ආක්‍රමණ වලින් රට බේරා ගැනීම', 'විදේශ ආක්‍රමණ වලින් රට බේරා ගැනීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7e518522-b7a3-4aa1-8226-19dd152734a8', '6a7ec166-b469-5029-a59b-f0cf534207cc', 'විශාල වෙහෙර විහාර ඉදිකිරීම', 'විශාල වෙහෙර විහාර ඉදිකිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('84354684-4341-4cdd-a54b-ce8ea90cc78b', '6a7ec166-b469-5029-a59b-f0cf534207cc', 'වාරි කර්මාන්තයේ දියුණුවට කටයුතු කිරීම', 'වාරි කර්මාන්තයේ දියුණුවට කටයුතු කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('464c90c2-19b3-5220-a3dd-dc6df580b855', '0c3c990e-e81c-5492-9797-f946ca52bc04', 10, '<p>රටක දේශපාලන බලය මධ්‍යගත වූ විට,</p>', '<p>රටක දේශපාලන බලය මධ්‍යගත වූ විට,</p>', NULL, 'දේශපාලන බලය එක් මධ්‍යස්ථානයකට හෝ එක් පාලකයෙකු යටතට ගොනු වූ විට (මධ්‍යගත වූ විට), රට තුළ පැවති ප්‍රාදේශීය බෙදීම් නැති වී ඒකීය හෙවත් එක්සත් රාජ්‍යයක් බිහි වේ.', 'දේශපාලන බලය එක් මධ්‍යස්ථානයකට හෝ එක් පාලකයෙකු යටතට ගොනු වූ විට (මධ්‍යගත වූ විට), රට තුළ පැවති ප්‍රාදේශීය බෙදීම් නැති වී ඒකීය හෙවත් එක්සත් රාජ්‍යයක් බිහි වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('577b66b6-5eab-4ebc-9398-0c056e1d956a', '464c90c2-19b3-5220-a3dd-dc6df580b855', 'එක්සත් රාජ්‍යයක් බිහි වේ.', 'එක්සත් රාජ්‍යයක් බිහි වේ.', NULL, 'sanitized', 'v1', 0, 1);
