INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1c7f06b6-1a3d-5450-bce9-178c49d0f6ab', '0c3c990e-e81c-5492-9797-f946ca52bc04', 13, '<p>මහවැලි ගගේ අතු ගංගාව කුමක්ද?</p>', '<p>මහවැලි ගගේ අතු ගංගාව කුමක්ද?</p>', NULL, 'අඹන් ගඟ යනු මහවැලි ගඟට එකතු වන ප්‍රධානතම අතු ගංගාවකි. එය බෝවතැන්න ජලාශය හරහා ගලා යයි.', 'අඹන් ගඟ යනු මහවැලි ගඟට එකතු වන ප්‍රධානතම අතු ගංගාවකි. එය බෝවතැන්න ජලාශය හරහා ගලා යයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
