INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f7a94133-8717-4ed0-8dff-5d63d530838a', 'beb0cceb-7dc6-5932-81ae-6f9f058547e4', 'සිදුරු සහිත ගල් පතුරේ ඝනකම වැඩි කිරීමය.', 'සිදුරු සහිත ගල් පතුරේ ඝනකම වැඩි කිරීමය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8b0b1572-9feb-478c-b9ee-fddcf87456e4', 'beb0cceb-7dc6-5932-81ae-6f9f058547e4', 'සිදුරු සහිත ගල් පතුරේ ඝනකම අඩු කිරීම ය.', 'සිදුරු සහිත ගල් පතුරේ ඝනකම අඩු කිරීම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cb0622d9-9141-5d6e-8a4d-e1d38933894c', '0c3c990e-e81c-5492-9797-f946ca52bc04', 18, '<p>අතීතයේ ශ්‍රී ලංකාව හා පැවැති විදේශ වෙළෙඳ ගනුදෙනුවල දී භාවිත කළ කාසි පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>අතීතයේ ශ්‍රී ලංකාව හා පැවැති විදේශ වෙළෙඳ ගනුදෙනුවල දී භාවිත කළ කාසි පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'අතීතයේ ලංකාව මධ්‍යස්ථානයක් කරගනිමින් සිදුවූ ජාත්‍යන්තර වෙළඳාමේදී විවිධ රටවලින් පැමිණි වෙළඳුන් තමන්ගේ රටේ කාසි මෙරට වෙළඳාම සඳහා ද භාවිතා කළහ (උදා: රෝම කාසි, චීන කාසි).', 'අතීතයේ ලංකාව මධ්‍යස්ථානයක් කරගනිමින් සිදුවූ ජාත්‍යන්තර වෙළඳාමේදී විවිධ රටවලින් පැමිණි වෙළඳුන් තමන්ගේ රටේ කාසි මෙරට වෙළඳාම සඳහා ද භාවිතා කළහ (උදා: රෝම කාසි, චීන කාසි).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
