INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9c80920d-f1ac-5178-82e4-047baf3a4670', '0c3c990e-e81c-5492-9797-f946ca52bc04', 23, '<p>පෘතුගීසීන් හා යාපනේ පාලකයන් අතර නිරතුරුව ගැටුම් ඇතිවීම කෙරෙහි බලපෑ ප්‍රධානතම හේතුව වූයේ,</p>', '<p>පෘතුගීසීන් හා යාපනේ පාලකයන් අතර නිරතුරුව ගැටුම් ඇතිවීම කෙරෙහි බලපෑ ප්‍රධානතම හේතුව වූයේ,</p>', NULL, 'යාපනයේ පාලකයාව සිටි I වන සංකිලි රජු විසින් කතෝලික ආගම වැළඳගත් මන්නාරමේ වැසියන් විශාල පිරිසක් ඝාතනය කිරීම සහ පෘතුගීසීන්ගේ කතෝලික ආගමික ව්‍යාප්තියට යාපනය පාලකයින්ගෙන් එල්ල වූ දැඩි විරෝධය ගැටුම් වලට ප්‍රධාන හේතුව විය.', 'යාපනයේ පාලකයාව සිටි I වන සංකිලි රජු විසින් කතෝලික ආගම වැළඳගත් මන්නාරමේ වැසියන් විශාල පිරිසක් ඝාතනය කිරීම සහ පෘතුගීසීන්ගේ කතෝලික ආගමික ව්‍යාප්තියට යාපනය පාලකයින්ගෙන් එල්ල වූ දැඩි විරෝධය ගැටුම් වලට ප්‍රධාන හේතුව විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9ea7eb76-916d-4069-b6e8-9765e9af2ed5', '9c80920d-f1ac-5178-82e4-047baf3a4670', 'පහතරට සිංහල පාලකයන්ගේ පෘතුගීසි විරෝධි සටන් වලට යාපනේ පාලකයන් සහාය දැක්වීමයි.', 'පහතරට සිංහල පාලකයන්ගේ පෘතුගීසි විරෝධි සටන් වලට යාපනේ පාලකයන් සහාය දැක්වීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('53f44393-e745-4adf-b53d-3b11fc3a28b2', '9c80920d-f1ac-5178-82e4-047baf3a4670', 'මන්නාරම් මුහුදේ මුතු කිමිදීමේ කටයුතු වල දී යාපනේ පාලකයන්ගෙන් පෘතුගීසීන්ට බාධා එල්ල වීමයි.', 'මන්නාරම් මුහුදේ මුතු කිමිදීමේ කටයුතු වල දී යාපනේ පාලකයන්ගෙන් පෘතුගීසීන්ට බාධා එල්ල වීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a1899802-f91d-4b50-8090-0d7813fd8553', '9c80920d-f1ac-5178-82e4-047baf3a4670', 'යාපනේ සිංහාසනයට උරුමකම් කියූ ඇතැම් ද්‍රවිඩ කුමාරවරුන් පෘතුගීසීන්ට පක්ෂව කටයුතු කිරීමයි.', 'යාපනේ සිංහාසනයට උරුමකම් කියූ ඇතැම් ද්‍රවිඩ කුමාරවරුන් පෘතුගීසීන්ට පක්ෂව කටයුතු කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c37913c5-97cc-4510-b2df-5fc0e0e71cdb', '9c80920d-f1ac-5178-82e4-047baf3a4670', 'යාපනය රාජධානියේ කතෝලික ආගම ප්‍රචාරය කිරීමට එරෙහිව එහි පාලකයන්ගෙන් දැඩි විරෝධතා එල්ල වීමයි.', 'යාපනය රාජධානියේ කතෝලික ආගම ප්‍රචාරය කිරීමට එරෙහිව එහි පාලකයන්ගෙන් දැඩි විරෝධතා එල්ල වීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b7c31d0f-7a8a-567c-985b-85f6c4366c05', '0c3c990e-e81c-5492-9797-f946ca52bc04', 24, '<p>මධ්‍යතන යුගයේ දී ආසියානු වෙළෙඳ ඒකාධිකාරය හිමි වූයේ,</p>', '<p>මධ්‍යතන යුගයේ දී ආසියානු වෙළෙඳ ඒකාධිකාරය හිමි වූයේ,</p>', NULL, 'මධ්‍යතන යුගයේදී පෙරදිග (ආසියානු) සහ අපරදිග අතර වෙළෙඳාමේ ඒකාධිකාරය (Monopoly) සම්පූර්ණයෙන්ම පාහේ අරාබි ජාතික මුස්ලිම් වෙළඳුන් සතුව පැවතුණි.', 'මධ්‍යතන යුගයේදී පෙරදිග (ආසියානු) සහ අපරදිග අතර වෙළෙඳාමේ ඒකාධිකාරය (Monopoly) සම්පූර්ණයෙන්ම පාහේ අරාබි ජාතික මුස්ලිම් වෙළඳුන් සතුව පැවතුණි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
