INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cbb2a160-c647-4212-ac52-3a78519438b4', '28e975e9-08b9-5543-965e-369b0cebd26e', 'අස්වැන්නෙන් කොටසක් බදු වශයෙන් ගෙවීමට සිදු වූ නිසාය.', 'අස්වැන්නෙන් කොටසක් බදු වශයෙන් ගෙවීමට සිදු වූ නිසාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3052dd89-79aa-5bc6-8b96-872dadf9094a', '0c3c990e-e81c-5492-9797-f946ca52bc04', 39, '<p>"මේ අවස්ථාවේ අප බලය අල්ලා නොගතහොත් ඉතිහාසය අපට සමාව නොදෙනු ඇත." මෙම ප්‍රකාශය කිනම් විප්ලවයක් හා සම්බන්ධ වේ ද?</p>', '<p>"මේ අවස්ථාවේ අප බලය අල්ලා නොගතහොත් ඉතිහාසය අපට සමාව නොදෙනු ඇත." මෙම ප්‍රකාශය කිනම් විප්ලවයක් හා සම්බන්ධ වේ ද?</p>', NULL, 'මෙම ප්‍රකාශය 1917 රුසියානු (බොල්ෂෙවික්) විප්ලවයේ නායකයා වූ ව්ලැඩිමීර් ලෙනින් විසින් බලය අල්ලා ගැනීම වේගවත් කිරීම සඳහා තම පක්ෂ සාමාජිකයින්ට කරන ලද ප්‍රකට ප්‍රකාශයකි.', 'මෙම ප්‍රකාශය 1917 රුසියානු (බොල්ෂෙවික්) විප්ලවයේ නායකයා වූ ව්ලැඩිමීර් ලෙනින් විසින් බලය අල්ලා ගැනීම වේගවත් කිරීම සඳහා තම පක්ෂ සාමාජිකයින්ට කරන ලද ප්‍රකට ප්‍රකාශයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
