INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7ce57446-578b-4e36-b72c-7a854bd068a2', '0fb80307-d636-5c50-a9c6-86559d0f0beb', 'පරිගණකය තුළ ඇති කුඩා පංකාව (fan) ආදේශ කිරීම පමණක්', 'පරිගණකය තුළ ඇති කුඩා පංකාව (fan) ආදේශ කිරීම පමණක්', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5323a391-a2c0-4dcd-81c2-ffea92a35e0e', '0fb80307-d636-5c50-a9c6-86559d0f0beb', 'දෘඪ ඩිස්කය වෙනුවට ඝන තත්ත්ව ධාවකයක් (Solid State Drive) ආදේශ කර මෙහෙයුම් පද්ධතිය නැවත ස්ථාපනය කිරීම', 'දෘඪ ඩිස්කය වෙනුවට ඝන තත්ත්ව ධාවකයක් (Solid State Drive) ආදේශ කර මෙහෙයුම් පද්ධතිය නැවත ස්ථාපනය කිරීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d942d006-99a0-5c81-b1b0-2fd563060d6d', '0d3d84ff-3666-5670-a6d6-0de604144293', 7, '<p>දශමය $14.25_{10}$ ට තුල්‍ය වන නිවැරදි ද්විමය සංඛ්‍යාව කුමක්ද?</p>', '<p>දශමය $14.25_{10}$ ට තුල්‍ය වන නිවැරදි ද්විමය සංඛ්‍යාව කුමක්ද?</p>', NULL, 'පූර්ණ සංඛ්‍යා කොටස: $14_{10} = 1110_2$.<br>දශම කොටස: $0.25 \times 2 = 0.5 (0)$, $0.5 \times 2 = 1.0 (1)$, එනම් $0.01_2$.<br>එකතු කළ විට: $1110.01_2$.', 'පූර්ණ සංඛ්‍යා කොටස: $14_{10} = 1110_2$.<br>දශම කොටස: $0.25 \times 2 = 0.5 (0)$, $0.5 \times 2 = 1.0 (1)$, එනම් $0.01_2$.<br>එකතු කළ විට: $1110.01_2$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
