INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5051eef7-9114-5cab-bee3-fe20b4b323d5', '0d3d84ff-3666-5670-a6d6-0de604144293', 8, '<p>අෂ්ඨමය $120_8$ ට තුල්‍ය වන නිවැරදි දශමය සංඛ්‍යාව කුමක් ද?</p>', '<p>අෂ්ඨමය $120_8$ ට තුල්‍ය වන නිවැරදි දශමය සංඛ්‍යාව කුමක් ද?</p>', NULL, '$120_8 = 1 \times 8^2 + 2 \times 8^1 + 0 \times 8^0$<br>$= 1 \times 64 + 2 \times 8 + 0$<br>$= 64 + 16 = 80_{10}$.', '$120_8 = 1 \times 8^2 + 2 \times 8^1 + 0 \times 8^0$<br>$= 1 \times 64 + 2 \times 8 + 0$<br>$= 64 + 16 = 80_{10}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
