INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c7af007d-c46b-5784-aad9-2fd7ab54884a', '0d3d84ff-3666-5670-a6d6-0de604144293', 9, '<p>පහත කවරක් නිවැරදි වේ ද?<br><br>I: $EB7_{16}=1110\ 1011\ 0111_2$<br>II: $84_{10}=1010100_2$<br>III: $753_8=1001011_2$</p>', '<p>පහත කවරක් නිවැරදි වේ ද?<br><br>I: $EB7_{16}=1110\ 1011\ 0111_2$<br>II: $84_{10}=1010100_2$<br>III: $753_8=1001011_2$</p>', NULL, 'I: $E=1110$, $B=1011$, $7=0111$ (සත්‍යය).<br>II: $84_{10} = 64 + 16 + 4 = 1000000_2 + 10000_2 + 100_2 = 1010100_2$ (සත්‍යය).<br>III: $753_8 = 111\ 101\ 011_2$, එය $1001011_2$ නොවේ (අසත්‍යය).<br>එබැවින් I සහ II පමණි.', 'I: $E=1110$, $B=1011$, $7=0111$ (සත්‍යය).<br>II: $84_{10} = 64 + 16 + 4 = 1000000_2 + 10000_2 + 100_2 = 1010100_2$ (සත්‍යය).<br>III: $753_8 = 111\ 101\ 011_2$, එය $1001011_2$ නොවේ (අසත්‍යය).<br>එබැවින් I සහ II පමණි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
