INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1ed145e3-2c4f-52c2-a0d7-a8189e33bb93', '0d3d84ff-3666-5670-a6d6-0de604144293', 19, '<p>සමත්ව (parity) බිටු සම්බන්ධයෙන් පහත කවරක් නිවැරදි ද?</p>', '<p>සමත්ව (parity) බිටු සම්බන්ධයෙන් පහත කවරක් නිවැරදි ද?</p>', NULL, 'සමත්ව බිටු (Parity bit) යොදාගන්නේ දෝෂ හඳුනාගැනීමටයි. එහිදී සම්ප්‍රේෂණය කරන දත්ත වල 1 ඉලක්කම් ගණන ඉරට්ටේ (Even parity) හෝ ඔත්තේ (Odd parity) බවට පත් කිරීම සඳහා 1 හෝ 0 අගයක් එකතු කරනු ලැබේ.', 'සමත්ව බිටු (Parity bit) යොදාගන්නේ දෝෂ හඳුනාගැනීමටයි. එහිදී සම්ප්‍රේෂණය කරන දත්ත වල 1 ඉලක්කම් ගණන ඉරට්ටේ (Even parity) හෝ ඔත්තේ (Odd parity) බවට පත් කිරීම සඳහා 1 හෝ 0 අගයක් එකතු කරනු ලැබේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2e8a35b4-e64e-4455-8203-f920f8ccaff6', '1ed145e3-2c4f-52c2-a0d7-a8189e33bb93', 'බිටු සමූහයක සමත්ව බිටුව, එම බිටු සමූහය සන්නිවේදනයෙන් පසුව හරිගැස්සවෙයි.', 'බිටු සමූහයක සමත්ව බිටුව, එම බිටු සමූහය සන්නිවේදනයෙන් පසුව හරිගැස්සවෙයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fd47cd37-c06a-4ff5-baa1-8def2b45c413', '1ed145e3-2c4f-52c2-a0d7-a8189e33bb93', 'බිටු සමූහයක සමත්ව බිටුව තෝරා ගැනෙනුයේ එම සමූහයේ මුළු 1- බිටු ගණන ඉරට්ටේ හෝ ඔත්තේ හෝ වන පරිදිය.', 'බිටු සමූහයක සමත්ව බිටුව තෝරා ගැනෙනුයේ එම සමූහයේ මුළු 1- බිටු ගණන ඉරට්ටේ හෝ ඔත්තේ හෝ වන පරිදිය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e00bb841-53d2-44fc-a4a0-3ecb410f1c5b', '1ed145e3-2c4f-52c2-a0d7-a8189e33bb93', 'සන්නිවේදනයක සම්ප්‍රේෂණ වේගය සමත්ව බිටු මගින් වැඩි කෙරේ.', 'සන්නිවේදනයක සම්ප්‍රේෂණ වේගය සමත්ව බිටු මගින් වැඩි කෙරේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('de86d61a-9b2b-4fe1-b517-f33ea569d248', '1ed145e3-2c4f-52c2-a0d7-a8189e33bb93', 'වැරදි නිවැරදි කිරීමට, සන්නිවේදනයකින් පසුව සමත්ව බිටු එකතු කෙරේ.', 'වැරදි නිවැරදි කිරීමට, සන්නිවේදනයකින් පසුව සමත්ව බිටු එකතු කෙරේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ab7ba856-7a82-4a78-89d6-a0fca8326684', '1ed145e3-2c4f-52c2-a0d7-a8189e33bb93', 'දත්ත සම්ප්‍රේෂණයකට අවශ්‍ය ගුප්ත කේතනය (encryption) සමත්ව බිටු මගින් සැපයේ.', 'දත්ත සම්ප්‍රේෂණයකට අවශ්‍ය ගුප්ත කේතනය (encryption) සමත්ව බිටු මගින් සැපයේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('81e3b0fa-ff92-5f96-9695-47b8f40d10b9', '0d3d84ff-3666-5670-a6d6-0de604144293', 20, '<p>පොදු ස්විච දුරකථන ජාල (PSTN) මඟකින් ප්‍රතිසම (analog) සංඥාඥාවක් ලද විට මොඩමයකින් කුමක් සිදු වේ ද?</p>', '<p>පොදු ස්විච දුරකථන ජාල (PSTN) මඟකින් ප්‍රතිසම (analog) සංඥාඥාවක් ලද විට මොඩමයකින් කුමක් සිදු වේ ද?</p>', NULL, 'දුරකථන රැහැන් ඔස්සේ එන ප්‍රතිසම (Analog) සංඥාව, පරිගණකයට තේරුම් ගත හැකි අංකිත (Digital) සංඥාවක් බවට පත් කිරීම එනම් විමූර්ජනය (Demodulation) කිරීම මොඩමයක් මගින් සිදු කරයි.', 'දුරකථන රැහැන් ඔස්සේ එන ප්‍රතිසම (Analog) සංඥාව, පරිගණකයට තේරුම් ගත හැකි අංකිත (Digital) සංඥාවක් බවට පත් කිරීම එනම් විමූර්ජනය (Demodulation) කිරීම මොඩමයක් මගින් සිදු කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c1e95edd-4c54-4571-8f89-0b5b94f6770a', '81e3b0fa-ff92-5f96-9695-47b8f40d10b9', 'වඩාත් පැහැදිලි ගුණය සදහා එය සංඥාව විස්තාරණය (amplify) කරයි.', 'වඩාත් පැහැදිලි ගුණය සදහා එය සංඥාව විස්තාරණය (amplify) කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a43b17c0-aaab-4ad7-a432-57af2c48ece1', '81e3b0fa-ff92-5f96-9695-47b8f40d10b9', 'ආචයනය (storage) සදහා එය සංඥාව සම්පීඩනය (compress) කරයි.', 'ආචයනය (storage) සදහා එය සංඥාව සම්පීඩනය (compress) කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('44c2a40b-9751-46a6-b5d9-453bb7cff2c9', '81e3b0fa-ff92-5f96-9695-47b8f40d10b9', 'එය සංඥාව යලි අංකිත (digital) ස්වරූපයට විමුර්ජනය (demodulate) කරයි.', 'එය සංඥාව යලි අංකිත (digital) ස්වරූපයට විමුර්ජනය (demodulate) කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3daae613-7de1-48c1-9496-ce91221f8c16', '81e3b0fa-ff92-5f96-9695-47b8f40d10b9', 'එය ආරක්ෂාව සදහා සංඥාව ගුප්ත කේතනය (encrypt) කරයි.', 'එය ආරක්ෂාව සදහා සංඥාව ගුප්ත කේතනය (encrypt) කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fdee7d23-0a8e-4492-bc98-05e8b9ee5a59', '81e3b0fa-ff92-5f96-9695-47b8f40d10b9', 'සම්ප්‍රේෂණය සදහා එය සංඥාව තවදුරටත් මූර්ජනය (modulate) කරයි.', 'සම්ප්‍රේෂණය සදහා එය සංඥාව තවදුරටත් මූර්ජනය (modulate) කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('55550863-be67-54bf-8303-fb809cfd2f5b', '0d3d84ff-3666-5670-a6d6-0de604144293', 21, '<p>ජාලයක ඇති ස්විචයක් වඩාත් හොඳින් විස්තර කරන්නේ පහත කුමන ප්‍රකාශයෙන් ද?</p>', '<p>ජාලයක ඇති ස්විචයක් වඩාත් හොඳින් විස්තර කරන්නේ පහත කුමන ප්‍රකාශයෙන් ද?</p>', NULL, 'Hub එකක් මෙන් නොව Switch එකක් මගින් පැමිණෙන දත්ත පැකට්ටුවේ ඇති MAC ලිපිනය කියවා, අදාළ දත්ත පැකට්ටුව නිවැරදි උපාංගය සම්බන්ධ කර ඇති කෙවෙනියට (port) පමණක් යොමු කරයි.', 'Hub එකක් මෙන් නොව Switch එකක් මගින් පැමිණෙන දත්ත පැකට්ටුවේ ඇති MAC ලිපිනය කියවා, අදාළ දත්ත පැකට්ටුව නිවැරදි උපාංගය සම්බන්ධ කර ඇති කෙවෙනියට (port) පමණක් යොමු කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
