INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('657d0c12-e1be-482f-8022-877812ad3873', '55550863-be67-54bf-8303-fb809cfd2f5b', 'දත්ත අපේක්ශිත උපාංගයට පමණක් එය දත්ත යොමු කරයි.', 'දත්ත අපේක්ශිත උපාංගයට පමණක් එය දත්ත යොමු කරයි.', NULL, 'sanitized', 'v1', 3, 0);
