INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ad72ea45-b2de-4a57-bf19-8bb6c94ba640', '071af135-6300-5d75-a0d1-5ed1a33d28c0', 'A - NIC අංකය ලබා ගන්න, B - දැනට ඇති වෙන් කිරීම් පෙන්වන්න, C - දිනය/වේලාව ලබාගන්න, D - පරිශීලකයාගේ හර/ණය පත් ගෙවීම සම්පූර්ණ කරන්න', 'A - NIC අංකය ලබා ගන්න, B - දැනට ඇති වෙන් කිරීම් පෙන්වන්න, C - දිනය/වේලාව ලබාගන්න, D - පරිශීලකයාගේ හර/ණය පත් ගෙවීම සම්පූර්ණ කරන්න', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a592ff34-06d5-5f2e-8d3d-c71f50c82c0b', '0d3d84ff-3666-5670-a6d6-0de604144293', 30, '<p>ඉහත පද්ධතිය ගැන පහත කවර යෝජනාවක් නුසුදුසු වේ ද?</p>', '<p>ඉහත පද්ධතිය ගැන පහත කවර යෝජනාවක් නුසුදුසු වේ ද?</p>', NULL, 'ක්‍රීඩා පිටිය වෙන් කිරීම සඳහා NIC අංකය ප්‍රමාණවත් වන අතර, සෑම වෙන්කිරීමකදීම ගෙදර ලිපිනය ඇතුළත් කිරීම අනවශ්‍ය සහ පරිශීලකයාට කරදරකාරී වේ. එබැවින් එය නුසුදුසු යෝජනාවකි.', 'ක්‍රීඩා පිටිය වෙන් කිරීම සඳහා NIC අංකය ප්‍රමාණවත් වන අතර, සෑම වෙන්කිරීමකදීම ගෙදර ලිපිනය ඇතුළත් කිරීම අනවශ්‍ය සහ පරිශීලකයාට කරදරකාරී වේ. එබැවින් එය නුසුදුසු යෝජනාවකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('90a39d39-16a1-4df8-8fe4-c882e6e7f212', 'a592ff34-06d5-5f2e-8d3d-c71f50c82c0b', 'අවශ්‍ය විටක, දී ඇති දිනයකට අදාළ වෙන්කිරීම් වල ලැයිස්තුවක් ලබා දිය යුතු ය.', 'අවශ්‍ය විටක, දී ඇති දිනයකට අදාළ වෙන්කිරීම් වල ලැයිස්තුවක් ලබා දිය යුතු ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7b35e1ca-691f-4951-a0b3-c51128435b16', 'a592ff34-06d5-5f2e-8d3d-c71f50c82c0b', 'සිසුවෙකු වෙන් කිරීමක් සිදු කරන සෑම විටකම ඔහු/ඇය තම ගෙදර ලිපිනය ඇතුළත් කිරීම අවශ්‍ය කළ යුතු ය.', 'සිසුවෙකු වෙන් කිරීමක් සිදු කරන සෑම විටකම ඔහු/ඇය තම ගෙදර ලිපිනය ඇතුළත් කිරීම අවශ්‍ය කළ යුතු ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('194be00f-3517-41b5-94e4-669690031b9f', 'a592ff34-06d5-5f2e-8d3d-c71f50c82c0b', 'NIC අංකයේ වලංගුතාවය පිරික්සීම සුදුසු වේ.', 'NIC අංකයේ වලංගුතාවය පිරික්සීම සුදුසු වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ec2cbd50-a2ef-43bb-a84d-f27ed1a44be2', 'a592ff34-06d5-5f2e-8d3d-c71f50c82c0b', 'වෙන්කිරිම් පාසල් වේලාවන් සමඟ ඝට්ටනය නොවිය යුතු ය.', 'වෙන්කිරිම් පාසල් වේලාවන් සමඟ ඝට්ටනය නොවිය යුතු ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('25ef0874-33cf-47a8-85ef-0bf6a779a13c', 'a592ff34-06d5-5f2e-8d3d-c71f50c82c0b', 'සාධාරණය සඳහා, යම් NIC අංකයකට දිනකට ඉඩ දෙන වෙන් කිරීම් ගණන සීමා කළ යුතු ය.', 'සාධාරණය සඳහා, යම් NIC අංකයකට දිනකට ඉඩ දෙන වෙන් කිරීම් ගණන සීමා කළ යුතු ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('38095ea5-64eb-554e-b9f9-e29b709c8d0d', '0d3d84ff-3666-5670-a6d6-0de604144293', 31, '<p>ආයතනයක වැඩසටහනකට ලියාපදිංචි වී ඇති සිසුවකුට අදාළ පහත සම්බන්ධය සලකන්න.<br>STUDENT(Sno, Snic, Sname, Sphone, Prog_number)<br><br>පහත කවරක් නිවැරදි ද?<br>A - Sno ප්‍රාථමික (primary) යතුරක් විය හැකි ය.<br>B - Snic නිරූප්‍ය (candidate) යතුරක් විය හැකිය.<br>C - Prog_number ආගන්තුක (foreign) යතුරක් විය හැකි ය.</p>
