INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7a48a392-116f-575a-8463-0ba670dc257f', '0d3d84ff-3666-5670-a6d6-0de604144293', 35, '<p>දත්ත සමුදා ප්‍රමත කරනයේ (normalization) මූලික අරමුණ කුමක් ද?</p>', '<p>දත්ත සමුදා ප්‍රමත කරනයේ (normalization) මූලික අරමුණ කුමක් ද?</p>', NULL, 'ප්‍රමතකරණයේ (Normalization) ප්‍රධානතම අරමුණ වන්නේ දත්ත සමුදායේ අනවශ්‍ය ලෙස දත්ත නැවත නැවත ගබඩා වීම (Data redundancy) අවම කිරීම සහ දත්ත ඇතුළත් කිරීමේදී, මකා දැමීමේදී හා යාවත්කාලීන කිරීමේදී ඇතිවන විෂමතා (Anomalies) ඉවත් කිරීමයි.', 'ප්‍රමතකරණයේ (Normalization) ප්‍රධානතම අරමුණ වන්නේ දත්ත සමුදායේ අනවශ්‍ය ලෙස දත්ත නැවත නැවත ගබඩා වීම (Data redundancy) අවම කිරීම සහ දත්ත ඇතුළත් කිරීමේදී, මකා දැමීමේදී හා යාවත්කාලීන කිරීමේදී ඇතිවන විෂමතා (Anomalies) ඉවත් කිරීමයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bfbc36e4-5679-4934-bcf9-020173c50968', '7a48a392-116f-575a-8463-0ba670dc257f', 'අනු පිටපත් වීම (redundancy) සහ නොගැලපීම් (annomalies) ඉවත් කිරීම', 'අනු පිටපත් වීම (redundancy) සහ නොගැලපීම් (annomalies) ඉවත් කිරීම', NULL, 'sanitized', 'v1', 0, 1);
