INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1b2f74b9-dbe1-4f07-ad5d-14d2d1a89154', '7a48a392-116f-575a-8463-0ba670dc257f', 'දත්ත සමුදා විමසුම් වේගවත් කිරීම', 'දත්ත සමුදා විමසුම් වේගවත් කිරීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9659b69a-f321-5195-9fa4-ed104fbe4aca', '0d3d84ff-3666-5670-a6d6-0de604144293', 36, '<p>පහත කවරක් මගින් USER සම්බන්ධයේ City උපලක්ෂණයේ ඇති සියලු ''Mahawa'' ලෙස ඇති තැන් ''Maho'' ලෙස වෙනස් කරයි ද?</p>', '<p>පහත කවරක් මගින් USER සම්බන්ධයේ City උපලක්ෂණයේ ඇති සියලු ''Mahawa'' ලෙස ඇති තැන් ''Maho'' ලෙස වෙනස් කරයි ද?</p>', NULL, 'දත්ත සමුදායක පවතින දත්ත යාවත්කාලීන කිරීම සඳහා SQL හි භාවිත වන්නේ ''UPDATE'' ප්‍රකාශයයි. එහි නිවැරදි ආකෘතිය `UPDATE table_name SET column1 = value1 WHERE condition;` වේ.', 'දත්ත සමුදායක පවතින දත්ත යාවත්කාලීන කිරීම සඳහා SQL හි භාවිත වන්නේ ''UPDATE'' ප්‍රකාශයයි. එහි නිවැරදි ආකෘතිය `UPDATE table_name SET column1 = value1 WHERE condition;` වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
