INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5b71dede-f5df-5f00-a5cb-4d18c0ca9bf6', '0d3d84ff-3666-5670-a6d6-0de604144293', 38, '<p>පහත පයිතන් කේතයේ $a=5$, $b=3$, $c=2$ සහ $d=6$ නම් එහි ක්‍රියාත්මක ප්‍රතිදානය කුමක් වේ ද?<br><br>$x=(a-b)^{**}c+d\%c$<br>print(x)</p>', '<p>පහත පයිතන් කේතයේ $a=5$, $b=3$, $c=2$ සහ $d=6$ නම් එහි ක්‍රියාත්මක ප්‍රතිදානය කුමක් වේ ද?<br><br>$x=(a-b)^{**}c+d\%c$<br>print(x)</p>', NULL, '$x = (5 - 3)^2 + 6 \% 2$<br>$x = (2)^2 + 0$<br>$x = 4 + 0 = 4$.', '$x = (5 - 3)^2 + 6 \% 2$<br>$x = (2)^2 + 0$<br>$x = 4 + 0 = 4$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
