INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8c284aa0-4007-58de-a476-07835f91da4d', '0d3d84ff-3666-5670-a6d6-0de604144293', 39, '<p>පහත පයිතන් කේතයේ ක්‍රියාත්මක ප්‍රතිදානය කුමක් වේ ද?<br><br>qns = ["a", "b"]<br>for x in range (1,3):<br>  for y in qns:<br>    print(x,y, end='' '')</p>', '<p>පහත පයිතන් කේතයේ ක්‍රියාත්මක ප්‍රතිදානය කුමක් වේ ද?<br><br>qns = ["a", "b"]<br>for x in range (1,3):<br>  for y in qns:<br>    print(x,y, end='' '')</p>', NULL, '`range(1,3)` මගින් x සඳහා 1 සහ 2 ලබා දේ. පළමු වටයේදී $x=1$, y සඳහා ''a'' සහ ''b'' ආදේශ වී `1 a 1 b` මුද්‍රණය වේ. දෙවන වටයේදී $x=2$, y සඳහා ''a'' සහ ''b'' ආදේශ වී `2 a 2 b` මුද්‍රණය වේ.', '`range(1,3)` මගින් x සඳහා 1 සහ 2 ලබා දේ. පළමු වටයේදී $x=1$, y සඳහා ''a'' සහ ''b'' ආදේශ වී `1 a 1 b` මුද්‍රණය වේ. දෙවන වටයේදී $x=2$, y සඳහා ''a'' සහ ''b'' ආදේශ වී `2 a 2 b` මුද්‍රණය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
