INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b7d37d70-2235-59e9-a56d-79bc9b916cd0', '0d3d84ff-3666-5670-a6d6-0de604144293', 40, '<p>පහත පයිතන් කේතයේ ක්‍රියාත්මක ප්‍රතිදානය කුමක් වේ ද?<br><br>def list_operation(nlist):<br>  for i in range(len(nlist)):<br>    if i % 2 == 0:<br>      nlist[i] = nlist[i] ** 2<br>    else:<br>      nlist[i] = nlist[i] + 3<br>  return nlist<br><br>numbers = [1, 2, 3, 4, 5]<br>output = list_operation(numbers)<br>print (output)</p>', '<p>පහත පයිතන් කේතයේ ක්‍රියාත්මක ප්‍රතිදානය කුමක් වේ ද?<br><br>def list_operation(nlist):<br>  for i in range(len(nlist)):<br>    if i % 2 == 0:<br>      nlist[i] = nlist[i] ** 2<br>    else:<br>      nlist[i] = nlist[i] + 3<br>  return nlist<br><br>numbers = [1, 2, 3, 4, 5]<br>output = list_operation(numbers)<br>print (output)</p>', NULL, 'දර්ශකය (index) $i$ ඉරට්ටේ අගයන් ගන්නා විට (0, 2, 4) ලැයිස්තුවේ එම ස්ථානවල අගයන් වර්ග කෙරේ. $i$ ඔත්තේ වන විට (1, 3) එම අගයන්ට 3ක් එකතු කෙරේ.<br>i=0: $1^2 = 1$<br>i=1: $2+3 = 5$<br>i=2: $3^2 = 9$<br>i=3: $4+3 = 7$<br>i=4: $5^2 = 25$<br>ප්‍රතිදානය: `[1, 5, 9, 7, 25]`.', 'දර්ශකය (index) $i$ ඉරට්ටේ අගයන් ගන්නා විට (0, 2, 4) ලැයිස්තුවේ එම ස්ථානවල අගයන් වර්ග කෙරේ. $i$ ඔත්තේ වන විට (1, 3) එම අගයන්ට 3ක් එකතු කෙරේ.<br>i=0: $1^2 = 1$<br>i=1: $2+3 = 5$<br>i=2: $3^2 = 9$<br>i=3: $4+3 = 7$<br>i=4: $5^2 = 25$<br>ප්‍රතිදානය: `[1, 5, 9, 7, 25]`.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
