INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3d146b08-8147-5a02-aba6-cd28737f11af', '0d3d84ff-3666-5670-a6d6-0de604144293', 46, '<p>HTML පෝරමයක POST භාවිත කිරීමේ අරමුණ කුමක් ද?</p>', '<p>HTML පෝරමයක POST භාවිත කිරීමේ අරමුණ කුමක් ද?</p>', NULL, 'HTML ආකෘති (forms) වල ''POST'' ක්‍රමය භාවිත කරන්නේ පරිශීලකයා විසින් ඇතුළත් කරන ලද දත්ත ආරක්ෂිතව සැකසීම සඳහා සේවාදායකය (Server) වෙත යැවීමටයි.', 'HTML ආකෘති (forms) වල ''POST'' ක්‍රමය භාවිත කරන්නේ පරිශීලකයා විසින් ඇතුළත් කරන ලද දත්ත ආරක්ෂිතව සැකසීම සඳහා සේවාදායකය (Server) වෙත යැවීමටයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
