INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fe8de8d5-6cee-5b7b-b638-17e2c1d00c6e', '0d3d84ff-3666-5670-a6d6-0de604144293', 48, '<p>පහත කවරක් නිවැරදි වේ ද?</p>', '<p>පහත කවරක් නිවැරදි වේ ද?</p>', NULL, 'Arduino වල `Serial.begin(9600)` යන විධානය මගින් පරිගණකය සහ Arduino පුවරුව අතර ශ්‍රේණිගත සන්නිවේදනය සඳහා තත්පරයකට බිටු 9600 ක සම්මත බෝඩ් ශීඝ්‍රතාවක් (baud rate) සකසනු ලබයි.', 'Arduino වල `Serial.begin(9600)` යන විධානය මගින් පරිගණකය සහ Arduino පුවරුව අතර ශ්‍රේණිගත සන්නිවේදනය සඳහා තත්පරයකට බිටු 9600 ක සම්මත බෝඩ් ශීඝ්‍රතාවක් (baud rate) සකසනු ලබයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e9441542-db90-4f87-87b2-80dba7e32350', 'fe8de8d5-6cee-5b7b-b638-17e2c1d00c6e', 'ආඩුයිනෝ ඌනෝ (Arduino Uno) යනු සාර්ව ද්‍රව්‍ය අන්තර්ජාල (IoT) යෙදුම් ඇටවීමට භාවිත කරන නියමාවලි යයි (protocol).', 'ආඩුයිනෝ ඌනෝ (Arduino Uno) යනු සාර්ව ද්‍රව්‍ය අන්තර්ජාල (IoT) යෙදුම් ඇටවීමට භාවිත කරන නියමාවලි යයි (protocol).', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2d212eff-75a6-4a06-8c8e-ed0645cd6847', 'fe8de8d5-6cee-5b7b-b638-17e2c1d00c6e', 'LDR හා LED යනු, ආඩුයිනෝ ඌනෝ මත පදනම් වූ IoT යෙදුම් සඳහා භාවිත වන සංවේදක (sensors) වේ.', 'LDR හා LED යනු, ආඩුයිනෝ ඌනෝ මත පදනම් වූ IoT යෙදුම් සඳහා භාවිත වන සංවේදක (sensors) වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b288b27a-dbd7-4152-8060-002df069b780', 'fe8de8d5-6cee-5b7b-b638-17e2c1d00c6e', 'ආඩුයිනෝ ඌනෝ පුවරුවක් හා පරිගණකයක් අතර ශ්‍රේණිගත සන්නිවේදනයකට (serial communication) මුල පිරීමට Serial.begin(9600) වලංගු බෝඩි ශීඝ්‍රතාවක් (baud rate) සපයයි.', 'ආඩුයිනෝ ඌනෝ පුවරුවක් හා පරිගණකයක් අතර ශ්‍රේණිගත සන්නිවේදනයකට (serial communication) මුල පිරීමට Serial.begin(9600) වලංගු බෝඩි ශීඝ්‍රතාවක් (baud rate) සපයයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a854376e-50fe-41d5-a386-16fbb091ceaa', 'fe8de8d5-6cee-5b7b-b638-17e2c1d00c6e', 'ආඩුයිනෝ ඌනෝට දෘඪ ඩිස්කයක් නැති නිසා එයට අනවසර දත්ත ප්‍රවේශයන් විඳීමට සිදු නොවේ.', 'ආඩුයිනෝ ඌනෝට දෘඪ ඩිස්කයක් නැති නිසා එයට අනවසර දත්ත ප්‍රවේශයන් විඳීමට සිදු නොවේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c1bfdf36-a5f9-49f7-a52e-1ce96f7b7efb', 'fe8de8d5-6cee-5b7b-b638-17e2c1d00c6e', 'ATMega328P ක්ෂුද්‍ර පාලකයෙහි A0 - A5 අතර තුඩු හතරට ඊතර්නෙට් පළිහක් (ethernet shield) සම්බන්ධ කළ යුතුම ය.', 'ATMega328P ක්ෂුද්‍ර පාලකයෙහි A0 - A5 අතර තුඩු හතරට ඊතර්නෙට් පළිහක් (ethernet shield) සම්බන්ධ කළ යුතුම ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d832c557-7ae9-56db-8ba6-5973f3518071', '0d3d84ff-3666-5670-a6d6-0de604144293', 49, '<p>පහත කවර වගන්ති සත්‍ය වේ ද?<br><br>A - ජනක කෘතිම බුද්ධි (generative AI) මෙවලම්වලට, ඔවුන් ඉගෙන ගත් රටාවන්ට අනුව අලුත් අන්තර්ගත (content) හෝ දත්ත හෝ නිෂ්පාදනය කළ හැකි ය.<br>B - පරිශීලක ප්‍රේරක (user prompts) සහිත GPT වැනි ජනක කෘතිම බුද්ධි මෙවලම් භාවිතය යන්ත්‍ර - යන්ත්‍ර සහපැවැත්ම (coexistence) සඳහා උදාහරණයකි.<br>C - කෘතිම බුද්ධිය දැනට භාවිත වුවද, ප්‍රබල කෘතිම බුද්ධිය (strong AI) [මිනිස් සංජානනයට (cognition) සමාන සාමාන්‍ය බුද්ධිය හා හැකියාවන් සහිත යන්ත්‍ර] තවමත් න්‍යායාත්මක සංකල්පයක්ව පවතී.</p>', '<p>පහත කවර වගන්ති සත්‍ය වේ ද?<br><br>A - ජනක කෘතිම බුද්ධි (generative AI) මෙවලම්වලට, ඔවුන් ඉගෙන ගත් රටාවන්ට අනුව අලුත් අන්තර්ගත (content) හෝ දත්ත හෝ නිෂ්පාදනය කළ හැකි ය.<br>B - පරිශීලක ප්‍රේරක (user prompts) සහිත GPT වැනි ජනක කෘතිම බුද්ධි මෙවලම් භාවිතය යන්ත්‍ර - යන්ත්‍ර සහපැවැත්ම (coexistence) සඳහා උදාහරණයකි.<br>C - කෘතිම බුද්ධිය දැනට භාවිත වුවද, ප්‍රබල කෘතිම බුද්ධිය (strong AI) [මිනිස් සංජානනයට (cognition) සමාන සාමාන්‍ය බුද්ධිය හා හැකියාවන් සහිත යන්ත්‍ර] තවමත් න්‍යායාත්මක සංකල්පයක්ව පවතී.</p>', NULL, 'Generative AI මගින් නව දත්ත/අන්තර්ගත නිර්මාණය කරයි (A සත්‍යය). පරිශීලකයා විසින් Prompt ලබාදීම යන්ත්‍ර-යන්ත්‍ර (machine-machine) නොව මානව-යන්ත්‍ර (human-machine) අන්තර්ක්‍රියාවකි (B අසත්‍යය). මිනිසාට සමාන බුද්ධියක් ඇති Strong AI / AGI තවමත් යථාර්ථයක් වී නොමැත (C සත්‍යය).', 'Generative AI මගින් නව දත්ත/අන්තර්ගත නිර්මාණය කරයි (A සත්‍යය). පරිශීලකයා විසින් Prompt ලබාදීම යන්ත්‍ර-යන්ත්‍ර (machine-machine) නොව මානව-යන්ත්‍ර (human-machine) අන්තර්ක්‍රියාවකි (B අසත්‍යය). මිනිසාට සමාන බුද්ධියක් ඇති Strong AI / AGI තවමත් යථාර්ථයක් වී නොමැත (C සත්‍යය).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
