INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('922d230f-d896-56c4-83cb-15b5abd0fe78', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 3, '<p>පරමාණුවක ක්වොන්ටම් අංක $n=3$, $m_l=-1$ සහ $n=4$, $m_l=-1$ තිබිය හැකි කාක්ෂික සංඛ්‍යාව කොපමණ ද?</p>', '<p>පරමාණුවක ක්වොන්ටම් අංක $n=3$, $m_l=-1$ සහ $n=4$, $m_l=-1$ තිබිය හැකි කාක්ෂික සංඛ්‍යාව කොපමණ ද?</p>', NULL, '$n=3$ සඳහා $l=0, 1, 2$ විය හැක. මෙහිදී $m_l=-1$ විය හැක්කේ $l=1$ (3p) සහ $l=2$ (3d) සඳහා පමණි (එනම් කාක්ෂික 2යි).<br><br>$n=4$ සඳහා $l=0, 1, 2, 3$ විය හැක. මෙහිදී $m_l=-1$ විය හැක්කේ $l=1$ (4p), $l=2$ (4d), සහ $l=3$ (4f) සඳහා පමණි (එනම් කාක්ෂික 3යි).<br><br>එමනිසා, අදාළ මුළු කාක්ෂික සංඛ්‍යාව = $2 + 3 = 5$.', '$n=3$ සඳහා $l=0, 1, 2$ විය හැක. මෙහිදී $m_l=-1$ විය හැක්කේ $l=1$ (3p) සහ $l=2$ (3d) සඳහා පමණි (එනම් කාක්ෂික 2යි).<br><br>$n=4$ සඳහා $l=0, 1, 2, 3$ විය හැක. මෙහිදී $m_l=-1$ විය හැක්කේ $l=1$ (4p), $l=2$ (4d), සහ $l=3$ (4f) සඳහා පමණි (එනම් කාක්ෂික 3යි).<br><br>එමනිසා, අදාළ මුළු කාක්ෂික සංඛ්‍යාව = $2 + 3 = 5$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
