INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c3d909ff-6336-5d9a-80d4-60f62b7701c8', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 6, '<p>උෂ්ණත්වය $25^{\circ}C$ දී, $M(OH)_2$ ලෝහ හයිඩ්‍රොක්සයිඩයක සන්තෘප්ත ද්‍රාවණයක pH වන්නේ,<br>($25^{\circ}C$ දී $M(OH)_2$ හි $K_{sp} = 4 \times 10^{-12} \text{ mol}^3 \text{ dm}^{-9}$)</p>', '<p>උෂ්ණත්වය $25^{\circ}C$ දී, $M(OH)_2$ ලෝහ හයිඩ්‍රොක්සයිඩයක සන්තෘප්ත ද්‍රාවණයක pH වන්නේ,<br>($25^{\circ}C$ දී $M(OH)_2$ හි $K_{sp} = 4 \times 10^{-12} \text{ mol}^3 \text{ dm}^{-9}$)</p>', NULL, '$M(OH)_2(s) \rightleftharpoons M^{2+}(aq) + 2OH^-(aq)$<br><br>ද්‍රාව්‍යතාවය $s$ යැයි ගනිමු. එවිට $[M^{2+}] = s$ සහ $[OH^-] = 2s$ වේ.<br><br>$K_{sp} = [M^{2+}][OH^-]^2 = (s)(2s)^2 = 4s^3$<br><br>$4s^3 = 4 \times 10^{-12} \implies s^3 = 10^{-12} \implies s = 10^{-4} \text{ mol dm}^{-3}$<br><br>$[OH^-] = 2s = 2 \times 10^{-4} \text{ mol dm}^{-3}$<br><br>$pOH = -\log_{10}[OH^-] = -\log_{10}(2 \times 10^{-4}) = 4 - 0.3 = 3.7$<br><br>$pH = 14 - pOH = 14 - 3.7 = 10.3$<br><br>දී ඇති පිළිතුරු අතරින් වඩාත්ම ආසන්න අගය 10 වේ.', '$M(OH)_2(s) \rightleftharpoons M^{2+}(aq) + 2OH^-(aq)$<br><br>ද්‍රාව්‍යතාවය $s$ යැයි ගනිමු. එවිට $[M^{2+}] = s$ සහ $[OH^-] = 2s$ වේ.<br><br>$K_{sp} = [M^{2+}][OH^-]^2 = (s)(2s)^2 = 4s^3$<br><br>$4s^3 = 4 \times 10^{-12} \implies s^3 = 10^{-12} \implies s = 10^{-4} \text{ mol dm}^{-3}$<br><br>$[OH^-] = 2s = 2 \times 10^{-4} \text{ mol dm}^{-3}$<br><br>$pOH = -\log_{10}[OH^-] = -\log_{10}(2 \times 10^{-4}) = 4 - 0.3 = 3.7$<br><br>$pH = 14 - pOH = 14 - 3.7 = 10.3$<br><br>දී ඇති පිළිතුරු අතරින් වඩාත්ම ආසන්න අගය 10 වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
