INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dff86074-db23-5ec9-a96d-d0f040be74b6', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 7, '<p>$IO_3^+$, $NFCl_2$, $F_3ClO_2$ සහ $F_4BrO^-$ හි හැඩයන් වනුයේ පිළිවෙළින්,</p>', '<p>$IO_3^+$, $NFCl_2$, $F_3ClO_2$ සහ $F_4BrO^-$ හි හැඩයන් වනුයේ පිළිවෙළින්,</p>', NULL, '$IO_3^+$: මධ්‍යම පරමාණුව වටා ඉලෙක්ට්‍රෝන යුගල 3 ක් සහ එකදු හුදකලා යුගලයක් නැත. හැඩය: තලීය ත්‍රිකෝණාකාර (Trigonal planar).<br><br>$NFCl_2$: N වටා බන්ධන යුගල 3 ක් සහ එක් හුදකලා යුගලයක් පවතී. හැඩය: ත්‍රි ආනති පිරමිඩාකාර (Trigonal pyramidal).<br><br>$F_3ClO_2$: Cl වටා බන්ධන යුගල 5 ක් සහ හුදකලා යුගල නොමැත. හැඩය: ත්‍රි ආනති ද්වි පිරමිඩාකාර (Trigonal bipyramidal).<br><br>$F_4BrO^-$ (හෝ සමචතුරස්‍ර පිරමිඩාකාර විශේෂයක් මෙහි අදහස් වේ): මධ්‍යම පරමාණුව වටා බන්ධන යුගල 5 ක් සහ එක් හුදකලා යුගලයක් පවතී. හැඩය: සමචතුරස්‍ර පිරමිඩාකාර (Square pyramidal).', '$IO_3^+$: මධ්‍යම පරමාණුව වටා ඉලෙක්ට්‍රෝන යුගල 3 ක් සහ එකදු හුදකලා යුගලයක් නැත. හැඩය: තලීය ත්‍රිකෝණාකාර (Trigonal planar).<br><br>$NFCl_2$: N වටා බන්ධන යුගල 3 ක් සහ එක් හුදකලා යුගලයක් පවතී. හැඩය: ත්‍රි ආනති පිරමිඩාකාර (Trigonal pyramidal).<br><br>$F_3ClO_2$: Cl වටා බන්ධන යුගල 5 ක් සහ හුදකලා යුගල නොමැත. හැඩය: ත්‍රි ආනති ද්වි පිරමිඩාකාර (Trigonal bipyramidal).<br><br>$F_4BrO^-$ (හෝ සමචතුරස්‍ර පිරමිඩාකාර විශේෂයක් මෙහි අදහස් වේ): මධ්‍යම පරමාණුව වටා බන්ධන යුගල 5 ක් සහ එක් හුදකලා යුගලයක් පවතී. හැඩය: සමචතුරස්‍ර පිරමිඩාකාර (Square pyramidal).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1950d891-6155-45d0-86ef-d417d90e4e38', 'dff86074-db23-5ec9-a96d-d0f040be74b6', 'තලීය ත්‍රිකෝණාකාර, ත්‍රි ආනති පිරමිඩාකාර, සමචතුරස්‍ර පිරමිඩාකාර සහ ත්‍රි ආනති ද්වි පිරමිඩාකාරය.', 'තලීය ත්‍රිකෝණාකාර, ත්‍රි ආනති පිරමිඩාකාර, සමචතුරස්‍ර පිරමිඩාකාර සහ ත්‍රි ආනති ද්වි පිරමිඩාකාරය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('878cebda-2d8f-42fe-a958-1b0776e524f0', 'dff86074-db23-5ec9-a96d-d0f040be74b6', 'ත්‍රි ආනති පිරමිඩාකාර, තලීය ත්‍රිකෝණාකාර, සමචතුරස්‍ර පිරමිඩාකාර සහ ත්‍රි ආනති ද්වි පිරමිඩාකාරය.', 'ත්‍රි ආනති පිරමිඩාකාර, තලීය ත්‍රිකෝණාකාර, සමචතුරස්‍ර පිරමිඩාකාර සහ ත්‍රි ආනති ද්වි පිරමිඩාකාරය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c4b157ce-efcd-498c-b393-e811d358fb8c', 'dff86074-db23-5ec9-a96d-d0f040be74b6', 'ත්‍රි ආනති පිරමිඩාකාර, T -හැඩය, ත්‍රි ආනති ද්වි පිරමිඩාකාර සහ සමචතුරස්‍ර පිරමිඩාකාරය.', 'ත්‍රි ආනති පිරමිඩාකාර, T -හැඩය, ත්‍රි ආනති ද්වි පිරමිඩාකාර සහ සමචතුරස්‍ර පිරමිඩාකාරය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('38df1d27-ae14-4f11-9a06-889335555f6e', 'dff86074-db23-5ec9-a96d-d0f040be74b6', 'T-හැඩය, තලීය ත්‍රිකෝණාකාර, ත්‍රි ආනති ද්වි පිරමිඩාකාර සහ සමචතුරස්‍ර පිරමිඩාකාරය.', 'T-හැඩය, තලීය ත්‍රිකෝණාකාර, ත්‍රි ආනති ද්වි පිරමිඩාකාර සහ සමචතුරස්‍ර පිරමිඩාකාරය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('72bddcee-a7e4-413c-a522-a5963286ba2e', 'dff86074-db23-5ec9-a96d-d0f040be74b6', 'තලීය ත්‍රිකෝණාකාර, ත්‍රි ආනති පිරමිඩාකාර, ත්‍රි ආනති ද්වි පිරමිඩාකාර සහ සමචතුරස්‍ර පිරමිඩාකාරය.', 'තලීය ත්‍රිකෝණාකාර, ත්‍රි ආනති පිරමිඩාකාර, ත්‍රි ආනති ද්වි පිරමිඩාකාර සහ සමචතුරස්‍ර පිරමිඩාකාරය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e7ad319b-3b84-554f-b1ee-bdb113f2e69b', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 8, '<p>වැරදි වගන්තිය තෝරන්න.</p>', '<p>වැරදි වගන්තිය තෝරන්න.</p>', NULL, 'B, C සහ O යන මූලද්‍රව්‍ය සැලකූ විට, ආවර්තයක් ඔස්සේ දකුණට යත්ම ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය (Electron Gain Enthalpy) සාමාන්‍යයෙන් වඩාත් සෘණ වේ. මෙහිදී B හි අගය -27 kJ/mol පමණ වන අතර C හි අගය -122 kJ/mol පමණ වේ. එබැවින් අඩුම සෘණ අගය පෙන්වන්නේ B (බෝරෝන්) මිස C නොවේ. ඒ නිසා මෙම ප්‍රකාශය වැරදිය.', 'B, C සහ O යන මූලද්‍රව්‍ය සැලකූ විට, ආවර්තයක් ඔස්සේ දකුණට යත්ම ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය (Electron Gain Enthalpy) සාමාන්‍යයෙන් වඩාත් සෘණ වේ. මෙහිදී B හි අගය -27 kJ/mol පමණ වන අතර C හි අගය -122 kJ/mol පමණ වේ. එබැවින් අඩුම සෘණ අගය පෙන්වන්නේ B (බෝරෝන්) මිස C නොවේ. ඒ නිසා මෙම ප්‍රකාශය වැරදිය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4431e914-f830-4ec7-b63f-b199da7d117b', 'e7ad319b-3b84-554f-b1ee-bdb113f2e69b', '$NCl_3$, $SO_3$ සහ $PCl_5$ රසායනික ප්‍රභේද අතුරෙන් එකම ධ්‍රැවීය ප්‍රභේදය $NCl_3$ වේ.', '$NCl_3$, $SO_3$ සහ $PCl_5$ රසායනික ප්‍රභේද අතුරෙන් එකම ධ්‍රැවීය ප්‍රභේදය $NCl_3$ වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('06a8949d-59e5-4509-af2d-b0b6ef9243e6', 'e7ad319b-3b84-554f-b1ee-bdb113f2e69b', 'Mg, Al, Si සහ P මූලද්‍රව්‍ය අතුරෙන් අඩුම පළමු අයනීකරණ ශක්තිය Al පෙන්වයි.', 'Mg, Al, Si සහ P මූලද්‍රව්‍ය අතුරෙන් අඩුම පළමු අයනීකරණ ශක්තිය Al පෙන්වයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ddec5565-dc0d-473a-85ac-31b657d890ec', 'e7ad319b-3b84-554f-b1ee-bdb113f2e69b', 'B, C සහ O මූලද්‍රව්‍ය අතුරෙන් ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය සඳහා අඩුම සෘණ අගය C පෙන්වයි.', 'B, C සහ O මූලද්‍රව්‍ය අතුරෙන් ඉලෙක්ට්‍රෝන ලබාගැනීමේ ශක්තිය සඳහා අඩුම සෘණ අගය C පෙන්වයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ec1ba5e-f3bc-4fee-8049-febf2da830bc', 'e7ad319b-3b84-554f-b1ee-bdb113f2e69b', '$NO_3^-$, $SO_3$, $SO_3^{2-}$ සහ $ClF_3$ රසායනික ප්‍රභේද අතුරෙන් එකම හැඩය ඇත්තේ $NO_3^-$ සහ $SO_3$ වලට පමණි.', '$NO_3^-$, $SO_3$, $SO_3^{2-}$ සහ $ClF_3$ රසායනික ප්‍රභේද අතුරෙන් එකම හැඩය ඇත්තේ $NO_3^-$ සහ $SO_3$ වලට පමණි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c860b090-b30c-4787-b0ae-e4cd19ae8c9d', 'e7ad319b-3b84-554f-b1ee-bdb113f2e69b', '$Li^+$, $Na^+$, $Be^{2+}$ සහ $Mg^{2+}$ අයන අතුරෙන් විශාලත්වයෙන් වැඩිම වෙනස ඇත්තේ $Na^+$ සහ $Be^{2+}$ අතර ය.', '$Li^+$, $Na^+$, $Be^{2+}$ සහ $Mg^{2+}$ අයන අතුරෙන් විශාලත්වයෙන් වැඩිම වෙනස ඇත්තේ $Na^+$ සහ $Be^{2+}$ අතර ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c3209512-d1ad-503c-80db-ec5d1f95d594', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 9, '<p>පහත දැක්වෙන A, B, C, D, E සහ F සංයෝග සලකන්න.<br><br><br>මෙම සංයෝගයන්හි තාපාංක වල (B.P.) විචලනය දළ වශයෙන් වඩාත් හොඳින් පෙන්වනු ලබන්නේ,</p>
