INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cfb006e6-d9b5-5f79-b5eb-fa4f3f8f72c0', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 10, '<p>දී ඇති උෂ්ණත්වයකදී, උත්ප්‍රේරකයක් මගින් ප්‍රතික්‍රියාවක වේගය වැඩි කරන්නේ,</p>', '<p>දී ඇති උෂ්ණත්වයකදී, උත්ප්‍රේරකයක් මගින් ප්‍රතික්‍රියාවක වේගය වැඩි කරන්නේ,</p>', NULL, 'උත්ප්‍රේරකයක් (Catalyst) මගින් ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව වැඩි කරන්නේ, අඩු සක්‍රියන ශක්තියක් (Activation Energy) සහිත විකල්ප ප්‍රතික්‍රියා මාර්ගයක් (alternative pathway) ලබා දීම මගිනි.', 'උත්ප්‍රේරකයක් (Catalyst) මගින් ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව වැඩි කරන්නේ, අඩු සක්‍රියන ශක්තියක් (Activation Energy) සහිත විකල්ප ප්‍රතික්‍රියා මාර්ගයක් (alternative pathway) ලබා දීම මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('95727a5e-9327-442a-9a4e-3961abe2e81d', 'cfb006e6-d9b5-5f79-b5eb-fa4f3f8f72c0', 'ප්‍රතික්‍රියක අණුවල ඉහළ ශක්තියක් ඇති ගැටුම් සංඛ්‍යාව වැඩි කිරීමෙනි.', 'ප්‍රතික්‍රියක අණුවල ඉහළ ශක්තියක් ඇති ගැටුම් සංඛ්‍යාව වැඩි කිරීමෙනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d4841a8f-da00-4d29-9463-af5240055b49', 'cfb006e6-d9b5-5f79-b5eb-fa4f3f8f72c0', 'ප්‍රතික්‍රියක අණුවල චාලක ශක්තිය වැඩි කිරීමෙනි.', 'ප්‍රතික්‍රියක අණුවල චාලක ශක්තිය වැඩි කිරීමෙනි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e8859194-1cee-46a1-a1b4-07065d572aab', 'cfb006e6-d9b5-5f79-b5eb-fa4f3f8f72c0', 'ප්‍රතික්‍රියක අණු අතර ගැටුම් සංඛ්‍යාව වැඩි කිරීමෙනි.', 'ප්‍රතික්‍රියක අණු අතර ගැටුම් සංඛ්‍යාව වැඩි කිරීමෙනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3ef8a2ff-dade-4c3d-a839-cc1f80b93a76', 'cfb006e6-d9b5-5f79-b5eb-fa4f3f8f72c0', 'ප්‍රතික්‍රියාවේ සක්‍රියන ශක්තිය වැඩි කිරීමෙනි.', 'ප්‍රතික්‍රියාවේ සක්‍රියන ශක්තිය වැඩි කිරීමෙනි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6e0046eb-81ef-4279-837a-a73d20156347', 'cfb006e6-d9b5-5f79-b5eb-fa4f3f8f72c0', 'ප්‍රතික්‍රියාව සඳහා නව මාර්ගයක් ලබාදීමෙනි.', 'ප්‍රතික්‍රියාව සඳහා නව මාර්ගයක් ලබාදීමෙනි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cbdea1cd-ae53-5039-acf1-7d6f40637717', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 11, '<p>$FeCl_3(s)$, $NH_3(g)$ සහ $H_2O(l)$ සමග ප්‍රතික්‍රියා කර $Fe(OH)_3$ සහ $NH_4Cl$ සාදයි.<br>$FeCl_3(s)$ $97.5 \text{ g}$, $NH_3(g)$ $34 \text{ g}$ සහ $H_2O(l)$ $27 \text{ g}$ ප්‍රතික්‍රියා කිරීමට සැලැස්වූ විට ලබාගත හැකි වැඩිම $Fe(OH)_3$ ප්‍රමාණය වනුයේ,<br>($Fe=56, H=1, N=14, O=16, Cl=35.5$)</p>', '<p>$FeCl_3(s)$, $NH_3(g)$ සහ $H_2O(l)$ සමග ප්‍රතික්‍රියා කර $Fe(OH)_3$ සහ $NH_4Cl$ සාදයි.<br>$FeCl_3(s)$ $97.5 \text{ g}$, $NH_3(g)$ $34 \text{ g}$ සහ $H_2O(l)$ $27 \text{ g}$ ප්‍රතික්‍රියා කිරීමට සැලැස්වූ විට ලබාගත හැකි වැඩිම $Fe(OH)_3$ ප්‍රමාණය වනුයේ,<br>($Fe=56, H=1, N=14, O=16, Cl=35.5$)</p>', NULL, 'තුලිත රසායනික සමීකරණය:<br>$FeCl_3 + 3NH_3 + 3H_2O \rightarrow Fe(OH)_3 + 3NH_4Cl$<br><br>මවුලික ස්කන්ධ:<br>$FeCl_3 = 56 + (3 \times 35.5) = 162.5 \text{ g mol}^{-1}$<br>$NH_3 = 14 + 3 = 17 \text{ g mol}^{-1}$<br>$H_2O = 18 \text{ g mol}^{-1}$<br><br>ප්‍රතික්‍රියකවල මවුල ගණන:<br>$n(FeCl_3) = \frac{97.5}{162.5} = 0.6 \text{ mol}$<br>$n(NH_3) = \frac{34}{17} = 2.0 \text{ mol}$<br>$n(H_2O) = \frac{27}{18} = 1.5 \text{ mol}$<br><br>සීමාකාරී ප්‍රතික්‍රියකය (Limiting Reagent) සෙවීම:<br>$0.6 \text{ mol}$ $FeCl_3$ සම්පූර්ණයෙන් ප්‍රතික්‍රියා කිරීමට $1.8 \text{ mol}$ $NH_3$ සහ $1.8 \text{ mol}$ $H_2O$ අවශ්‍ය වේ. නමුත් පද්ධතියේ ඇත්තේ $1.5 \text{ mol}$ $H_2O$ පමණි. එමනිසා සීමාකාරී ප්‍රතික්‍රියකය $H_2O$ වේ.<br><br>සෑදෙන $Fe(OH)_3$ මවුල ගණන = $H_2O$ මවුල ගණන $/ 3 = \frac{1.5}{3} = 0.5 \text{ mol}$.<br><br>$Fe(OH)_3$ හි මවුලික ස්කන්ධය = $56 + 3 \times (16+1) = 107 \text{ g mol}^{-1}$.<br>ලැබෙන ස්කන්ධය = $0.5 \text{ mol} \times 107 \text{ g mol}^{-1} = 53.5 \text{ g}$.', 'තුලිත රසායනික සමීකරණය:<br>$FeCl_3 + 3NH_3 + 3H_2O \rightarrow Fe(OH)_3 + 3NH_4Cl$<br><br>මවුලික ස්කන්ධ:<br>$FeCl_3 = 56 + (3 \times 35.5) = 162.5 \text{ g mol}^{-1}$<br>$NH_3 = 14 + 3 = 17 \text{ g mol}^{-1}$<br>$H_2O = 18 \text{ g mol}^{-1}$<br><br>ප්‍රතික්‍රියකවල මවුල ගණන:<br>$n(FeCl_3) = \frac{97.5}{162.5} = 0.6 \text{ mol}$<br>$n(NH_3) = \frac{34}{17} = 2.0 \text{ mol}$<br>$n(H_2O) = \frac{27}{18} = 1.5 \text{ mol}$<br><br>සීමාකාරී ප්‍රතික්‍රියකය (Limiting Reagent) සෙවීම:<br>$0.6 \text{ mol}$ $FeCl_3$ සම්පූර්ණයෙන් ප්‍රතික්‍රියා කිරීමට $1.8 \text{ mol}$ $NH_3$ සහ $1.8 \text{ mol}$ $H_2O$ අවශ්‍ය වේ. නමුත් පද්ධතියේ ඇත්තේ $1.5 \text{ mol}$ $H_2O$ පමණි. එමනිසා සීමාකාරී ප්‍රතික්‍රියකය $H_2O$ වේ.<br><br>සෑදෙන $Fe(OH)_3$ මවුල ගණන = $H_2O$ මවුල ගණන $/ 3 = \frac{1.5}{3} = 0.5 \text{ mol}$.<br><br>$Fe(OH)_3$ හි මවුලික ස්කන්ධය = $56 + 3 \times (16+1) = 107 \text{ g mol}^{-1}$.<br>ලැබෙන ස්කන්ධය = $0.5 \text{ mol} \times 107 \text{ g mol}^{-1} = 53.5 \text{ g}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
