INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4a24cafa-38b4-42d6-aa08-1a15b1889df4', 'f586e187-369f-5107-a9e1-8445f859c9bd', 'වක්‍රයට අයත් ක්ෂේත්‍රඵලය වෙනස් නොවේ. | උපරිම ලක්ෂ්‍යයෙහි පිහිටීම වෙනස් නොවේ.', 'වක්‍රයට අයත් ක්ෂේත්‍රඵලය වෙනස් නොවේ. | උපරිම ලක්ෂ්‍යයෙහි පිහිටීම වෙනස් නොවේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3137de7f-a4fd-572e-8760-0adb9b99ae10', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 25, '<p>උෂ්ණත්වය $298 \text{ K}$ දී ක්‍රියාත්මක වෙමින් පවතින පහත දී ඇති විද්‍යුත් රසායනික කෝෂය සලකන්න.<br>$Zn(s) | Zn^{2+}(aq, 1.0 \text{ mol dm}^{-3}) || Fe^{2+}(aq, 1.0 \text{ mol dm}^{-3}), Fe^{3+}(aq, 1.0 \text{ mol dm}^{-3}) | Pt(s)$<br><br>පහත සඳහන් කුමක් මගින් නිවැරදි සම්පූර්ණ කෝෂ ප්‍රතික්‍රියාව සහ $E_{cell}^{\circ}$ දක්වයිද?<br>$E^{\circ}_{Zn^{2+}(aq)/Zn(s)} = -0.76 \text{ V}$<br>$E^{\circ}_{Fe^{3+}(aq)/Fe^{2+}(aq)} = +0.77 \text{ V}$</p>', '<p>උෂ්ණත්වය $298 \text{ K}$ දී ක්‍රියාත්මක වෙමින් පවතින පහත දී ඇති විද්‍යුත් රසායනික කෝෂය සලකන්න.<br>$Zn(s) | Zn^{2+}(aq, 1.0 \text{ mol dm}^{-3}) || Fe^{2+}(aq, 1.0 \text{ mol dm}^{-3}), Fe^{3+}(aq, 1.0 \text{ mol dm}^{-3}) | Pt(s)$<br><br>පහත සඳහන් කුමක් මගින් නිවැරදි සම්පූර්ණ කෝෂ ප්‍රතික්‍රියාව සහ $E_{cell}^{\circ}$ දක්වයිද?<br>$E^{\circ}_{Zn^{2+}(aq)/Zn(s)} = -0.76 \text{ V}$<br>$E^{\circ}_{Fe^{3+}(aq)/Fe^{2+}(aq)} = +0.77 \text{ V}$</p>', NULL, 'සම්මත කෝෂ නිරූපණයට අනුව වම්පසින් ඇනෝඩයත් (ඔක්සිකරණය), දකුණුපසින් කැතෝඩයත් (ඔක්සිහරණය) දැක්වේ.<br>ඇනෝඩ ප්‍රතික්‍රියාව: $Zn(s) \rightarrow Zn^{2+}(aq) + 2e^-$<br>කැතෝඩ ප්‍රතික්‍රියාව: $Fe^{3+}(aq) + e^- \rightarrow Fe^{2+}(aq)$<br>සමස්ත ප්‍රතික්‍රියාව (ඉලෙක්ට්‍රෝන තුලිත කිරීමට කැතෝඩ ප්‍රතික්‍රියාව 2 න් ගුණ කර එකතු කිරීමෙන්):<br>$Zn(s) + 2Fe^{3+}(aq) \rightarrow Zn^{2+}(aq) + 2Fe^{2+}(aq)$<br><br>සම්මත කෝෂ විභවය: $E^{\circ}_{cell} = E^{\circ}_{cathode} - E^{\circ}_{anode} = (+0.77 \text{ V}) - (-0.76 \text{ V}) = +1.53 \text{ V}$.', 'සම්මත කෝෂ නිරූපණයට අනුව වම්පසින් ඇනෝඩයත් (ඔක්සිකරණය), දකුණුපසින් කැතෝඩයත් (ඔක්සිහරණය) දැක්වේ.<br>ඇනෝඩ ප්‍රතික්‍රියාව: $Zn(s) \rightarrow Zn^{2+}(aq) + 2e^-$<br>කැතෝඩ ප්‍රතික්‍රියාව: $Fe^{3+}(aq) + e^- \rightarrow Fe^{2+}(aq)$<br>සමස්ත ප්‍රතික්‍රියාව (ඉලෙක්ට්‍රෝන තුලිත කිරීමට කැතෝඩ ප්‍රතික්‍රියාව 2 න් ගුණ කර එකතු කිරීමෙන්):<br>$Zn(s) + 2Fe^{3+}(aq) \rightarrow Zn^{2+}(aq) + 2Fe^{2+}(aq)$<br><br>සම්මත කෝෂ විභවය: $E^{\circ}_{cell} = E^{\circ}_{cathode} - E^{\circ}_{anode} = (+0.77 \text{ V}) - (-0.76 \text{ V}) = +1.53 \text{ V}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1f20fde3-9444-4f0d-811c-c7dcdc5ef775', '3137de7f-a4fd-572e-8760-0adb9b99ae10', 'කෝෂ ප්‍රතික්‍රියාව: $Zn(s) + 2Fe^{3+}(aq) \rightarrow 2Fe^{2+}(aq) + Zn^{2+}(aq)$ | $E_{cell}^{\circ} = 1.53 \text{ V}$', 'කෝෂ ප්‍රතික්‍රියාව: $Zn(s) + 2Fe^{3+}(aq) \rightarrow 2Fe^{2+}(aq) + Zn^{2+}(aq)$ | $E_{cell}^{\circ} = 1.53 \text{ V}$', NULL, 'sanitized', 'v1', 0, 1);
