INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a4ba1f13-4d93-41b9-be2f-aac348bb4bf4', '3137de7f-a4fd-572e-8760-0adb9b99ae10', 'කෝෂ ප්‍රතික්‍රියාව: $Zn(s) + 2Fe^{3+}(aq) \rightarrow 2Fe^{2+}(aq) + Zn^{2+}(aq)$ | $E_{cell}^{\circ} = 0.01 \text{ V}$', 'කෝෂ ප්‍රතික්‍රියාව: $Zn(s) + 2Fe^{3+}(aq) \rightarrow 2Fe^{2+}(aq) + Zn^{2+}(aq)$ | $E_{cell}^{\circ} = 0.01 \text{ V}$', NULL, 'sanitized', 'v1', 2, 0);
