INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c1edbdea-07c5-4806-904a-ca5ce6ac95ee', '91a4acf5-3b69-5bc7-a76c-97130ad1fd51', '(d) සහ (a) පමණක් නිවැරදියි', '(d) සහ (a) පමණක් නිවැරදියි', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5c40a79b-2892-4b22-8a24-9cf092a294f2', '91a4acf5-3b69-5bc7-a76c-97130ad1fd51', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3580dad4-6c11-597a-af8a-2b8dc658aba2', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 35, '<p>කාබන් ඩයොක්සයිඩ් $(CO_2)$ හි කලාප රූපසටහන පහත දැක්වේ.<br><br><br>$25^{\\circ}C$ හා 1 atm පීඩනයකදී ඝන $CO_2$ (වියළි - අයිස්) නියැදියක් බීකරයක තැබූ විට ද්‍රව $CO_2$ නොසෑදෙන බව නිරීක්ෂණය කළ හැක. ඉහත රූපසටහන අනුව පහත සඳහන් කුමන ප්‍රකාශනය/ප්‍රකාශන මෙම නිරීක්ෂණය පැහැදිලි කරයි ද?<br><br>(a) ත්‍රික - ලක්ෂ්‍යයෙහි උෂ්ණත්වය අවධි උෂ්ණත්වයට වඩා අඩුය.<br>(b) අවධි ලක්ෂ්‍යයෙහි උෂ්ණත්වය $25^{\\circ}C$ ට වඩා වැඩි ය.<br>(c) ත්‍රික-ලක්ෂ්‍යයෙහි පීඩනය 1 atm වලට වඩා වැඩි ය.<br>(d) පීඩනය 1 atm වලදී ඝන $CO_2$ වායු කලාපය සමග පමණක් සමතුලිතව පවතී.</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('861cbef0-c64e-498b-b318-72446f179b68', '3580dad4-6c11-597a-af8a-2b8dc658aba2', '(a) සහ (b) පමණක් නිවැරදියි', '(a) සහ (b) පමණක් නිවැරදියි', NULL, 'sanitized', 'v1', 0, 1);
