INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e7009a46-a88b-4bfe-970f-d4e8a6879c13', '65ffd24a-e218-5553-90c9-827acd65504f', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', 'වෙනත් ප්‍රතිචාර සංඛ්‍යාවක් හෝ සංයෝජනයක් හෝ නිවැරදියි', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f64d57ef-95f9-551e-ad71-d16aba5fc2f0', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 41, '<p>**පළමු ප්‍රකාශය:** 1 වන කාණ්ඩයේ මූල ද්‍රව්‍ය (Li - Cs) වල ලෝහක බන්ධන, 2 වන කාණ්ඩයේ මූලද්‍රව්‍ය (Be - Ba) වල ලෝහක බන්ධන වලට වඩා දුර්වල වේ.<br><br>**දෙවන ප්‍රකාශය:** ලෝහක බන්ධන වලට, 1 වන කාණ්ඩයේ මූල ද්‍රව්‍ය වල එක් සංයුජ ඉලෙක්ට්‍රෝනයක් පමණක් සම්බන්ධ වුවද 2 වන කාණ්ඩයේ මූලද්‍රව්‍යවල ඉලෙක්ට්‍රෝන දෙකක් සම්බන්ධ වේ.</p>', '<p>**පළමු ප්‍රකාශය:** 1 වන කාණ්ඩයේ මූල ද්‍රව්‍ය (Li - Cs) වල ලෝහක බන්ධන, 2 වන කාණ්ඩයේ මූලද්‍රව්‍ය (Be - Ba) වල ලෝහක බන්ධන වලට වඩා දුර්වල වේ.<br><br>**දෙවන ප්‍රකාශය:** ලෝහක බන්ධන වලට, 1 වන කාණ්ඩයේ මූල ද්‍රව්‍ය වල එක් සංයුජ ඉලෙක්ට්‍රෝනයක් පමණක් සම්බන්ධ වුවද 2 වන කාණ්ඩයේ මූලද්‍රව්‍යවල ඉලෙක්ට්‍රෝන දෙකක් සම්බන්ධ වේ.</p>', NULL, 'පළමු ප්‍රකාශය සත්‍ය වේ. 1 වන කාණ්ඩයේ මූලද්‍රව්‍යවලට වඩා 2 වන කාණ්ඩයේ මූලද්‍රව්‍යවල ලෝහක බන්ධන ශක්තිමත්ය.<br>දෙවන ප්‍රකාශයද සත්‍ය වේ. ලෝහක බන්ධනයක ප්‍රබලතාව රඳා පවතින්නේ ලෝහක දැලිසට මුදාහරින සංයුජ ඉලෙක්ට්‍රෝන ගණන සහ කැටායනයේ ප්‍රමාණය මතය. 1 කාණ්ඩය එක් ඉලෙක්ට්‍රෝනයක් ද 2 කාණ්ඩය ඉලෙක්ට්‍රෝන දෙකක් ද මුදා හරින බැවින් 2 කාණ්ඩයේ ලෝහක බන්ධන ප්‍රබල වේ. එබැවින් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ. 1 වන කාණ්ඩයේ මූලද්‍රව්‍යවලට වඩා 2 වන කාණ්ඩයේ මූලද්‍රව්‍යවල ලෝහක බන්ධන ශක්තිමත්ය.<br>දෙවන ප්‍රකාශයද සත්‍ය වේ. ලෝහක බන්ධනයක ප්‍රබලතාව රඳා පවතින්නේ ලෝහක දැලිසට මුදාහරින සංයුජ ඉලෙක්ට්‍රෝන ගණන සහ කැටායනයේ ප්‍රමාණය මතය. 1 කාණ්ඩය එක් ඉලෙක්ට්‍රෝනයක් ද 2 කාණ්ඩය ඉලෙක්ට්‍රෝන දෙකක් ද මුදා හරින බැවින් 2 කාණ්ඩයේ ලෝහක බන්ධන ප්‍රබල වේ. එබැවින් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f019ab92-2a0f-4fe9-b02d-c7de05bf40c4', 'f64d57ef-95f9-551e-ad71-d16aba5fc2f0', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b91aeec-3e0e-4a82-b87d-a7d9dc4e7baf', 'f64d57ef-95f9-551e-ad71-d16aba5fc2f0', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4090735b-0cb2-4c52-9dff-246648258ade', 'f64d57ef-95f9-551e-ad71-d16aba5fc2f0', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('15cc0fa9-94c9-4b17-b50a-7a75243c6bf9', 'f64d57ef-95f9-551e-ad71-d16aba5fc2f0', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6ddbddc9-af36-46ab-8160-70d0cb416659', 'f64d57ef-95f9-551e-ad71-d16aba5fc2f0', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7c1d433c-01cf-5c50-85b4-c1bd806afeb5', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 42, '<p>**පළමු ප්‍රකාශය:** පහත දැක්වෙන අණුක ව්‍යුහයන් එකිනෙකෙහි පාරත්‍රිමාන සමාවයවික වේ.<br><br><br><br>**දෙවන ප්‍රකාශය:** එකිනෙකෙහි දර්පණ ප්‍රතිබිම්බ නොවන ත්‍රිමාන සමාවයවික, පාරත්‍රිමාන සමාවයවික වේ.</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f8b873ec-e4b5-4220-8dfd-6c03e2cca771', '7c1d433c-01cf-5c50-85b4-c1bd806afeb5', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a0c091d8-c668-432b-898a-ec25b50ec959', '7c1d433c-01cf-5c50-85b4-c1bd806afeb5', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', NULL, 'sanitized', 'v1', 1, 0);
