INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('380d6d9c-b4a6-5767-98d3-314d0c60ff02', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 47, '<p>**පළමු ප්‍රකාශය:** $N_2(g)$ වලට ඔක්සිකාරකයක් ලෙස හැසිරිය නොහැක.<br><br>**දෙවන ප්‍රකාශය:** රත් කළ විට $N_2(g)$, Li සමග ප්‍රතික්‍රියා කර ලැබෙන අයනික ඵලය ජලය සමග $NH_3(g)$ පිට කරමින් ප්‍රතික්‍රියා කරයි.</p>', '<p>**පළමු ප්‍රකාශය:** $N_2(g)$ වලට ඔක්සිකාරකයක් ලෙස හැසිරිය නොහැක.<br><br>**දෙවන ප්‍රකාශය:** රත් කළ විට $N_2(g)$, Li සමග ප්‍රතික්‍රියා කර ලැබෙන අයනික ඵලය ජලය සමග $NH_3(g)$ පිට කරමින් ප්‍රතික්‍රියා කරයි.</p>', NULL, 'පළමු ප්‍රකාශය අසත්‍ය වේ. $N_2$ සක්‍රිය ලෝහ සමග ප්‍රතික්‍රියා කිරීමේදී (උදා: 6Li + $N_2 \rightarrow 2Li_3N$) නයිට්‍රජන් 0 සිට -3 දක්වා ඔක්සිහරණය වන බැවින් එය ඔක්සිකාරකයක් ලෙස හැසිරේ.<br>දෙවන ප්‍රකාශය සත්‍ය වේ. සෑදෙන ලිතියම් නයිට්‍රයිඩ් ($Li_3N$) ජලය සමග ප්‍රතික්‍රියා කර ඇමෝනියා වායුව පිට කරයි ($Li_3N + 3H_2O \rightarrow 3LiOH + NH_3$).', 'පළමු ප්‍රකාශය අසත්‍ය වේ. $N_2$ සක්‍රිය ලෝහ සමග ප්‍රතික්‍රියා කිරීමේදී (උදා: 6Li + $N_2 \rightarrow 2Li_3N$) නයිට්‍රජන් 0 සිට -3 දක්වා ඔක්සිහරණය වන බැවින් එය ඔක්සිකාරකයක් ලෙස හැසිරේ.<br>දෙවන ප්‍රකාශය සත්‍ය වේ. සෑදෙන ලිතියම් නයිට්‍රයිඩ් ($Li_3N$) ජලය සමග ප්‍රතික්‍රියා කර ඇමෝනියා වායුව පිට කරයි ($Li_3N + 3H_2O \rightarrow 3LiOH + NH_3$).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('212cbab0-af05-4051-9e6b-73d5bc84b6d2', '380d6d9c-b4a6-5767-98d3-314d0c60ff02', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 0, 1);
