INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('684bfe3e-7be1-4ec2-8e06-abc22c1387cf', '2a0eb6a1-13b2-5f49-9c4e-7dc19bc33c28', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8df48618-016d-5d34-a658-c2ee4a7f255a', '0ea6809c-ab0d-5379-a3c5-a848c7acdfbe', 50, '<p>**පළමු ප්‍රකාශය:** තාපස්ථාපන බහු අවයවක රත් කිරීම මගින් මෘදු කළ නොහැක.<br><br>**දෙවන ප්‍රකාශය:** තාපස්ථාපන බහු අවයවකවලට ත්‍රිමාන දැලිසක් ලෙස සැකසුණු අණුක ව්‍යුහයක් ඇත.</p>', '<p>**පළමු ප්‍රකාශය:** තාපස්ථාපන බහු අවයවක රත් කිරීම මගින් මෘදු කළ නොහැක.<br><br>**දෙවන ප්‍රකාශය:** තාපස්ථාපන බහු අවයවකවලට ත්‍රිමාන දැලිසක් ලෙස සැකසුණු අණුක ව්‍යුහයක් ඇත.</p>', NULL, 'පළමු ප්‍රකාශය සත්‍ය වේ. තාපස්ථාපන (Thermosetting) බහු අවයවක රත් කිරීමේදී දිය වී හෝ මෘදු වී නොයන අතර ඒවා දැවී යයි.<br>දෙවන ප්‍රකාශය ද සත්‍ය වේ. ඒවායේ බහු අවයවක දාම අතර ප්‍රබල සහසංයුජ හරස් බන්ධන (cross-links) පවතින බැවින් ශක්තිමත් ත්‍රිමාන ජාලයක් සෑදී ඇත. මෙම දැඩි ව්‍යුහය නිසාම ඒවා රත් කළ විට මෘදු නොවේ. එබැවින් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය මැනවින් පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ. තාපස්ථාපන (Thermosetting) බහු අවයවක රත් කිරීමේදී දිය වී හෝ මෘදු වී නොයන අතර ඒවා දැවී යයි.<br>දෙවන ප්‍රකාශය ද සත්‍ය වේ. ඒවායේ බහු අවයවක දාම අතර ප්‍රබල සහසංයුජ හරස් බන්ධන (cross-links) පවතින බැවින් ශක්තිමත් ත්‍රිමාන ජාලයක් සෑදී ඇත. මෙම දැඩි ව්‍යුහය නිසාම ඒවා රත් කළ විට මෘදු නොවේ. එබැවින් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය මැනවින් පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('802460c2-673a-4f1c-91c3-eee6cf5d5bad', '8df48618-016d-5d34-a658-c2ee4a7f255a', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4c60b9a9-b2a2-4499-9a1e-62904ded56a9', '8df48618-016d-5d34-a658-c2ee4a7f255a', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ. නමුත් දෙවන ප්‍රකාශය මගින් පළමු ප්‍රකාශය නිවැරදිව පැහැදිලි නොකරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('756910ff-da4d-440c-be83-dbbe19c59cd2', '8df48618-016d-5d34-a658-c2ee4a7f255a', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'පළමු ප්‍රකාශය සත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9c9e149d-03ed-49b8-9d08-1f37eab62f17', '8df48618-016d-5d34-a658-c2ee4a7f255a', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය සත්‍ය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e6f409eb-b9f8-4b48-97bb-aec071d3bc1f', '8df48618-016d-5d34-a658-c2ee4a7f255a', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', 'පළමු ප්‍රකාශය අසත්‍ය වේ, දෙවන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('12f6f396-c7b4-5197-9160-3fb5fe0da0c6', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 1, '<p>ආහාර රත් කිරීම සඳහා භාවිත කරන ක්ෂුද්‍ර තරංග උදුන (Microwave oven) විසිරණවල තරංග ආයාමය $1.1 \text{ cm}$ වේ. මෙම ක්ෂුද්‍ර තරංග විසිරණවල එක් ෆෝටෝනයක ශක්තිය වනුයේ,<br>(සටහන: ප්ලෑන්ක්ගේ නියතය, $h = 6.6 \times 10^{-34} \text{ J s}$ සහ ආලෝකයේ ප්‍රවේගය $c = 3 \times 10^8 \text{ m s}^{-1}$ ලෙස ගණනය කිරීමට යොදා ගන්න.)</p>', '<p>ආහාර රත් කිරීම සඳහා භාවිත කරන ක්ෂුද්‍ර තරංග උදුන (Microwave oven) විසිරණවල තරංග ආයාමය $1.1 \text{ cm}$ වේ. මෙම ක්ෂුද්‍ර තරංග විසිරණවල එක් ෆෝටෝනයක ශක්තිය වනුයේ,<br>(සටහන: ප්ලෑන්ක්ගේ නියතය, $h = 6.6 \times 10^{-34} \text{ J s}$ සහ ආලෝකයේ ප්‍රවේගය $c = 3 \times 10^8 \text{ m s}^{-1}$ ලෙස ගණනය කිරීමට යොදා ගන්න.)</p>', NULL, 'ෆෝටෝනයක ශක්තිය ගණනය කිරීම සඳහා $E = \frac{hc}{\lambda}$ සමීකරණය භාවිතා කරයි.<br>මෙහි $\lambda = 1.1 \text{ cm} = 1.1 \times 10^{-2} \text{ m}$ වේ.<br><br>$E = \frac{6.6 \times 10^{-34} \text{ J s} \times 3 \times 10^8 \text{ m s}^{-1}}{1.1 \times 10^{-2} \text{ m}}$<br>$E = \frac{19.8 \times 10^{-26}}{1.1 \times 10^{-2}} \text{ J}$<br>$E = 18 \times 10^{-24} \text{ J} = 1.8 \times 10^{-23} \text{ J}$.', 'ෆෝටෝනයක ශක්තිය ගණනය කිරීම සඳහා $E = \frac{hc}{\lambda}$ සමීකරණය භාවිතා කරයි.<br>මෙහි $\lambda = 1.1 \text{ cm} = 1.1 \times 10^{-2} \text{ m}$ වේ.<br><br>$E = \frac{6.6 \times 10^{-34} \text{ J s} \times 3 \times 10^8 \text{ m s}^{-1}}{1.1 \times 10^{-2} \text{ m}}$<br>$E = \frac{19.8 \times 10^{-26}}{1.1 \times 10^{-2}} \text{ J}$<br>$E = 18 \times 10^{-24} \text{ J} = 1.8 \times 10^{-23} \text{ J}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
