INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('92188a17-af0b-4528-8798-23365ea8dd9e', '12f6f396-c7b4-5197-9160-3fb5fe0da0c6', '$6.0 \times 10^{-20} \text{ J}$', '$6.0 \times 10^{-20} \text{ J}$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e036b880-5bea-5b85-9809-ac7f1f08f6d4', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 2, '<p>පහත දැක්වෙන ලැයිස්තුවෙන්, හයිඩ්‍රජන් වර්ණාවලියේ ඉහළම සංඛ්‍යාතය සහ පහළම සංඛ්‍යාතය ඇති විමෝචන රේඛා පිළිවෙළින් හඳුනාගන්න.<br>විමෝචන රේඛා ලැයිස්තුව ($n$ = ප්‍රධාන ක්වොන්ටම් අංකය)<br>$n=3 \rightarrow n=1, n=2 \rightarrow n=1, n=3 \rightarrow n=2, n=4 \rightarrow n=2, n=4 \rightarrow n=3$</p>', '<p>පහත දැක්වෙන ලැයිස්තුවෙන්, හයිඩ්‍රජන් වර්ණාවලියේ ඉහළම සංඛ්‍යාතය සහ පහළම සංඛ්‍යාතය ඇති විමෝචන රේඛා පිළිවෙළින් හඳුනාගන්න.<br>විමෝචන රේඛා ලැයිස්තුව ($n$ = ප්‍රධාන ක්වොන්ටම් අංකය)<br>$n=3 \rightarrow n=1, n=2 \rightarrow n=1, n=3 \rightarrow n=2, n=4 \rightarrow n=2, n=4 \rightarrow n=3$</p>', NULL, 'ෆෝටෝනයක ශක්තිය එහි සංඛ්‍යාතයට අනුලෝමව සමානුපාතික වේ ($E = h\nu$).<br>හයිඩ්‍රජන් පරමාණුවක ශක්ති මට්ටම් අතර වෙනස $\Delta E \propto (\frac{1}{n_1^2} - \frac{1}{n_2^2})$ මගින් දැක්වේ.<br>ඉහළම ශක්ති වෙනසක් (ඉහළම සංඛ්‍යාතය) ඇතිවන්නේ ලයිමන් ශ්‍රේණියට අයත් ($n=1$ වෙතට සිදුවන) විශාලතම පරතරය ඇති සංක්‍රමණය වන $n=3 \rightarrow n=1$ සඳහාය.<br>පහළම ශක්ති වෙනසක් (පහළම සංඛ්‍යාතය) ඇතිවන්නේ ඉහළම $n$ අගයන් අතර සිදුවන සංක්‍රමණය වන $n=4 \rightarrow n=3$ (පැෂන් ශ්‍රේණිය) සඳහාය.', 'ෆෝටෝනයක ශක්තිය එහි සංඛ්‍යාතයට අනුලෝමව සමානුපාතික වේ ($E = h\nu$).<br>හයිඩ්‍රජන් පරමාණුවක ශක්ති මට්ටම් අතර වෙනස $\Delta E \propto (\frac{1}{n_1^2} - \frac{1}{n_2^2})$ මගින් දැක්වේ.<br>ඉහළම ශක්ති වෙනසක් (ඉහළම සංඛ්‍යාතය) ඇතිවන්නේ ලයිමන් ශ්‍රේණියට අයත් ($n=1$ වෙතට සිදුවන) විශාලතම පරතරය ඇති සංක්‍රමණය වන $n=3 \rightarrow n=1$ සඳහාය.<br>පහළම ශක්ති වෙනසක් (පහළම සංඛ්‍යාතය) ඇතිවන්නේ ඉහළම $n$ අගයන් අතර සිදුවන සංක්‍රමණය වන $n=4 \rightarrow n=3$ (පැෂන් ශ්‍රේණිය) සඳහාය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
