INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2c8e2f6c-f445-5850-934a-456e62a256c6', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 9, '<p>මීතේන්හි මුක්ත ඛණ්ඩක ක්ලෝරිනීකරණ ප්‍රතික්‍රියාවේ දාම ප්‍රචාරණ පියවරක් නිරූපණය වනුයේ පහත දැක්වෙන කුමක් මගින්ද?</p>', '<p>මීතේන්හි මුක්ත ඛණ්ඩක ක්ලෝරිනීකරණ ප්‍රතික්‍රියාවේ දාම ප්‍රචාරණ පියවරක් නිරූපණය වනුයේ පහත දැක්වෙන කුමක් මගින්ද?</p>', NULL, 'මුක්ත ඛණ්ඩක ප්‍රතික්‍රියාවක දාම ප්‍රචාරණ (Chain propagation) පියවරකදී එක් මුක්ත ඛණ්ඩකයක් ප්‍රතික්‍රියා කර අලුතින් තවත් මුක්ත ඛණ්ඩකයක් නිපදවිය යුතුය.<br>(2) ප්‍රතික්‍රියාවේදී ක්ලෝරීන් මුක්ත ඛණ්ඩකය ($\dot{C}l$), $CH_2Cl_2$ සමග ප්‍රතික්‍රියා කර $\dot{C}HCl_2$ නැමැති නව මුක්ත ඛණ්ඩකයක් සහ $HCl$ නිපදවයි. එබැවින් මෙය ප්‍රචාරණ පියවරකි.<br>(3) සහ (5) ප්‍රතික්‍රියා වලදී මුක්ත ඛණ්ඩක දෙකක් එකතු වී ස්ථායී අණුවක් සාදන බැවින් ඒවා දාම අවසන් වීමේ (Termination) පියවර වේ.', 'මුක්ත ඛණ්ඩක ප්‍රතික්‍රියාවක දාම ප්‍රචාරණ (Chain propagation) පියවරකදී එක් මුක්ත ඛණ්ඩකයක් ප්‍රතික්‍රියා කර අලුතින් තවත් මුක්ත ඛණ්ඩකයක් නිපදවිය යුතුය.<br>(2) ප්‍රතික්‍රියාවේදී ක්ලෝරීන් මුක්ත ඛණ්ඩකය ($\dot{C}l$), $CH_2Cl_2$ සමග ප්‍රතික්‍රියා කර $\dot{C}HCl_2$ නැමැති නව මුක්ත ඛණ්ඩකයක් සහ $HCl$ නිපදවයි. එබැවින් මෙය ප්‍රචාරණ පියවරකි.<br>(3) සහ (5) ප්‍රතික්‍රියා වලදී මුක්ත ඛණ්ඩක දෙකක් එකතු වී ස්ථායී අණුවක් සාදන බැවින් ඒවා දාම අවසන් වීමේ (Termination) පියවර වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e7408ea9-8606-4a29-9986-abf9b060937d', '2c8e2f6c-f445-5850-934a-456e62a256c6', '$CH_3Cl + \dot{C}l \rightarrow CH_2Cl_2 + \dot{H}$', '$CH_3Cl + \dot{C}l \rightarrow CH_2Cl_2 + \dot{H}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7d9530b9-a529-43b9-97f3-4542c5a21c90', '2c8e2f6c-f445-5850-934a-456e62a256c6', '$CH_2Cl_2 + \dot{C}l \rightarrow \dot{C}HCl_2 + HCl$', '$CH_2Cl_2 + \dot{C}l \rightarrow \dot{C}HCl_2 + HCl$', NULL, 'sanitized', 'v1', 1, 0);
