INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('45e9e04c-55f0-4b43-beda-7223c63c6326', '68cd8526-9ba9-55b7-8235-829ce681315a', 'කිසිම යන්ත්‍රණයක් ශීඝ්‍රතා නියමය සමග අනුගත නොවේ.', 'කිසිම යන්ත්‍රණයක් ශීඝ්‍රතා නියමය සමග අනුගත නොවේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc12e098-63bb-4364-983e-0db697413771', '68cd8526-9ba9-55b7-8235-829ce681315a', 'සියලුම යන්ත්‍රණ ශීඝ්‍රතා නියමය සමග අනුගත වේ.', 'සියලුම යන්ත්‍රණ ශීඝ්‍රතා නියමය සමග අනුගත වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f5aa1729-adaa-59d5-928e-b8ee7353529e', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 11, '<p>පහත දී ඇති ලවණවල තාප වියෝජනය පිළිබඳ වැරදි ප්‍රකාශය හඳුනාගන්න.<br>$NH_4Cl$, $NH_4NO_2$, $NH_4NO_3$, $(NH_4)_2CO_3$, $(NH_4)_2Cr_2O_7$</p>', '<p>පහත දී ඇති ලවණවල තාප වියෝජනය පිළිබඳ වැරදි ප්‍රකාශය හඳුනාගන්න.<br>$NH_4Cl$, $NH_4NO_2$, $NH_4NO_3$, $(NH_4)_2CO_3$, $(NH_4)_2Cr_2O_7$</p>', NULL, 'මෙම ලවණවල තාප වියෝජන ප්‍රතික්‍රියා පහත පරිදි වේ:<br>$NH_4Cl \rightarrow NH_3 + HCl$<br>$NH_4NO_2 \rightarrow N_2 + 2H_2O$<br>$NH_4NO_3 \rightarrow N_2O + 2H_2O$<br>$(NH_4)_2CO_3 \rightarrow 2NH_3 + CO_2 + H_2O$<br>$(NH_4)_2Cr_2O_7 \rightarrow N_2 + Cr_2O_3 + 4H_2O$<br><br>මෙහි $H_2O$ ලබා දෙන ලවණ 4 ක් ඇත ($NH_4NO_2$, $NH_4NO_3$, $(NH_4)_2CO_3$, $(NH_4)_2Cr_2O_7$). නමුත් 5 වන ප්‍රකාශයේ සඳහන් වන්නේ ලවණ දෙකක් පමණක් $H_2O$ ලබා දෙන බවයි. එබැවින් 5 වැරදි ප්‍රකාශය වේ.', 'මෙම ලවණවල තාප වියෝජන ප්‍රතික්‍රියා පහත පරිදි වේ:<br>$NH_4Cl \rightarrow NH_3 + HCl$<br>$NH_4NO_2 \rightarrow N_2 + 2H_2O$<br>$NH_4NO_3 \rightarrow N_2O + 2H_2O$<br>$(NH_4)_2CO_3 \rightarrow 2NH_3 + CO_2 + H_2O$<br>$(NH_4)_2Cr_2O_7 \rightarrow N_2 + Cr_2O_3 + 4H_2O$<br><br>මෙහි $H_2O$ ලබා දෙන ලවණ 4 ක් ඇත ($NH_4NO_2$, $NH_4NO_3$, $(NH_4)_2CO_3$, $(NH_4)_2Cr_2O_7$). නමුත් 5 වන ප්‍රකාශයේ සඳහන් වන්නේ ලවණ දෙකක් පමණක් $H_2O$ ලබා දෙන බවයි. එබැවින් 5 වැරදි ප්‍රකාශය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a01d0732-f294-472b-98ec-ed8347dea044', 'f5aa1729-adaa-59d5-928e-b8ee7353529e', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස $NH_3$ ලබා දේ.', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස $NH_3$ ලබා දේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a589214d-ab20-4373-ae4f-8c90494ab87c', 'f5aa1729-adaa-59d5-928e-b8ee7353529e', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස $N_2$ ලබා දේ.', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස $N_2$ ලබා දේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('87c7a50c-5910-407f-a28c-4e5392eb6b77', 'f5aa1729-adaa-59d5-928e-b8ee7353529e', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස ආම්ලික වායුවක් ලබා දේ.', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස ආම්ලික වායුවක් ලබා දේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('da695cfb-649a-40b4-99fb-6ba0e87fc429', 'f5aa1729-adaa-59d5-928e-b8ee7353529e', 'එක් ලවණයක් පමණක් කාමර උෂ්ණත්වයේදී ඝනයක් ලෙස පවතින ඵලයක් ලබා දේ.', 'එක් ලවණයක් පමණක් කාමර උෂ්ණත්වයේදී ඝනයක් ලෙස පවතින ඵලයක් ලබා දේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1fbffc8a-5ee2-4063-9f6a-2ee25fdd0706', 'f5aa1729-adaa-59d5-928e-b8ee7353529e', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස $H_2O$ ලබා දේ.', 'ලවණ දෙකක් පමණක් ඵලයක් ලෙස $H_2O$ ලබා දේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('16822389-e29b-5998-aac2-374d1754b470', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 12, '<p>දී ඇති අනුමාපන වක්‍රය ඒකභාස්මික දුබල අම්ලයක් NaOH සමග අනුමාපනය කිරීමෙන් ලබාගන්නා ලදි. පහත දී ඇති වගන්ති අතුරෙන් වැරදි වගන්තිය හඳුනාගන්න.</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42fc93c2-fb16-4732-9714-b86fa1f69929', '16822389-e29b-5998-aac2-374d1754b470', 'A ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයේ pH අගය, දුබල අම්ලයෙහි $pK_a$ අගයට සමාන වේ.', 'A ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයේ pH අගය, දුබල අම්ලයෙහි $pK_a$ අගයට සමාන වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('91e399e0-818b-4c93-bfd3-c2aa707ae8fc', '16822389-e29b-5998-aac2-374d1754b470', 'A ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයෙහි ඉතිරි වී ඇති දුබල අම්ලයේ සහ එහි සංයුග්මක භස්මයෙහි සාන්ද්‍රණ සමාන වේ.', 'A ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයෙහි ඉතිරි වී ඇති දුබල අම්ලයේ සහ එහි සංයුග්මක භස්මයෙහි සාන්ද්‍රණ සමාන වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e92acd3-7d59-4a89-84e2-ed422f9668a8', '16822389-e29b-5998-aac2-374d1754b470', 'B ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයෙහි $H^+$ හා $OH^-$ සාන්ද්‍රණයන් සමාන වේ.', 'B ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයෙහි $H^+$ හා $OH^-$ සාන්ද්‍රණයන් සමාන වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a1a6ce9d-bb31-4cde-ae0d-ddbeb7b4be62', '16822389-e29b-5998-aac2-374d1754b470', 'මෙම අනුමාපනය සඳහා දර්ශකයක් ලෙස ෆිනෝල්ප්තලීන් භාවිත කළ හැක.', 'මෙම අනුමාපනය සඳහා දර්ශකයක් ලෙස ෆිනෝල්ප්තලීන් භාවිත කළ හැක.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('28b78085-b52d-47d6-a5d6-401db79b2ab1', '16822389-e29b-5998-aac2-374d1754b470', 'C ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයෙහි pH අගය, භාවිත කරන ලද NaOH ද්‍රාවණයෙහි pH අගයට වඩා අඩු වේ.', 'C ලක්ෂ්‍යයේදී අනුමාපන මිශ්‍රණයෙහි pH අගය, භාවිත කරන ලද NaOH ද්‍රාවණයෙහි pH අගයට වඩා අඩු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('149beebd-925d-5332-b9ca-17f677c634bb', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 13, '<p>A නම් කාබනික සංයෝගයත් 2,4 - ඩයිනයිට්‍රෝෆෙනිල්හයිඩ්‍රසීන් සමඟ වර්ණවත් අවක්ෂේපයක් ලබා දෙයි. A සංයෝගය, ආම්ලීකෘත පොටෑසියම් ඩයික්‍රෝමේට් සමග ප්‍රතික්‍රියා කළ විට B සංයෝගය සෑදෙන අතර ද්‍රාවණය කොළ පාට වේ.<br>B සංයෝගය 2,4 - ඩයිනයිට්‍රෝෆෙනිල් හයිඩ්‍රසීන් සමග වර්ණවත් අවක්ෂේපයක් ලබා නොදුනි. A හි ව්‍යුහය විය හැක්කේ,</p>', '<p>A නම් කාබනික සංයෝගයත් 2,4 - ඩයිනයිට්‍රෝෆෙනිල්හයිඩ්‍රසීන් සමඟ වර්ණවත් අවක්ෂේපයක් ලබා දෙයි. A සංයෝගය, ආම්ලීකෘත පොටෑසියම් ඩයික්‍රෝමේට් සමග ප්‍රතික්‍රියා කළ විට B සංයෝගය සෑදෙන අතර ද්‍රාවණය කොළ පාට වේ.<br>B සංයෝගය 2,4 - ඩයිනයිට්‍රෝෆෙනිල් හයිඩ්‍රසීන් සමග වර්ණවත් අවක්ෂේපයක් ලබා නොදුනි. A හි ව්‍යුහය විය හැක්කේ,</p>', NULL, 'A සංයෝගය 2,4-DNP සමඟ වර්ණවත් අවක්ෂේපයක් දෙන බැවින් එහි කාබොනයිල් (ඇල්ඩිහයිඩ් හෝ කීටෝන) කාණ්ඩයක් ඇත.<br>එය ඔක්සිකරණය වී B සාදන විට B සංයෝගය 2,4-DNP සමඟ අවක්ෂේපයක් ලබා නොදේ. එනම් B හි කීටෝන හෝ ඇල්ඩිහයිඩ කාණ්ඩයක් නොමැත.<br>A සංයෝගයේ කීටෝන කාණ්ඩයක් තිබුණේ නම්, ඔක්සිකරණයයේදී එය වෙනස් නොවන බැවින් B තුළ ද කීටෝන කාණ්ඩය පවතී (එවිට B ද 2,4-DNP දෙනු ඇත). එබැවින් A හි කීටෝන කාණ්ඩයක් හෝ ද්විතියික මධ්‍යසාර කාණ්ඩයක් (ඔක්සිකරණයෙන් කීටෝන සාදන) තිබිය නොහැක.<br>A යනු ඇල්ඩිහයිඩයක් නම්, එය ඔක්සිකරණය වී B ලෙස කාබොක්සිලික් අම්ලය සාදයි (එය 2,4-DNP සමග ප්‍රතික්‍රියා නොකරයි).<br>මෙම ලක්ෂණවලට ගැළපෙන්නේ ඇල්ඩිහයිඩ කාණ්ඩයක් සහ ප්‍රාථමික මධ්‍යසාර කාණ්ඩයක් පමණක් ඇති 3 වන ව්‍යුහයයි ($HOCH_2CH_2CH_2CH_2CHO$).', 'A සංයෝගය 2,4-DNP සමඟ වර්ණවත් අවක්ෂේපයක් දෙන බැවින් එහි කාබොනයිල් (ඇල්ඩිහයිඩ් හෝ කීටෝන) කාණ්ඩයක් ඇත.<br>එය ඔක්සිකරණය වී B සාදන විට B සංයෝගය 2,4-DNP සමඟ අවක්ෂේපයක් ලබා නොදේ. එනම් B හි කීටෝන හෝ ඇල්ඩිහයිඩ කාණ්ඩයක් නොමැත.<br>A සංයෝගයේ කීටෝන කාණ්ඩයක් තිබුණේ නම්, ඔක්සිකරණයයේදී එය වෙනස් නොවන බැවින් B තුළ ද කීටෝන කාණ්ඩය පවතී (එවිට B ද 2,4-DNP දෙනු ඇත). එබැවින් A හි කීටෝන කාණ්ඩයක් හෝ ද්විතියික මධ්‍යසාර කාණ්ඩයක් (ඔක්සිකරණයෙන් කීටෝන සාදන) තිබිය නොහැක.<br>A යනු ඇල්ඩිහයිඩයක් නම්, එය ඔක්සිකරණය වී B ලෙස කාබොක්සිලික් අම්ලය සාදයි (එය 2,4-DNP සමග ප්‍රතික්‍රියා නොකරයි).<br>මෙම ලක්ෂණවලට ගැළපෙන්නේ ඇල්ඩිහයිඩ කාණ්ඩයක් සහ ප්‍රාථමික මධ්‍යසාර කාණ්ඩයක් පමණක් ඇති 3 වන ව්‍යුහයයි ($HOCH_2CH_2CH_2CH_2CHO$).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
