INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4326d10e-1f21-48e5-bd3d-f9e52fcc976e', '0784b6a5-6adc-5990-aae0-807e4679e42a', 'ඉදිරි ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව අඩුවේ. ආපසු ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව වෙනස් නොවේ.', 'ඉදිරි ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව අඩුවේ. ආපසු ප්‍රතික්‍රියාවේ ශීඝ්‍රතාව වෙනස් නොවේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4d77173c-942b-5701-b41a-669398eb0e10', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 17, '<p>$1.0 \text{ mol dm}^{-3} CH_3COOH(aq)$ $100.0 \text{ cm}^3$ ද, $1.0 \text{ mol dm}^{-3} CH_3COONa(aq)$ $100.0 \text{ cm}^3$ ද මිශ්‍ර කර ද්‍රාවණයක් සාදන ලදී. ලැබුණු ද්‍රාවණයෙහි $25^{\circ}C$ හි දී pH අගය 4.8 ක් විය. මෙම ද්‍රාවණයට $0.10 \text{ mol dm}^{-3} HCl(aq)$ බිංදු කිහිපයක් එකතු කර හොඳින් මිශ්‍ර කළ විට ද pH අගය 4.8 හිම පැවතුණි. ද්‍රාවණයෙහි pH අගය වෙනස්වීම වැළැක්වීම සඳහා පහත කුමන ප්‍රතික්‍රියාව සිදු වී තිබිය හැකිද?</p>', '<p>$1.0 \text{ mol dm}^{-3} CH_3COOH(aq)$ $100.0 \text{ cm}^3$ ද, $1.0 \text{ mol dm}^{-3} CH_3COONa(aq)$ $100.0 \text{ cm}^3$ ද මිශ්‍ර කර ද්‍රාවණයක් සාදන ලදී. ලැබුණු ද්‍රාවණයෙහි $25^{\circ}C$ හි දී pH අගය 4.8 ක් විය. මෙම ද්‍රාවණයට $0.10 \text{ mol dm}^{-3} HCl(aq)$ බිංදු කිහිපයක් එකතු කර හොඳින් මිශ්‍ර කළ විට ද pH අගය 4.8 හිම පැවතුණි. ද්‍රාවණයෙහි pH අගය වෙනස්වීම වැළැක්වීම සඳහා පහත කුමන ප්‍රතික්‍රියාව සිදු වී තිබිය හැකිද?</p>', NULL, 'මෙය ආම්ලික ස්වාරක්ෂක (buffer) ද්‍රාවණයකි. ස්වාරක්ෂක ද්‍රාවණයකට බාහිරින් ප්‍රබල අම්ලයක් (HCl) එකතු කළ විට, ඉන් ලැබෙන $H_3O^+$ අයන, ද්‍රාවණයේ ඇති සංයුග්මක භෂ්මය වන $CH_3COO^-$ අයන සමග ප්‍රතික්‍රියා කර දුර්වල අම්ලය ($CH_3COOH$) සාදයි. මේ හේතුවෙන් ද්‍රාවණයේ නිදහස් $H_3O^+$ සාන්ද්‍රණය සැලකිය යුතු ලෙස ඉහළ නොයන අතර pH අගය බොහෝදුරට නියතව පවතී.', 'මෙය ආම්ලික ස්වාරක්ෂක (buffer) ද්‍රාවණයකි. ස්වාරක්ෂක ද්‍රාවණයකට බාහිරින් ප්‍රබල අම්ලයක් (HCl) එකතු කළ විට, ඉන් ලැබෙන $H_3O^+$ අයන, ද්‍රාවණයේ ඇති සංයුග්මක භෂ්මය වන $CH_3COO^-$ අයන සමග ප්‍රතික්‍රියා කර දුර්වල අම්ලය ($CH_3COOH$) සාදයි. මේ හේතුවෙන් ද්‍රාවණයේ නිදහස් $H_3O^+$ සාන්ද්‍රණය සැලකිය යුතු ලෙස ඉහළ නොයන අතර pH අගය බොහෝදුරට නියතව පවතී.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('97f63114-843c-4423-8db0-3fed11e7a0d3', '4d77173c-942b-5701-b41a-669398eb0e10', '$H_3O^+(aq) + OH^-(aq) \rightarrow 2H_2O(l)$', '$H_3O^+(aq) + OH^-(aq) \rightarrow 2H_2O(l)$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b0dd64c-aea1-48ce-a4b8-27d1716dc394', '4d77173c-942b-5701-b41a-669398eb0e10', '$H_3O^+(aq) + CH_3COO^-(aq) \rightarrow CH_3COOH(aq) + H_2O(l)$', '$H_3O^+(aq) + CH_3COO^-(aq) \rightarrow CH_3COOH(aq) + H_2O(l)$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0b460339-842f-46f8-bd4b-c2b3a25f6016', '4d77173c-942b-5701-b41a-669398eb0e10', '$H_3O^+(aq) + Cl^-(aq) \rightarrow HCl(aq) + H_2O(l)$', '$H_3O^+(aq) + Cl^-(aq) \rightarrow HCl(aq) + H_2O(l)$', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('63e59ff1-aa7c-415a-b6db-3e0005f501ee', '4d77173c-942b-5701-b41a-669398eb0e10', '$H_3O^+(aq) + CH_3COOH(aq) \rightarrow CH_3COOH_2^+(aq) + H_2O(l)$', '$H_3O^+(aq) + CH_3COOH(aq) \rightarrow CH_3COOH_2^+(aq) + H_2O(l)$', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dab467cb-a7fa-4dcd-9e22-f3273b0d4398', '4d77173c-942b-5701-b41a-669398eb0e10', '$H_3O^+(aq) + CH_3COO^-(aq) \rightarrow CH_3COO^-(aq) + H_3O^+(aq)$', '$H_3O^+(aq) + CH_3COO^-(aq) \rightarrow CH_3COO^-(aq) + H_3O^+(aq)$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f9b6140b-a90d-5467-97d9-6b1ac9e7a64e', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 18, '<p>පහත සඳහන් කුමක් මගින් $H_2(g) + Cl_2(g) \rightarrow 2HCl(g)$ ප්‍රතික්‍රියාවෙහි ශක්ති සටහන නිරූපණය වේද?<br>$H-H$, $Cl-Cl$ හා $H-Cl$ හි බන්ධන ශක්තීන් පිළිවෙළින් 430, 240 හා 430 $\text{kJ mol}^{-1}$ වේ.</p>', '<p>පහත සඳහන් කුමක් මගින් $H_2(g) + Cl_2(g) \rightarrow 2HCl(g)$ ප්‍රතික්‍රියාවෙහි ශක්ති සටහන නිරූපණය වේද?<br>$H-H$, $Cl-Cl$ හා $H-Cl$ හි බන්ධන ශක්තීන් පිළිවෙළින් 430, 240 හා 430 $\text{kJ mol}^{-1}$ වේ.</p>', NULL, 'ප්‍රතික්‍රියාවේ එන්තැල්පි වෙනස ගණනය කිරීම:<br>$\Delta H = \Sigma (\text{බිඳෙන බන්ධන වල ශක්තිය}) - \Sigma (\text{සෑදෙන බන්ධන වල ශක්තිය})$<br>බිඳෙන බන්ධන: $1 \times (H-H) + 1 \times (Cl-Cl) = 430 + 240 = 670 \text{ kJ}$<br>සෑදෙන බන්ධන: $2 \times (H-Cl) = 2 \times 430 = 860 \text{ kJ}$<br>$\Delta H = 670 - 860 = -190 \text{ kJ mol}^{-1}$<br><br>$\Delta H$ සෘණ වන බැවින් මෙය තාපදායක ප්‍රතික්‍රියාවකි. එනම් ඵල වල ශක්ති මට්ටම ප්‍රතික්‍රියක වලට වඩා $190 \text{ kJ mol}^{-1}$ කින් පහළින් පිහිටිය යුතුය. මෙම ලක්ෂණ නිවැරදිව පෙන්වන්නේ පළමු ප්‍රස්තාරයයි.', 'ප්‍රතික්‍රියාවේ එන්තැල්පි වෙනස ගණනය කිරීම:<br>$\Delta H = \Sigma (\text{බිඳෙන බන්ධන වල ශක්තිය}) - \Sigma (\text{සෑදෙන බන්ධන වල ශක්තිය})$<br>බිඳෙන බන්ධන: $1 \times (H-H) + 1 \times (Cl-Cl) = 430 + 240 = 670 \text{ kJ}$<br>සෑදෙන බන්ධන: $2 \times (H-Cl) = 2 \times 430 = 860 \text{ kJ}$<br>$\Delta H = 670 - 860 = -190 \text{ kJ mol}^{-1}$<br><br>$\Delta H$ සෘණ වන බැවින් මෙය තාපදායක ප්‍රතික්‍රියාවකි. එනම් ඵල වල ශක්ති මට්ටම ප්‍රතික්‍රියක වලට වඩා $190 \text{ kJ mol}^{-1}$ කින් පහළින් පිහිටිය යුතුය. මෙම ලක්ෂණ නිවැරදිව පෙන්වන්නේ පළමු ප්‍රස්තාරයයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
