INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b91349eb-d852-4ab1-a1fa-1472fb044f95', 'aa3b9f53-55ab-5237-9a53-504f5a2ebd6d', 'Pd කුඩු ඵල සාන්ද්‍රණය අඩු කිරීමට උපකාර වේ.', 'Pd කුඩු ඵල සාන්ද්‍රණය අඩු කිරීමට උපකාර වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('676a99a0-145b-4250-8932-1c8e422376cc', 'aa3b9f53-55ab-5237-9a53-504f5a2ebd6d', 'එක් ඵලයක් Pd වලට බන්ධනය වී ඵල සාන්ද්‍රණය අඩු කිරීම මගින් ප්‍රතික්‍රියාවෙහි ශීඝ්‍රතාවය වැඩි කරයි.', 'එක් ඵලයක් Pd වලට බන්ධනය වී ඵල සාන්ද්‍රණය අඩු කිරීම මගින් ප්‍රතික්‍රියාවෙහි ශීඝ්‍රතාවය වැඩි කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1107c596-3be2-44fa-b51e-9ffc80b1ec8a', 'aa3b9f53-55ab-5237-9a53-504f5a2ebd6d', 'අඩු වශයෙන් එක් ප්‍රතික්‍රියකයක් Pd වලට බන්ධනය වී අඩු සක්‍රියන ශක්තියක් සහිත විකල්ප මාර්ගයක් ඔස්සේ ප්‍රතික්‍රියාව සිදු වේ.', 'අඩු වශයෙන් එක් ප්‍රතික්‍රියකයක් Pd වලට බන්ධනය වී අඩු සක්‍රියන ශක්තියක් සහිත විකල්ප මාර්ගයක් ඔස්සේ ප්‍රතික්‍රියාව සිදු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('311d42cf-1f26-5963-b8cb-0e741ee41639', '1339fcfe-d2aa-5c59-b811-f2336da5b4f7', 26, '<p>සුදුසු තත්ත්ව යටතේ $C_2H_5OH$ මවුලයක් $CO_2$ බවට ඔක්සිකරණය කළ විට පිටවන ඉලෙක්ට්‍රෝන මවුල සංඛ්‍යාව වනුයේ,</p>', '<p>සුදුසු තත්ත්ව යටතේ $C_2H_5OH$ මවුලයක් $CO_2$ බවට ඔක්සිකරණය කළ විට පිටවන ඉලෙක්ට්‍රෝන මවුල සංඛ්‍යාව වනුයේ,</p>', NULL, 'එතනෝල් ($C_2H_6O$) අණුවේ කාබන් පරමාණුවල මධ්‍යන්‍ය ඔක්සිකරණ අංකය ගණනය කරමු:<br>$2C + 6(+1) + 1(-2) = 0 \implies 2C + 4 = 0 \implies C = -2$<br>$CO_2$ අණුවේ කාබන්හි ඔක්සිකරණ අංකය +4 වේ.<br>එක් කාබන් පරමාණුවක් -2 සිට +4 දක්වා ඔක්සිකරණය වීමේදී ඉලෙක්ට්‍රෝන 6 ක් පිට කරයි.<br>එතනෝල් මවුල 1 ක කාබන් මවුල 2 ක් ඇති බැවින්, පිටවන මුළු ඉලෙක්ට්‍රෝන මවුල සංඛ්‍යාව = $6 \times 2 = 12$ කි.<br>(අර්ධ සමීකරණය: $C_2H_5OH + 3H_2O \rightarrow 2CO_2 + 12H^+ + 12e^-$)', 'එතනෝල් ($C_2H_6O$) අණුවේ කාබන් පරමාණුවල මධ්‍යන්‍ය ඔක්සිකරණ අංකය ගණනය කරමු:<br>$2C + 6(+1) + 1(-2) = 0 \implies 2C + 4 = 0 \implies C = -2$<br>$CO_2$ අණුවේ කාබන්හි ඔක්සිකරණ අංකය +4 වේ.<br>එක් කාබන් පරමාණුවක් -2 සිට +4 දක්වා ඔක්සිකරණය වීමේදී ඉලෙක්ට්‍රෝන 6 ක් පිට කරයි.<br>එතනෝල් මවුල 1 ක කාබන් මවුල 2 ක් ඇති බැවින්, පිටවන මුළු ඉලෙක්ට්‍රෝන මවුල සංඛ්‍යාව = $6 \times 2 = 12$ කි.<br>(අර්ධ සමීකරණය: $C_2H_5OH + 3H_2O \rightarrow 2CO_2 + 12H^+ + 12e^-$)', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
